        public void DeleteCustomer(int customerMasterID)
        {
            string sql = @"
            IF NOT EXISTS (
                SELECT 1
                FROM CustomerInquiry
                WHERE CustomerMasterID = @CustomerMasterID
            )
            BEGIN
                DELETE FROM ContactDetails
                WHERE CustomerMasterID = @CustomerMasterID;

                DELETE FROM ContactPersonDetails
                WHERE CustomerMasterID = @CustomerMasterID;

                DELETE FROM LocationDetails
                WHERE CustomerMasterID = @CustomerMasterID;

                DELETE FROM CompanyDetails
                WHERE CustomerMasterID = @CustomerMasterID;

                DELETE FROM CustomerMaster
                WHERE CustomerMasterID = @CustomerMasterID;
            END";

            using (SqlConnection con = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.Parameters.AddWithValue("@CustomerMasterID", customerMasterID);
                    con.Open();
                    cmd.ExecuteNonQuery();
                }
            }

        }
