        public int UpdateTestResultDetailsChemical(DAL.CM obj)
        {

            string formattedIssueDate = obj.issueDate.ToString("yyyy-MM-dd");
            string formattedStartDate = obj.analysisStartingDate.ToString("yyyy-MM-dd");
            string formattedCompletionDate = obj._analysisCompletionDate.ToString("yyyy-MM-dd");

            string sQuery = @"Update TestResultDetails set IssueDate = '" + formattedIssueDate + "'" +
                       ", ULRNo = '" + obj.ulrNo +
                       "', AnalysisStartingDate = '" + formattedStartDate + "'" +
                       ", AnalysisCompletionDate = '" + formattedCompletionDate + "'" +
                        ", NameOfProduct = '" + obj.nameOfProduct +
                        "', DateOfMfg = null" +
                        ", DateOfExp = null" +
                        ", SampleQuality = '" + obj.sampleQuality +
                        "', SampleCondition = '" + obj.samplingCondition +
                        "', TestRequired = '" + obj.testRequired +
                        "', Sampling = '" + obj.sampling +
                        "', SamplingMethod = '" + obj.SamplingMethod +
                        "', TestReportNo = '" + obj.TestReportNo +
                        "', CustomerReference = '" + obj.CustomerReference +
                        "', Remarks = '" + obj.remarks +
                        "', FinalTestResult = '" + obj.FinalTestResult +
                         "' where SampleID =" + obj.sampleId;
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand(sQuery, _sCon);
                {
                    _sCon.Open();
                    int modified = cmd.ExecuteNonQuery();
                }
            }

            return modified;
        }

