        public DataTable getCustomerInquiryDetails(int InquiryID)
        {
            sQuery = @"select ci.inquiryid,cd.firstname + '' + cd.lastname as customername,d.DepartmentName, pg.ProductGroupName,p.subgroupname,
                                e.employeename,s.supervisorname,ci.created as EnquiryDate,(select top 1 issuedate from testresultdetails 
                                where sampleid=(select s.sampleid from sampledetails s inner join customerinquiry ci on s.id= ci.sampleid and ci.inquiryid=" + InquiryID + ") order by issuedate desc) as ReportDate,RequestNo " +
                               @" from customerdetails cd 
                                inner join customerinquiry ci on cd.CustomerMasterId = ci.CustomerMasterId 
                                inner join department d on d.departmentid=ci.departmentid
                                inner join ProductSubGroup p on ci.productCategoryID = p.SubGroupID  
                                inner join ProductGroup pg on p.productgroupid = pg.productgroupid
                                inner join sampledetails sp on sp.id = ci.sampleid
                                inner join allocation a on a.sampleid = ci.sampleid
                                inner join supervisor s on a.employeeid = s.employeeid 
                                inner join employees e on a.employeeid=e.id
                                where ci.inquiryid=" + InquiryID + " and cd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                             @" union
                                select ci.inquiryid,cd.companyname as customername,d.DepartmentName, pg.ProductGroupName,p.subgroupname,
                                e.employeename,s.supervisorname,ci.created as EnquiryDate,(select top 1 issuedate from testresultdetails 
                                where sampleid=(select s.sampleid from sampledetails s inner join customerinquiry ci on s.id= ci.sampleid and ci.inquiryid=" + InquiryID + ") order by issuedate desc) as ReportDate,RequestNo " +
                            @"  from companydetails cd 
                                inner join customerinquiry ci on cd.CustomerMasterId = ci.CustomerMasterId 
                                inner join department d on d.departmentid=ci.departmentid
                                inner join ProductSubGroup p on ci.productCategoryID = p.SubGroupID  
                                inner join ProductGroup pg on p.productgroupid = pg.productgroupid
                                inner join sampledetails sp on sp.id = ci.sampleid
                                inner join allocation a on a.sampleid = ci.sampleid
                                inner join supervisor s on a.employeeid = s.employeeid 
                                inner join employees e on a.employeeid=e.id
                                where ci.inquiryid=" + InquiryID + " and cd.OrganizationID =1";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
