        public DataTable getCustomerList()
        {
            sQuery = @"select c.customermasterid,c.companyid as CustomerId,c.companyname,
                         CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM CustomerInquiry ci
                                    WHERE ci.CustomerMasterID = c.CustomerMasterID
                                )
                                THEN 1
                                ELSE 0
                            END AS HasEnquiries
                        from companydetails c 
                        where c.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                      @" GROUP BY c.customermasterid,c.companyid,companyname ORDER BY companyname asc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable getCustomerList(string search, string customerType)
        {
            if (customerType == "Individual")
            {
                sQuery = @"select c.customermasterid,c.customerid,Title , Firstname , MiddleName , Lastname,
                             CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM CustomerInquiry ci
                                    WHERE ci.CustomerMasterID = c.CustomerMasterID
                                )
                                THEN 1
                                ELSE 0
                            END AS HasEnquiries
                            from customerdetails c 
                            where c.firstname like '%" + search + "%' or c.middlename like '%" + search +
                            "%' or c.lastname like '%" + search + "%' and c.OrganizationID =1";
            }
            else
            {
                sQuery = @"select c.customermasterid,companyid as customerid,companyname,
                             CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM CustomerInquiry ci
                                    WHERE ci.CustomerMasterID = c.CustomerMasterID
                                )
                                THEN 1
                                ELSE 0
                            END AS HasEnquiries
                            from companydetails c 
                            where companyname like '%" + search + "%' and c.OrganizationID =1";
            }
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
