        public DataTable getCustomerDetails(string customerType, string Inv, int dummy)
        {
            if (Inv.Length > 0)
            {

                if (customerType == "Individual")
                {
                    sQuery = @"select i.InvoiceId,i.InvoiceNumber,c.customermasterid,c.customerid,Title , Firstname , MiddleName , Lastname,
                            AddressLine1 + ' ' + AddressLine2 + ' ' + AddressLine3 + ' ' + country+ ' ' + state+ ' ' + district+ ' ' + city+ ' ' + pincode  as Address, 
                            LocationAddressType from customerdetails c 
                            left join locationdetails l on c.customerid = l.CustomerId
                            inner join Invoices i on i.customerid = c.CompanyId
                            where InvoiceID in(" + Inv + ")";
                }
                else
                {
                    sQuery = @"select distinct i.InvoiceId,i.InvoiceNumber,c.customermasterid,c.CompanyId,companyname,tradingname,location,
							Title + '. '+ FirstName + ' ' + LastName as ContactPerson, Mobile,Email,
                            AddressLine1 + ' ' + AddressLine2 + ' ' + AddressLine3 + ' ' + country+ ' ' + state+ ' ' + district+ ' ' + city+ ' ' + pincode  as Address, 
                            LocationAddressType from companydetails c 
							left join ContactDetails cd on cd.CustomerMasterId = c.CustomerMasterId
							left join ContactPersonDetails cp on cp.PersonId = cd.PersonId
                            left join locationdetails l on c.customermasterid = l.customermasterid 
							inner join Invoices i on i.CompanyID = c.CustomerMasterId
                            where InvoiceID in(" + Inv + ")";
                }
            }

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
