        public DataTable getInquiryDetails(string Dept, string Option)
        {
            switch (Dept)
            {
                case "Lab":
                    if (Option == "1005")
                    {
                        sQuery = @"select c.inquiryid, c.created,i.statusname, c.CustomerId,
                            c.InquiryDetail,cd.CustomerMasterId,cd.FirstName as customername,
                            EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.EmployeeDepartmentName as DepartmentName, 
                            RequestNo,QuotationStatus from CustomerInquiry c 
                           inner join EmployeeDepartment d on d.DepartmentID = c.DepartmentID
                            inner join inquirystatus i on c.inquiryStatusID = i.InquiryStatusId  
                            inner join CustomerDetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                             union " +
                             @" select c.inquiryid,c.created,i.statusname,c.CustomerId,c.InquiryDetail,
                            cd.CustomerMasterId,cd.companyname as customername,
                            EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.EmployeeDepartmentName as DepartmentName, 
                            RequestNo,QuotationStatus from CustomerInquiry c 
                            inner join inquirystatus i on c.inquiryStatusID = i.InquiryStatusId  
                            inner join companydetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                           inner join EmployeeDepartment d on d.DepartmentID = c.DepartmentID
                            order by c.inquiryid desc";
                    }
                    else
                    {
                        sQuery = @"select c.inquiryid, c.created,i.statusname, c.CustomerId,
                            c.InquiryDetail,cd.CustomerMasterId,cd.FirstName as customername,
                            EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.EmployeeDepartmentName as DepartmentName, 
                            RequestNo,QuotationStatus from CustomerInquiry c 
                           inner join EmployeeDepartment d on d.DepartmentID = c.DepartmentID
                            inner join inquirystatus i on c.inquiryStatusID = i.InquiryStatusId  
                            inner join CustomerDetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                            where d.DepartmentID ='" + Option + "' union " +
                            @" select c.inquiryid,c.created,i.statusname,c.CustomerId,c.InquiryDetail,
                            cd.CustomerMasterId,cd.companyname as customername,
                            EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.EmployeeDepartmentName as DepartmentName, 
                            RequestNo,QuotationStatus from CustomerInquiry c 
                            inner join inquirystatus i on c.inquiryStatusID = i.InquiryStatusId  
                            inner join companydetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                           inner join EmployeeDepartment d on d.DepartmentID = c.DepartmentID
                            where d.DepartmentID ='" + Option + "' order by c.inquiryid desc";
                    }

                    break;
                case "Certification":
                    if (Option == "1005")
                    {
                        sQuery = @"select c.inquiryid, c.created,i.CalibrationStatus as statusname, c.CustomerId,
                            c.InquiryDetail,cd.CustomerMasterId,cd.FirstName as customername,
                              EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.DepartmentName, 
                              RequestNo,qm.QuotationMasterID,QuotationStatus from CustomerInquiry c 
                              inner join CalibrationStatus i on c.inquiryStatusID = i.CalibrationStatusID  
                              inner join CustomerDetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                              inner join Department d on d.DepartmentID = c.DepartmentID
                              left join QuotationMaster qm on qm.EnquiryId = c.InquiryId
                         union
                              select c.inquiryid,c.created,i.CalibrationStatus as statusname,c.CustomerId,
                              c.InquiryDetail,cd.CustomerMasterId,cd.companyname as customername,
                              EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.DepartmentName, 
                              RequestNo,qm.QuotationMasterID,QuotationStatus from CustomerInquiry c 
                              inner join CalibrationStatus i on c.inquiryStatusID = i.CalibrationStatusID  
                              inner join companydetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                            inner join Department d on d.DepartmentID = c.DepartmentID
                            left join QuotationMaster qm on qm.EnquiryId = c.InquiryId order by c.inquiryid desc";
                    }
                    else
                    {
                        sQuery = @"select c.inquiryid, c.created,i.CalibrationStatus as statusname, c.CustomerId,
                            c.InquiryDetail,cd.CustomerMasterId,cd.FirstName as customername,
                              EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.DepartmentName, 
                              RequestNo,qm.QuotationMasterID,QuotationStatus from CustomerInquiry c 
                              inner join CalibrationStatus i on c.inquiryStatusID = i.CalibrationStatusID  
                              inner join CustomerDetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                              inner join Department d on d.DepartmentID = c.DepartmentID
                              left join QuotationMaster qm on qm.EnquiryId = c.InquiryId
                              union
                              select c.inquiryid,c.created,i.CalibrationStatus as statusname,c.CustomerId,
                              c.InquiryDetail,cd.CustomerMasterId,cd.companyname as customername,
                              EnquirySeries,ReportFormat,d.DepartmentID as EnquiryDept,d.DepartmentName, 
                              RequestNo,qm.QuotationMasterID,QuotationStatus from CustomerInquiry c 
                              inner join CalibrationStatus i on c.inquiryStatusID = i.CalibrationStatusID  
                              inner join companydetails cd on cd.CustomerMasterId = c.CustomerMasterId 
                            inner join Department d on d.DepartmentID = c.DepartmentID
                            left join QuotationMaster qm on qm.EnquiryId = c.InquiryId order by c.inquiryid desc";
                    }

                    break;
                default:
                    break;
            }

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable[] GetCustomerInquiry()
        {
            string sQuery = "";

            DataTable dtNewInquiry = new DataTable();
            DataTable dtNewCustomer = new DataTable();
            DataTable dtAssigned = new DataTable();
            DataTable dtCompleted = new DataTable();

            int newInquiry = 1; int assignedInquiry = 19; int completedInquiry = 20;

            sQuery = @"select distinct ci.CustomerId from CustomerInquiry ci 
                            inner join customerdetails cd on cd.CustomerMasterId = ci.CustomerMasterId where cd.customerid 
                            not in(select customerid from customerrequestdetails) " +
                         @"  union
                            select distinct ci.CustomerId as customerid from CustomerInquiry ci 
                            inner join companydetails cd on cd.CustomerMasterId = ci.CustomerMasterId  
                            where cd.companyid not in(select customerid from customerrequestdetails) ";

            dtNewCustomer = GetDataUsingQuery(sQuery);

            string sQuery1 = @"Select inquiryid from CustomerInquiry ci 
                                inner join CustomerDetails cd on ci.CustomerMasterId = cd.CustomerMasterId where ci.InquiryStatusId = ";
            string sQuery2 = @" union
                                Select inquiryid from CustomerInquiry ci 
                                inner join companydetails cd on ci.CustomerMasterId = cd.CustomerMasterId where ci.InquiryStatusId = ";

            sQuery = sQuery1 + newInquiry + sQuery2 + newInquiry;
            dtNewInquiry = GetDataUsingQuery(sQuery);

            sQuery = sQuery1 + assignedInquiry + sQuery2 + assignedInquiry;
            dtAssigned = GetDataUsingQuery(sQuery);

            sQuery = sQuery1 + completedInquiry + sQuery2 + completedInquiry;
            dtCompleted = GetDataUsingQuery(sQuery);

            return new DataTable[] { dtNewInquiry, dtNewCustomer, dtAssigned, dtCompleted };
        }
