        public DataTable BindInquiryCustomer(int InquiryId)
        {
            if (HttpContext.Current.Session["OrganizationID"] == null) { HttpContext.Current.Session["OrganizationID"] = 1; }
            sQuery = @"select top 1 ci.CustomerId,ci.InquiryId,ci.created,ci.standardID,ci.categoryTypeStdTest,ci.testList,(cd.Title+' '+cd.firstname) as customername, null as VAT,ci.ReportID,
                        l.*
