                        inner join CustomerInquiry ci on ci.CustomerMasterID = cd.CustomerMasterID 
                        inner join LocationDetails l on l.CustomerMasterID = cd.CustomerMasterID 
                        where ci.InquiryId = '" + InquiryId + "'" +
                     @" union 
                        select top 1 ci.CustomerId,ci.InquiryId,ci.created,ci.standardID,ci.categoryTypeStdTest,ci.testList,cm.companyname as customername,cm.VAT,ci.ReportID,
                        l.*
                        from companydetails cm 
                        inner join CustomerInquiry ci on ci.CustomerMasterID = cm.CustomerMasterID 
                        inner join LocationDetails l on l.CustomerMasterID = ci.CustomerMasterID 
                        where ci.InquiryId = '" + InquiryId + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
