        public DataTable getCustomerCRFSampleDetails(int InquiryID)
        {
            DataTable dt = new DataTable();
            //string sQuery = @"select distinct CustomerCRFSampleId,CustomerRequestID,SampleName,SampleType,BatchNo,
            //                    TestParameter,TestSubParameter,TestMethod,ExpectedValue,Dimensions,Specification,
            //                    SizeofSample,Remarks from CustomerCRFSampleDetails 
            //                    where InquiryId='" + InquiryID + "' and OrganizationID =1";
            string sQuery = @"select CASE
                                        WHEN TestSubSubParameter = '' THEN TestSubParameter 
	                                    ELSE TestSubParameter + ' - ' + TestSubSubParameter	
                                    END AS TestSubParameter,* from CustomerCRFSampleDetails cs
                                inner join CustomerInquiry ci on ci.InquiryId = cs.InquiryId
                                inner join CompanyDetails cd on cd.CustomerMasterId = ci.customermasterid
                                inner join additionaldetails a on a.requestid=cs.CustomerRequestId
                                where cs.InquiryId=" + InquiryID + " order by CustomerCRFSampleId asc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
