                                inner join crfclonelist ci on cd.clonecrfsampleid = ci.clonecrfsampleid
								inner join InquiryStatus s on s.inquirystatusid= cd.samplestatus
								left join testresults t on t.CRFSampleID = cd.CRFSampleId
                               left join testParameter tp on tp.TestParameterID = cd.TestParameterID
								left join testsubParameter ts on ts.TestSubParameterId = cd.TestSubParameterId
                                inner join sampledetails sd on ci.sampleid= sd.id and sd.id = '" + sampleID + "'";
            dt = GetDataUsingQuery(sQuery);

            return dt;
        }
        public void clearTable(string tab)
        {
            try
            {
                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand command = new SqlCommand("DELETE FROM " + tab, _sCon))
                    {
                        command.ExecuteNonQuery();
                    }
                }
            }
            catch (SystemException ex)
            {

            }
        }
        public DataTable GetCRFListForAllocation(int sampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"select 
                                CASE WHEN isnull(cd.TestSubSubParameter,'') = '' THEN
                                      CASE 
		                                  WHEN isnull(cd.TestSubParameter,'') ='' THEN
			                                tp.TestParameter
		                                  ELSE
			                                tp.TestParameter + '-' + ts.TestSubParameter
		                                  END
	                                ELSE 
		                                tp.TestParameter + '-' + isnull(ts.TestSubParameter,'') + '-' +isnull(tss.TestSubSubParameter,'')
                                END AS TestItem,
                                unitofmeasurement,
                                *,e1.Employeename as Supervisor 
									from crfsampledetails cd 
                                inner join CRFClonelist ci on cd.clonecrfsampleid = ci.clonecrfsampleid
								inner join CustomerInquiry c on c.InquiryId = cd.InquiryId
								inner join InquiryStatus s on s.inquirystatusid= ci.CRFStatusID
								inner join sampledetails sd on ci.sampleid= sd.id and sd.sampleid= '" + sampleID + "'" +
                            @"  and sd. OrganizationID ='1'
								left join Employees e on e.EmployeeID = cd.EmployeeId	
								left join Employees e1 on e1.EmployeeID = cd.SupervisorID
                                left join Organization o on o.ID = cd.LocationID
								left join TestParameter tp on tp.TestParameterID = cd.TestParameterID
								left join TestSubParameter ts on ts.TestSubParameterID = cd.TestSubParameterID
								left join TestSubSubParameter tss on tss.TestSubSubParameterID = cd.TestSubSubParameterID
                                order by tp.Position asc";


            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
