        public DataTable getCRFByInquiryStatus(string InquiryStatusID, string search)
        {
            sQuery = @"select c.inquiryid,i.statusname,c.created,i.statusname,c.CustomerId,c.InquiryDetail,cd.CustomerMasterId,cd.FirstName as customername from InquiryStatus i
                            inner join CustomerInquiry c on c.InquiryStatusID = i.InquiryStatusID
                            inner join CustomerDetails cd on c.CustomerMasterId = cd.CustomerMasterId
                            where cd.firstname like '%" + search + "%' or cd.middlename like '%" + search + "%' or cd.lastname like '%" + search + "%' and c.inquirystatusid in(" + InquiryStatusID + ") and c.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                            @" union
                            select c.inquiryid,i.statusname,c.created,i.statusname,c.CustomerId,c.InquiryDetail,cd.CustomerMasterId,cd.companyname as customername from InquiryStatus i
                            inner join CustomerInquiry c on c.InquiryStatusID = i.InquiryStatusID
                            inner join CompanyDetails cd on c.CustomerMasterId = cd.CustomerMasterId
                            where companyname like '%" + search + "%' and c.inquirystatusid in(" + InquiryStatusID + ") and c.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                            "order by c.InquiryID desc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
