							c.created,i.statusname,c.CustomerId,c.InquiryDetail,cd.CustomerMasterId,CompanyName,RequestNo, WorkOrderNumber, cr.sampleID,d.EmployeeDepartmentName as DepartmentName
							from CustomerInquiry c 
							inner join CompanyDetails cd on c.CustomerMasterId = cd.CustomerMasterId 
							inner join InquiryStatus i on c.InquiryStatusId = i.InquiryStatusId 
							left join CRFCloneList cr on cr.EnquiryID = c.InquiryId 
							left join InquiryStatus i1 on cr.CRFStatusID = i1.InquiryStatusId
                            left join QuotationMaster qm on qm.EnquiryId = c.InquiryId
                            inner join EmployeeDepartment d on d.DepartmentID = c.DepartmentID
							where d.DepartmentID='" + DepartmentID + "' and " + InquiryStatus + "  and c.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'  order by c.InquiryID desc";
            dt = GetDataUsingQuery(sQuery);
