        public int checkCustomerUIDExists(int CustomerUID)
        {
            string ErrMsg = string.Empty;
            int exists = 0;
            try
            {

                sQuery = "SELECT count(*) FROM CustomerMaster WHERE CustomerUID = " + CustomerUID +
                         " and OrganizationID =1";
                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        exists = Convert.ToInt32(cmd.ExecuteScalar());
                    }
                }
                return exists;
            }
            catch (Exception ex)
            {
                ErrMsg = ex.Message;
                //HttpContext.Current.Response.Redirect("~/Error.aspx", false);
                return 0;
            }
        }
