        public int AddProductGroup(DAL.CM obj)
        {
            int modified = 0;

            string sQuery = "";
            sQuery = @"Select * from ProductGroup where ProductGroupName='" + obj.GroupName + "'";
            dt = GetDataUsingQuery(sQuery);
            if (dt.Rows.Count > 0)
            {
                modified = 0;
            }
            else
            {
                //Start Reseed to avoid identity jump
                int prevIdentity = GetReseedIdentity("ProductGroup", "ProductGroupID");
                ReseedIdentity("ProductGroup", prevIdentity);
                //End Reseed to avoid identity jump

                sQuery = "insert into ProductGroup (ProductGroupName,DepartmentId, OrganizationID) output INSERTED.ProductGroupID values (@ProductGroupName,@DepartmentId,@OrganizationID)";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@ProductGroupName", obj.GroupName);
                        cmd.Parameters.AddWithValue("@DepartmentId", obj.departmentID);
                        cmd.Parameters.AddWithValue("@OrganizationID", obj.OrganizationID);
                        _sCon.Open();
                        modified = (int)cmd.ExecuteScalar();



                    }
                }
            }
            return modified;
        }
        public int AddProductSubGroup(DAL.CM obj)
        {
            int modified = 0;

            string sQuery = "";
            sQuery = @"Select * from ProductSubGroup where SubGroupName='" + obj.subGroup + "' and DepartmentID='" + obj.departmentID + "'";
            dt = GetDataUsingQuery(sQuery);
            if (dt.Rows.Count > 0)
            {
                modified = 0;
            }
            else
            {
                //Start Reseed to avoid identity jump
                int prevIdentity = GetReseedIdentity("ProductSubGroup", "SubGroupID");
                ReseedIdentity("ProductSubGroup", prevIdentity);
                //End Reseed to avoid identity jump

                sQuery = "insert into ProductSubGroup (SubGroupName,ProductGroupID,DepartmentId,sampleCategory,OrganizationID) output INSERTED.ProductGroupID values (@SubGroupName,@ProductGroupID,@DepartmentId,@sampleCategory,@OrganizationID)";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@SubGroupName", obj.subGroup);
                        cmd.Parameters.AddWithValue("@ProductGroupID", obj.groupId);
                        cmd.Parameters.AddWithValue("@DepartmentId", obj.departmentID);
                        cmd.Parameters.AddWithValue("@sampleCategory", obj.sampleCategoryID);
                        cmd.Parameters.AddWithValue("@OrganizationID", obj.OrganizationID);

                        _sCon.Open();
                        modified = (int)cmd.ExecuteScalar();
                    }
                }
            }
            return modified;
        }
        public int AddTestMethod(DAL.CM obj)
