            string sQuery = "";
            sQuery = @"Select distinct * from TestMethod where TestMethod='" + obj.testMethod + "'  and OrganizationID =1";
            dt = GetDataUsingQuery(sQuery);
            if (dt.Rows.Count > 0)
            {
                modified = 0;
            }
            else
            {
                //Start Reseed to avoid identity jump
                int prevIdentity = GetReseedIdentity("TestMethod", "TestMethodID");
                ReseedIdentity("TestMethod", prevIdentity);
                //End Reseed to avoid identity jump

                sQuery = "insert into TestMethod (TestMethod,OrganizationID) output INSERTED.TestMethodID values (@TestMethod,@OrganizationID)";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@TestMethod", obj.testMethod);
                        cmd.Parameters.AddWithValue("@OrganizationID", obj.OrganizationID);
                        modified = (int)cmd.ExecuteScalar();

                    }
                }
            }
            return modified;
        }
        public int AddTestParameter(DAL.CM obj)
        {
            int modified = 0;

            string sQuery = "";
            sQuery = @"Select * from TestParameter where TestParameter='" + obj.testParameter + "'";
            dt = GetDataUsingQuery(sQuery);
            if (dt.Rows.Count > 0)
            {
                modified = 0;
            }
            else
            {
                //Start Reseed to avoid identity jump
                int prevIdentity = GetReseedIdentity("TestParameter", "TestParameterID");
                ReseedIdentity("TestParameter", prevIdentity);
                //End Reseed to avoid identity jump

                sQuery = "insert into TestParameter (TestParameter,OrganizationID) output INSERTED.TestParameterID values (@TestParameter,@OrganizationID)";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@TestParameter", obj.testParameter);
                        cmd.Parameters.AddWithValue("@OrganizationID", obj.OrganizationID);
                        modified = (int)cmd.ExecuteScalar();



                    }
                }
            }
            return modified;
        }
