        public DataTable getParameter(DAL.CM obj, int level)
        {
            switch (level)
            {
                case 1:
                    sQuery = @"select tp.testparameterID,tp.testparameter,
                                tp.protocol,tp.uomname,tp.uomid,tp.RequirementID,tp.LOD,tp.LOQ
                                from TestParameter tp where tp.testparameter='" + obj.testParameter + "' and tp.uomname='" + obj.UOMName + "'";
                    break;
                case 2:
                    sQuery = @"select tp.testparameterID,tp.testparameter,
                                 ts.testsubparameterid,ts.testsubparameter,
                                 ts.protocol,ts.uomname,ts.uomid,tp.RequirementID,ts.LOD,ts.LOQ
                                 from TestParameter tp inner join TestSubParameter ts on ts.testparameterID = tp.testparameterID where tp.testparameter='" + obj.testParameter + "' and testsubparameter='" + obj.testSubParameter + "' and ts.uomname='" + obj.UOMName + "'";
                    break;
                case 3:
                    sQuery = @"select tp.testparameterID,tp.testparameter,
                                ts.testsubparameterid,ts.testsubparameter,
                                tss.testsubsubparameterid,tas.testsubsubparameter,tss.protocol,tss.uomname,tss.uomid,tp.RequirementID,tss.LOD,tss.LOQ
                                from TestParameter tp inner join TestSubParameter ts on ts.testparameterID = tp.testparameterID inner join TestSubSubParameter tss on tss.TestSubParameterID=ts.TestSubParameterID where tp.testparameter='" + obj.testParameter + "' and  testsubparameter='" + obj.testSubParameter + "' and tss.TestSubSubParameter='" + obj.testSubSubParameter + "' and tss.uomname='" + obj.UOMName + "'";
                    break;
                default: break;
            }
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
