        public DataTable GetDepartmentSampleDetails(string DepartmentID, int year, int month)
        {
            DataTable dt = new DataTable();
            string sQuery = @"Select s.*,cr.Clonecrfsampleid,cr.enquiryId as InquiryID,i.StatusName,c.departmentid,RequestNo  from SampleDetails s 
                                inner join CRFcloneList cr on s.id = cr.sampleID
								inner join customerinquiry c on c.InquiryId = cr.EnquiryID  
                                inner join inquirystatus i on i.inquirystatusid = cr.CRFStatusID
								inner join employeedepartment ed on ed.departmentid = c.departmentid
                                 where ed.departmentid in(" + DepartmentID + ") and s.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' and SampleStatus in (14,15,17,18) and year(s.created)=" + year + " and month(s.created)=" + month + " order by s.id desc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
