        public DataTable GetAllocation(int EmployeeId, int roleID, int year)
        {
            DataTable dt = new DataTable();
            string sQuery = "";
            switch (roleID)
            {
                case 2:
                    sQuery = @"select c.CloneCRFSampleID,sd.SampleId,sd.sampleidseries,a.AllocationId,st.StatusName from Allocation a 
                                    inner join SampleDetails sd on sd.Id = a.SampleId 
								    inner join crfclonelist c on c.sampleid = sd.id 
								    inner join InquiryStatus st on st.InquiryStatusId = c.CRFStatusID
                                    inner join supervisor s on a.id = s.employeeid and and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' supervisorid=" + EmployeeId + " and sd.samplestatus in(29," +
                                 @" 25,15,14,13,17,16,20,26,12,27,18,19) and year(a.created)=" + year;
                    dt = GetDataUsingQuery(sQuery);
                    break;
                case 3:
                    sQuery = @"select AllocatedEmployeeID from Employees where ID=" + EmployeeId;
                    dt = GetDataUsingQuery(sQuery);
                    if (dt.Rows.Count > 0)
                    {
                        sQuery = @"select c.CloneCRFSampleID,sd.SampleId,sd.sampleidseries,a.AllocationId,st.StatusName from Allocation a 
                                  inner join SampleDetails sd on sd.Id = a.SampleId 
								  inner join crfclonelist c on c.sampleid = sd.id 
								  inner join InquiryStatus st on st.InquiryStatusId = c.CRFStatusID 
                                  inner join Employees e on e.ID=a.EmployeeID
                                  where a.employeeid in(" + dt.Rows[0]["AllocatedEmployeeID"].ToString() + ") and st.StatusName='Allocated for Testing' and year(a.created)=" + year;
                    }


                    //            sQuery = @"select c.CloneCRFSampleID,sd.SampleId,sd.sampleidseries,a.AllocationId,st.StatusName from Allocation a 
                    //                        inner join SampleDetails sd on sd.Id = a.SampleId 
                    //inner join crfclonelist c on c.sampleid = sd.id 
                    //inner join InquiryStatus st on st.InquiryStatusId = c.CRFStatusID where a.employeeid='" + EmployeeId + "' and st.StatusName='Allocated for Testing'";
                    dt = GetDataUsingQuery(sQuery);
                    break;
                default: break;
            }
            return dt;
        }
        public DataTable GetAllocation(int EmployeeId, int roleID, int year, int month)
        {
            DataTable dt = new DataTable();
            string sQuery = "";
            switch (roleID)
            {
                case 2:
                    sQuery = @"select distinct c.CloneCRFSampleID,sd.ID,sd.SampleId,sd.sampleidseries,
                                    st.StatusName,sd.id, ci.InquiryID  ,
                                    sd.ReceivedDate,sd.DeliveryDate,ServiceRequired
									from SampleDetails sd
                                    inner join crfclonelist c on c.sampleid = sd.id 
                                    inner join CustomerInquiry ci on ci.InquiryId = c.EnquiryID
                                    inner join InquiryStatus st on st.InquiryStatusId = c.CRFStatusID 
									inner join CRFSampleDetails cs on cs.CloneCRFSampleID = c.CloneCRFSampleID 
                                    left join AdditionalDetails ad on ad.InquiryID = cs.InquiryId
								 inner join supervisor s on cs.EmployeeId = s.employeeid and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' and cs.supervisorid=" + EmployeeId +
                              @" and sd.samplestatus in(29,25,15,14,13,17,16,20,26,12,27,18,19) and year(sd.created)=" + year +
                              @" and month(sd.created)= " + month;
                    dt = GetDataUsingQuery(sQuery);
                    break;
                //       case 3:
                //           sQuery = @"select AllocatedEmployeeID from Employees where ID=" + EmployeeId;
                //           dt = GetDataUsingQuery(sQuery);
                //           if (dt.Rows.Count > 0)
                //           {
                //               sQuery = @"select distinct c.CloneCRFSampleID,sd.ID,sd.SampleId,sd.sampleidseries,st.StatusName,id, ci.InquiryID,
                //sd.ReceivedDate,sd.DeliveryDate,ServiceRequired from crfsampledetails cs
                //                           inner join CustomerInquiry ci on ci.InquiryId = cs.InquiryID     
                //                           inner join crfclonelist c on c.EnquiryID = cs.InquiryID
                //                           inner join SampleDetails sd on sd.id = c.sampleID
                //                           inner join InquiryStatus st on st.InquiryStatusId = cs.samplestatus 
                //                           left join AdditionalDetails ad on ad.InquiryID = cs.InquiryId
                //                           where (st.StatusName='Allocated for Testing' or st.StatusName='Re-Test') and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                //                         " and year(sd.created)=" + year + " and month(sd.created)=" + month + " and cs.EmployeeID=" + EmployeeId;
                //           }
                case 3:
                    sQuery = @"SELECT distinct cl.CloneCRFSampleID,csd.EmployeeId,st.StatusName, sd.ID,sd.SampleId,sd.sampleidseries,st.StatusName,id, cl.EnquiryID as InquiryID,
									sd.ReceivedDate,sd.DeliveryDate,ServiceRequired 
                                    FROM SampleDetails sd
                        INNER JOIN CRFCloneList cl ON sd.ID = cl.SampleID
                        INNER JOIN CRFSampleDetails csd ON cl.CloneCRFSampleID = csd.CloneCRFSampleID
                        INNER JOIN InquiryStatus st on st.InquiryStatusId = csd.samplestatus 
                        inner join CustomerInquiry cii on cii.InquiryId =  cl.EnquiryID
                        left join AdditionalDetails ad on ad.InquiryID = cl.EnquiryID
                        WHERE csd.EmployeeId = " + EmployeeId + " AND YEAR(csd.Created) = " + year + " AND MONTH(csd.Created) = " + month + "  AND (st.StatusName='Allocated for Testing' or st.StatusName='Re-Test') ";

                    dt = GetDataUsingQuery(sQuery);
                    break;
                default: break;
            }
            return dt;
        }
