                                inner join employees e on e.ID = cs.employeeid 
								inner join Employees e1 on e1.ID = cs.SupervisorID	
                                left join Parameter tp on tp.TestParameterID = cs.TestParameterID
							    where c.CloneCRFSampleID='" + CloneCRFSampleID + "' and s.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' order by cs.CRFSampleId asc";
