        public DataTable GetTestReportDetails1(string SampleId)
        {
            DataTable dt = new DataTable();
            string sQuery = @"Select top 1 c.CloneCRFSampleID,sd.ID,sd.ReceivedDate,sd.SampleId,sd.sampleidseries,sd.Created,d.DepartmentName,
                                    pg.productgroupname,pc.subgroupname,cs.BatchNo,cs.SampleName,cs.SizeOfSample,
                                    ci.inquiryid,cs.sizeofsample,cs.created as CRFdate,cs.TestParameter,cs.TestMethod,ci.created as inquiryDate,
                                    TransportAndReceiptTemp,Humidity,Employeename as SamplingBy,sd.Remarks as samplecondition,ci.ReportID from sampledetails sd
									inner join CRFCloneList c on sd.Id = c.sampleid
									inner join CustomerInquiry ci on ci.InquiryId = c.EnquiryID
                                    inner join AdditionalDetails a on a.inquiryid=ci.inquiryid
									inner join Department d on ci.DepartmentId = d.DepartmentId                                     
									inner join productsubgroup pc on ci.productcategoryid = pc.SubGroupID
                                    inner join productgroup pg on pg.productgroupid = pc.productgroupid
									inner join CustomerDetails cd on cd.customermasterid = ci.customermasterid 
									inner join CRFSampleDetails cs on cs.CloneCRFSampleID = c.CloneCRFSampleID
                                    inner join Employees e on e.id=sd.SampleVerifiedBy
									where sd.ID =" + SampleId +
                                @" UNION 
                                    Select top 1 c.CloneCRFSampleID,sd.ID,sd.ReceivedDate,sd.SampleId,sd.sampleidseries,sd.Created,d.DepartmentName,
                                    pg.productgroupname,pc.subgroupname,cs.BatchNo,cs.SampleName,cs.SizeOfSample,ci.inquiryid,
                                    cs.sizeofsample,cs.created as CRFdate,cs.TestParameter,cs.TestMethod,ci.created as inquiryDate,
                                    TransportAndReceiptTemp,Humidity,Employeename as SamplingBy,sd.Remarks as samplecondition,ci.ReportID from sampledetails sd
									inner join CRFCloneList c on sd.Id = c.sampleid
									inner join CustomerInquiry ci on ci.InquiryId = c.EnquiryID
                                    inner join AdditionalDetails a on a.inquiryid=ci.inquiryid
									inner join Department d on ci.DepartmentId = d.DepartmentId 
									inner join productsubgroup pc on ci.productcategoryid = pc.SubGroupID
                                    inner join productgroup pg on pg.productgroupid = pc.productgroupid
									inner join CompanyDetails cd on cd.customermasterid = ci.customermasterid 
									inner join CRFSampleDetails cs on cs.CloneCRFSampleID = c.CloneCRFSampleID
                                    inner join Employees e on e.id=sd.SampleVerifiedBy
									where sd.ID =" + SampleId + " order by cs.created desc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

        public DataTable GetTestReportDetails2(string SampleId)
        {
            DataTable dt = new DataTable();
            sQuery = @"Select  distinct cd.companyid,(cd.CompanyName) as CustomerName, (cp.Title+' '+ cp.FirstName) as ContactPerson,
                                        cn.Mobile,cn.Email,ld.AddressLine1,ld.AddressLine2,ld.AddressLine3,ld.city,ld.taluka,
                                        ld.District,ld.pincode,ld.state,ld.country,ci.ReportID 
                                        from CustomerRequestDetails cr 
                                        inner join CustomerInquiry ci on cr.inquiryid = ci.inquiryid
                                        left join contactpersondetails cp on cp.PersonId = cr.ContactPerson
                                        left join ContactDetails cn on cn.personid = cr.ContactPerson
                                        inner join CRFSampleDetails cs on cs.inquiryid = cr.inquiryid
                                        inner join CRFCloneList c on c.CloneCRFSampleID = cs.CloneCRFSampleID
                                        inner join CompanyDetails cd on cd.CustomerMasterID=cp.CustomerMasterID   
                                        left join locationdetails ld on ld.customermasterid = cd.customermasterid
                                        inner join sampledetails sd on sd.id = c.sampleid where sd.ID=" + SampleId + " and ci.customermasterid = cd.customermasterid";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

