        public DataTable GetTestReportResult(string SampleId, string type)
        {
            DataTable dt = new DataTable();
            string sQuery = "";
            if ((type == "Pesticides") || (type == "MQI"))
            {
                sQuery = @"select ROW_NUMBER() OVER(ORDER BY c.crfsampleid ASC) AS Sr,* from crfsampledetails c 
                                inner join TestResults t on c.crfsampleid = t.crfsampleid and t.sampleID='" + SampleId + "' inner join TestParameter tp on tp.TestParameter = c.TestParameter";
            }
            else if (type == "NA")
            {
                sQuery = @"select ROW_NUMBER() OVER(ORDER BY c.crfsampleid ASC) AS Sr,* from crfsampledetails c 
                                inner join TestResults t on c.crfsampleid = t.crfsampleid and t.sampleID='" + SampleId + "' inner join TestParameter tp on tp.TestParameter = c.TestParameter";
            }
            else
            {
                sQuery = @"select ROW_NUMBER() OVER(ORDER BY c.crfsampleid ASC) AS Sr,* from crfsampledetails c 
                                inner join TestResults t on c.crfsampleid = t.crfsampleid and t.sampleID='" + SampleId + "' inner join TestParameter tp on tp.TestParameter = c.TestParameter where NABLorNonNABL='" + type + "'";
            }

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
