        public DataTable getCustomerFeedbackList()
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT distinct cf.inquiryid,cd.firstname + ' ' + cd.lastname as customername,Average,RequestNo
                                  FROM customerFeedback AS cf 
                                  inner join customerinquiry ci on cf.inquiryid = ci.inquiryid
                                  inner join CustomerDetails cd on cd.customerid = ci.customerid
                                  JOIN (SELECT inquiryid, SUM(FeedbackWeightage) AS Average
                                          FROM customerFeedback
                                         GROUP BY inquiryid
                                       ) AS s ON cf.inquiryid = s.inquiryid
                                union
                                SELECT distinct cf.inquiryid,cd.companyname as customername,Average,RequestNo
                                  FROM customerFeedback AS cf 
                                  inner join customerinquiry ci on cf.inquiryid = ci.inquiryid
                                  inner join companydetails cd on cd.customermasterid = ci.customermasterid
                                  JOIN (SELECT inquiryid, SUM(FeedbackWeightage) AS Average
                                          FROM customerFeedback
                                         GROUP BY inquiryid
                                       ) AS s ON cf.inquiryid = s.inquiryid";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
