        public DataTable GetSupervisors()
        {
            DataTable dt = new DataTable();
            string sQuery = @"select e.employeename,count(*) as allocated,EmployeeDepartmentName as Departmentname from orgtree o 
                                inner join employees e on o.id = e.EmployeeID
                                inner join EmployeeDepartment d on e.DepartmentID = d.EmployeeDepartmentID 
                                inner join allocation a on a.employeeid = e.employeeid group by e.id,e.employeename," +
                              " o.name, EmployeeDepartmentName order by EmployeeDepartmentName asc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetEmployees()
        {
            DataTable dt = new DataTable();
            string sQuery = @"select ID,EmployeeName,DesignationName,EmployeeDepartmentName,contactNumber,Mobile,Email,RoleName from employees e 
                                left join employeeDepartment d on e.departmentid = d.EmployeeDepartmentID
                                left join Designation ds on ds.designationid = e.DesignationID
                                left join users u on u.employeeid = e.employeeid
								left join roles r on u.roleid = r.roleid where e.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' order by EmployeeName asc";
