        public DataTable[] GetSampleCount()
        {
            string sQuery = "";
            DataTable dtToday = new DataTable();
            DataTable dtWeek = new DataTable();
            DataTable dtMonth = new DataTable();
            DateTime TodayDate = DateTime.Today;
            DateTime prevWeek = DateTime.Now.AddDays(-7);
            DateTime prevMonth = DateTime.Now.AddDays(-30);
            sQuery = "Select * from SampleDetails where Created ='" + TodayDate + "' and OrganizationID =1";
            dtToday = GetDataUsingQuery(sQuery);
            sQuery = "Select * from SampleDetails where Created <='" + TodayDate + "' and Created >='" + prevWeek + "' and OrganizationID =1";
            dtWeek = GetDataUsingQuery(sQuery);
            sQuery = "Select * from SampleDetails where Created <='" + TodayDate + "' and Created >='" + prevMonth + "' and OrganizationID =1";
            dtMonth = GetDataUsingQuery(sQuery);
            return new DataTable[] { dtToday, dtWeek, dtMonth };
        }
        public DataTable[] GetStatus(string type)
        {
            string sQuery = "";
            DataTable dtInquiry = new DataTable();
            DataTable dtNewCustomer = new DataTable();
            DataTable dtAssigned = new DataTable();
            DataTable dtCompleted = new DataTable();
            if (type == "today")
            {
                DateTime TodayDate = DateTime.Today;
                string today = TodayDate.ToString("d");
                sQuery = "Select * from CustomerInquiry where Created ='" + today + "' where OrganizationID =1";
                dtInquiry = GetDataUsingQuery(sQuery);
                sQuery = "Select customerid from CustomerDetails cd union select companyid from CompanyDetails where Created='" + TodayDate + "' where OrganizationID =1";
                dtNewCustomer = GetDataUsingQuery(sQuery);
                sQuery = "Select * from CustomerInquiry ci inner join CustomerDetails cd on ci.CustomerId = cd.customerId where ci.InquiryStatusId = '19' and Created='" + TodayDate + "' where OrganizationID =1";
                dtAssigned = GetDataUsingQuery(sQuery);
                sQuery = "Select * from TestResultDetails Created='" + TodayDate + "'";
                dtCompleted = GetDataUsingQuery(sQuery);
            }
            if (type == "week")
            {
                DateTime TodaydateOnly = DateTime.Today;
                string today = TodaydateOnly.ToString("d");
                DateTime prevWeek = DateTime.Now.AddDays(-7);
                sQuery = "Select * from CustomerInquiry where Created <='" + today + "' and Created >='" + prevWeek + "' where OrganizationID =1";
                dtInquiry = GetDataUsingQuery(sQuery);
                sQuery = "Select customerid from CustomerDetails cd union select companyid from CompanyDetails where Created <='" + today + "' and Created >='" + prevWeek + "' where OrganizationID =1";
                dtNewCustomer = GetDataUsingQuery(sQuery);
                sQuery = "Select * from CustomerInquiry ci inner join CustomerDetails cd on ci.CustomerId = cd.customerId where ci.InquiryStatusId = '19' and Created <='" + today + "' and Created >='" + prevWeek + "' where OrganizationID =1";
                dtAssigned = GetDataUsingQuery(sQuery);
                sQuery = "Select * from TestResultDetails Created <='" + today + "' and Created >='" + prevWeek + "'";
                dtCompleted = GetDataUsingQuery(sQuery);
            }
            if (type == "month")
            {
                DateTime TodaydateOnly = DateTime.Today;
                string today = TodaydateOnly.ToString("d");
                DateTime prevMonth = DateTime.Now.AddDays(-30);
                sQuery = "Select * from CustomerInquiry where Created <='" + today + "' and Created >='" + prevMonth + "' where OrganizationID =1";
                dtInquiry = GetDataUsingQuery(sQuery);
                sQuery = "Select customerid from CustomerDetails cd union select companyid from CompanyDetails where Created <='" + today + "' and Created >='" + prevMonth + "' where OrganizationID =1";
                dtNewCustomer = GetDataUsingQuery(sQuery);
                sQuery = "Select * from CustomerInquiry ci inner join CustomerDetails cd on ci.CustomerId = cd.customerId where ci.InquiryStatusId = '19' and Created <='" + today + "' and Created >='" + prevMonth + "' where OrganizationID =1";
                dtAssigned = GetDataUsingQuery(sQuery);
                sQuery = "Select * from TestResultDetails Created <='" + today + "' and Created >='" + prevMonth + "'";
                dtCompleted = GetDataUsingQuery(sQuery);
            }
            if (type == "all")
            {
                DateTime TodaydateOnly = DateTime.Today;
                string today = TodaydateOnly.ToString("d");
                DateTime prevMonth = DateTime.Now.AddDays(-30);
                sQuery = "Select * from CustomerInquiry where OrganizationID =1";
                dtInquiry = GetDataUsingQuery(sQuery);
                sQuery = "Select customerid from CustomerDetails cd union select companyid from CompanyDetails where OrganizationID =1";
                dtNewCustomer = GetDataUsingQuery(sQuery);
                sQuery = "Select * from CustomerInquiry ci inner join CustomerDetails cd on ci.CustomerId = cd.customerId where ci.InquiryStatusId = '19' and OrganizationID =1";
                dtAssigned = GetDataUsingQuery(sQuery);
                sQuery = "Select * from TestResultDetails";
                dtCompleted = GetDataUsingQuery(sQuery);
            }
            return new DataTable[] { dtInquiry, dtNewCustomer, dtAssigned, dtCompleted };
        }
