        public DataTable getAllSamples(int Year, int month)
        {
            DataTable dt = new DataTable();
            string sQuery = @"select distinct ID,sampleIDSeries,isnull(tr.testreportNo,' ') as TestReportNo,ReceivedDate,tr.issuedate,CloneCRFSampleID,statusname,cr.EnquiryID as inquiryID,
                                CustomerUID,departmentname,companyname as CustomerName,ReportName from sampledetails sd 			
                                                                    inner join inquiryStatus i on sd.samplestatus = i.inquirystatusid 
                                                                    inner join CRFCloneList cr on cr.sampleID = sd.ID
									                                inner join CustomerInquiry ci on ci.InquiryId = cr.EnquiryID
                                                                    inner join ReportFormat r on r.ReportFormatID= ci.ReportFormat
                                                                    inner join Department d on d.DepartmentID = ci.DepartmentID
									                                inner join CustomerMaster cm on cm.CustomerMasterId = ci.CustomerMasterId
									                                inner join CompanyDetails cd on cd.CustomerMasterId = cm.CustomerMasterId
									                                left join TestResultDetails tr on tr.sampleid=sd.id
                                                                    where year(sd.created)='" + Year + "' and month(sd.created) = '" + month + "' and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                             @" union
                                select distinct ID,sampleIDSeries,isnull(tr.testreportNo,' ') as TestReportNo,ReceivedDate,tr.issuedate,CloneCRFSampleID,statusname,cr.EnquiryID as inquiryID,
                                CustomerUID,departmentname,firstname + ' ' + lastname as CustomerName,ReportName from sampledetails sd 			
                                                                    inner join inquiryStatus i on sd.samplestatus = i.inquirystatusid 
                                                                    inner join CRFCloneList cr on cr.sampleID = sd.ID
									                                inner join CustomerInquiry ci on ci.InquiryId = cr.EnquiryID
                                                                    inner join ReportFormat r on r.ReportFormatID= ci.ReportFormat
                                                                    inner join Department d on d.DepartmentID = ci.DepartmentID
									                                inner join CustomerMaster cm on cm.CustomerMasterId = ci.CustomerMasterId
									                                inner join CustomerDetails cd on cd.CustomerMasterId = cm.CustomerMasterId
									                                left join TestResultDetails tr on tr.sampleid=sd.id
                                                                    where year(sd.created)='" + Year + "' and month(sd.created) = '" + month + "' and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                                                                    @"order by ReceivedDate desc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
