									left join TestResultDetails tr on tr.sampleid=sd.id
                                    where ed.departmentid in(" + DepartmentID + ") and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' and year(sd.created)= '" + Year + "' and month(sd.created) = '" + month + "'" +
                                @" union
select distinct ID,sampleIDSeries,isnull(tr.testreportNo,' ') as TestReportNo,ReceivedDate,tr.issuedate,CloneCRFSampleID,statusname,cr.EnquiryID as inquiryID,
CustomerUID,departmentname,firstname + ' ' + lastname as CustomerName,ReportName from sampledetails sd
