        public void GenerateTAFNo(int RequestID, string Type)
        {
            DataTable dtTAF = getLastTAFNo();
            if (dtTAF.Rows.Count > 0)
            {
                if (dtTAF.Rows[0]["TAFSeries"].ToString() != "")
                {
                    TAFSeries = Convert.ToInt32(dtTAF.Rows[0]["TAFSeries"]) + 1;
                }
            }
            else
            {
                TAFSeries = 1;
            }
            string sYear = DateTime.Now.AddHours(1.5).ToString("yyyy");
            string sMonth = DateTime.Now.AddHours(1.5).ToString("MM");
            TAFNo = sYear + sMonth + TAFSeries.ToString().PadLeft(4, '0');
            updateTAF(TAFSeries, TAFNo, Type, RequestID);

        }
        public int updateTAF(int TAFSeries, string TAFNo, string type, int RequestID)
        {
            string sQuery = "";

            if (type == "TAF")
            {
                sQuery = "Update CustomerRequestDetails set TAFNo='" + TAFNo + "',TAFSeries='" + TAFSeries + "' where CustomerRequestId=" + RequestID;
            }
            if (type == "Clone")
            {
                sQuery = "Update CRFSampleDetails set TAFNo='" + TAFNo + "' where CustomerRequestId=" + RequestID;
            }
            int modified = UpdateSQLQuery(sQuery);
            return modified;
        }
        public int updateCRFTAF(int CloneCRFSampleID)
        {
            string sQuery = "";

            sQuery = @"UPDATE s
                        SET 
	                        s.TAFCount = c.tafseries,
                            s.tafno = c.tafno
                        FROM CRFSampleDetails s
                        INNER JOIN CustomerRequestDetails c 
                            ON s.CustomerRequestId = c.CustomerRequestId and s.CloneCRFSampleID=" + CloneCRFSampleID;
            int modified = UpdateSQLQuery(sQuery);
            return modified;
        }
