        public string ReplaceSuperScript(string input)
        {
            string text = input;//caret symbol Shift + 6
            string scriptHex = ""; string newStr;
            if (text.Contains("^0"))
            {
                scriptHex = "0x2070";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^0", newStr);
            }
            if (text.Contains("^1"))
            {
                scriptHex = "0x00B9";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^1", newStr);
            }
            if (text.Contains("^2"))
            {
                scriptHex = "0x00B2";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^2", newStr);
            }
            if (text.Contains("^3"))
            {
                scriptHex = "0x00B3";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^3", newStr);
            }
            if (text.Contains("^4"))
            {
                scriptHex = "0x2074";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^4", newStr);
            }
            if (text.Contains("^5"))
            {
                scriptHex = "0x2075";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^5", newStr);
            }
            if (text.Contains("^6"))
            {
                scriptHex = "0x2076";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^6", newStr);
            }
            if (text.Contains("^7"))
            {
                scriptHex = "0x2077";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^7", newStr);

            }
            if (text.Contains("^8"))
            {
                scriptHex = "0x2078";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^8", newStr);

            }
            if (text.Contains("^9"))
            {
                scriptHex = "0x2079";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^9", newStr);
            }
            if (text.Contains("^*"))
            {
                scriptHex = "0x002A";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("^*", newStr);
            }
            if (text.Contains("deg"))
            {
                scriptHex = "0x00B0";
                newStr = System.Convert.ToChar(System.Convert.ToUInt32(scriptHex, 16)).ToString() + " ";
                text = text.Replace("deg", newStr);
            }
            return text;
        }

