        public DataTable getReportSentByStatus(int sentStatus)
        {
            DataTable dt = new DataTable();
            string sQuery = @"select distinct tr.TestReportID,td.TestReportNo,tr.testReportFileName,e.employeeName,
                                cd.companyname as customername,tr.created,tr.SentEmail,tr.SentDate from TestReports tr 
                                inner join Employees e on e.employeeid=tr.employeeID
                                inner join CRFCloneList cr on cr.CloneCRFSampleID = tr.CloneCRFSampleID 
                                inner join testresultdetails td on td.sampleid=cr.sampleid
                                inner join CustomerInquiry ci on ci.InquiryId = cr.EnquiryID 
                                inner join CompanyDetails cd on cd.customermasterid=ci.customermasterid
                                where tr.testreportfilename like '%.pdf' and tr.sentstatus=" + sentStatus +
                            @"  union
                                select distinct tr.TestReportID,td.TestReportNo,tr.testReportFileName,e.employeeName,
                                cd.FirstName + ' ' + cd.LastName  as customername,tr.created,tr.SentEmail,tr.SentDate from TestReports tr 
                                inner join Employees e on e.employeeid=tr.employeeID
                                inner join CRFCloneList cr on cr.CloneCRFSampleID = tr.CloneCRFSampleID 
                                inner join testresultdetails td on td.sampleid=cr.sampleid
                                inner join CustomerInquiry ci on ci.InquiryId = cr.EnquiryID 
                                inner join CustomerDetails cd on cd.CustomerMasterId=ci.customermasterid
                                where tr.testreportfilename like '%.pdf' and tr.sentstatus= " + sentStatus + " order by tr.created desc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
