        public int GetReseedIdentity(string table, string identityField)
        {
            int ReseedIdentity = 0;
            try
            {
                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        _sCon.Open();

                        cmd.CommandType = CommandType.Text;
                        cmd.CommandText = "select max(" + identityField + ") from " + table;
                        ReseedIdentity = (int)cmd.ExecuteScalar();
                    }
                }
                return ReseedIdentity;
            }
            catch (Exception ex)
            {
                string msg = ex.Message;
                // HttpContext.Current.Response.Redirect("~/Error.aspx", false);
                return 0;
            }
        }
        public void ReseedIdentity(string table, int reseedIdentity)
        {
            string sql =
                $"DBCC CHECKIDENT('{table}', RESEED, {reseedIdentity})";

            using (SqlConnection con =
                   new SqlConnection(ConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                con.Open();

                using (SqlCommand cmd = new SqlCommand(sql, con))
                {
                    cmd.ExecuteNonQuery();
                }
            }
        }
