        public DataTable GetDataUsingQuery(string sQuery)
        {
            DataTable dt = new DataTable();
            using (SqlConnection con = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, con))
                {
                    con.Open();
                    SqlDataAdapter adp = new SqlDataAdapter(cmd);
                    adp.Fill(dt);
                }
            }
            return dt;
        }

        public DataTable GetDataUsingQuery(string sQuery, List<SqlParameter> parameters)
        {
            DataTable dt = new DataTable();

            using (SqlConnection con = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, con))
                {
                    if (parameters != null && parameters.Count > 0)
                    {
                        cmd.Parameters.AddRange(parameters.ToArray());
                    }

                    using (SqlDataAdapter adp = new SqlDataAdapter(cmd))
                    {
                        adp.Fill(dt);
                    }
                }
            }

            return dt;
        }
        public int UpdateSQLQuery(string sQuery)
        {
            int modified = 0;
            DataTable dt = new DataTable();
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    _sCon.Open();
                    modified = cmd.ExecuteNonQuery();
                }
            }

            return modified;
        }
