        public DataTable[] GetWork(int EmployeeID, int RoleID, int DepartmentID)
        {
            string sQuery = "";
            DataTable dtSamples = new DataTable();
            DataTable dtWorkList = new DataTable();
            DataTable dtGenReport = new DataTable();
            DataTable dtReview = new DataTable();
            DataTable dtAllSamples = new DataTable();
            DataTable dtAllocate = new DataTable();
            DataTable dtCRFReceived = new DataTable();
            DataTable dtCRFFinalised = new DataTable();
            DataTable dtCRFApproved = new DataTable();

            sQuery = "Select * from SampleDetails where OrganizationID =1";
            dtSamples = GetDataUsingQuery(sQuery);
            sQuery = @"SELECT distinct cl.CloneCRFSampleID,csd.EmployeeId,st.StatusName, sd.ID,sd.SampleId,sd.sampleidseries,st.StatusName,id, cl.EnquiryID as InquiryID,
									sd.ReceivedDate,sd.DeliveryDate,ServiceRequired 
                                    FROM SampleDetails sd
                        INNER JOIN CRFCloneList cl ON sd.ID = cl.SampleID
                        INNER JOIN CRFSampleDetails csd ON cl.CloneCRFSampleID = csd.CloneCRFSampleID
                        INNER JOIN InquiryStatus st on st.InquiryStatusId = csd.samplestatus 
                        inner join CustomerInquiry cii on cii.InquiryId =  cl.EnquiryID
                        left join AdditionalDetails ad on ad.InquiryID = cl.EnquiryID
                        WHERE csd.EmployeeId = " + EmployeeID + " AND (st.StatusName='Allocated for Testing' or st.StatusName='Re-Test')";
            dtWorkList = GetDataUsingQuery(sQuery);
            if (RoleID == 2)
            {
                sQuery = @"Select * from SampleDetails s
                        inner join CRFCloneList c on c.sampleid=s.ID
                        inner join CustomerInquiry ci on ci.InquiryID=c.EnquiryID
                        where SampleStatus=27 and ci.DepartmentID=" + DepartmentID + " and s.OrganizationID =1";
            }
            if (RoleID == 3)
            {
                sQuery = @"Select * from SampleDetails s
                        inner join CRFCloneList c on c.sampleid=s.ID
                        inner join CustomerInquiry ci on ci.InquiryID=c.EnquiryID
                        where SampleStatus=19 and ci.DepartmentID=" + DepartmentID + " and s.OrganizationID =1";
            }
            if (RoleID == 5)
            {
                sQuery = @"Select * from SampleDetails s
                        inner join CRFCloneList c on c.sampleid=s.ID
                        inner join CustomerInquiry ci on ci.InquiryID=c.EnquiryID
                        where SampleStatus=29 and s.OrganizationID =1";
            }
            dtGenReport = GetDataUsingQuery(sQuery);
            sQuery = @"Select * from SampleDetails s
                        inner join CRFCloneList c on c.sampleid=s.ID
                        inner join CustomerInquiry ci on ci.InquiryID=c.EnquiryID
                        where SampleStatus=29 and ci.DepartmentID=" + DepartmentID + " and s.OrganizationID =1";
            dtReview = GetDataUsingQuery(sQuery);
            sQuery = "Select * from SampleDetails";
            dtAllSamples = GetDataUsingQuery(sQuery);
            sQuery = @"Select * from SampleDetails s
                        inner join CRFCloneList c on c.sampleid=s.ID
                        inner join CustomerInquiry ci on ci.InquiryID=c.EnquiryID
                        where SampleStatus in(14,15) and ci.DepartmentID=" + DepartmentID + " and s.OrganizationID =1";
            dtAllocate = GetDataUsingQuery(sQuery);
            sQuery = @"select * from CustomerInquiry ci where inquiryid not in(
                        select EnquiryID from CRFCloneList c
                        inner join SampleDetails s on s.id=c.sampleID)
                        and InquiryStatusID=6 and DepartmentID=" + DepartmentID + " and ci.OrganizationID =1";
            dtCRFReceived = GetDataUsingQuery(sQuery);
            sQuery = @"select distinct CustomerRequestId, InquiryStatusid from CustomerInquiry ci 
                        inner join CRFSampleDetails cs on cs.InquiryId = ci.InquiryId
                        where ci.inquiryid not in(
                        select EnquiryID from CRFCloneList c
                        inner join SampleDetails s on s.id=c.sampleID)
                        and DepartmentID=" + DepartmentID + " and ci.OrganizationID =1";
            dtCRFFinalised = GetDataUsingQuery(sQuery);
            sQuery = @"select distinct CustomerRequestId, InquiryStatusid from CustomerInquiry ci 
                        inner join CustomerCRFSampleDetails cs on cs.InquiryId = ci.InquiryId
                        where ci.inquiryid not in(
                        select EnquiryID from CRFCloneList c
                        inner join SampleDetails s on s.id=c.sampleID)
                        and InquiryStatusID=21 and DepartmentID=" + DepartmentID + " and ci.OrganizationID =1";
            dtCRFApproved = GetDataUsingQuery(sQuery);
            return new DataTable[] { dtSamples, dtWorkList, dtGenReport, dtReview, dtAllocate, dtCRFReceived, dtCRFFinalised, dtCRFApproved };
        }
