        public DataTable GetCRFDetails(int InquiryID)
        {
            sQuery = @"select a.*,c.*,cr.ShippingAgency,cr.AirwayBillNo,cm.customeruid,cd.CustomerMasterId,
                        cd.FirstName as customername,cp.personid,cr.contactperson 
                        ,AddressLine1, AddressLine2 + ' ' + AddressLine3 as AddressLine2,Pincode,VAT
									from CustomerDetails cd
                        inner join customermaster cm on cm.CustomerMasterId = cd.CustomerMasterId
                        inner join LocationDetails l on l.CustomerMasterId = cd.CustomerMasterId
                        inner join CustomerInquiry c on c.CustomerMasterId = cd.CustomerMasterId 
						inner join CustomerRequestDetails cr on cr.inquiryID = c.inquiryID
						inner join ContactPersonDetails cp on cp.personID = cr.contactperson
                        left join AdditionalDetails a on a.InquiryID = c.InquiryID
                        where c.InquiryID=" + InquiryID +
                      @" union
                        select a.*,c.*,cr.ShippingAgency,cr.AirwayBillNo,cm.customeruid,cd.CustomerMasterId,
						CompanyName as CustomerName,cp.personid,cr.contactperson 
						,AddressLine1, AddressLine2 + ' ' + AddressLine3 as AddressLine2,Pincode,VAT
									from CompanyDetails cd
                        inner join customermaster cm on cm.CustomerMasterId = cd.CustomerMasterId
                        inner join LocationDetails l on l.CustomerMasterId = cd.CustomerMasterId
                        inner join CustomerInquiry c on c.CustomerMasterId = cd.CustomerMasterId 
						inner join CustomerRequestDetails cr on cr.inquiryID = c.inquiryID
						inner join ContactPersonDetails cp on cp.personID = cr.contactperson
                        left join AdditionalDetails a on a.InquiryID = c.InquiryID
                        where c.InquiryID=" + InquiryID;

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }


