        public int AddTestResultDetailsMicro(DAL.CM obj)
        {
            int modified = 0;


            //Start Reseed to avoid identity jump
            int prevIdentity = GetReseedIdentity("TestResultDetails", "TestResultID");
            ReseedIdentity("TestResultDetails", prevIdentity);
            //End Reseed to avoid identity jump
            string mfgDate = ""; string expDate = "";
            if (obj.dateOfMfg != "")
            {
                mfgDate = DateTime.ParseExact(obj.dateOfMfg, "dd/MM/yyyy", CultureInfo.InvariantCulture).ToString("MM/dd/yyyy").ToString();
            }
            if (obj.dateOfExp != "")
            {
                expDate = DateTime.ParseExact(obj.dateOfExp, "dd/MM/yyyy", CultureInfo.InvariantCulture).ToString("MM/dd/yyyy").ToString();
            }

            string sQuery = @"Insert into TestResultDetails (SampleId,IssueDate,ULRNo,AnalysisStartingDate,
            AnalysisCompletionDate,NameOfProduct,DateOfMfg,DateOfExp,SampleQuality,SampleCondition,TestRequired,
            Sampling,SamplingMethod,TestReportNo,CustomerReference,Remarks)output INSERTED.TestResultId  
            values (" + obj.sampleId + ",'" + obj.issueDate.ToString("MM/dd/yyyy") + "','" + obj.ulrNo + "','" + obj.analysisStartingDate.ToString("MM/dd/yyyy") + "','" +
          obj.analysisCompleteDate.ToString("MM/dd/yyyy") + "','" + obj.nameOfProduct + "','" + mfgDate + "','" +
          expDate + "','" + obj.sampleQuality + "','" + obj.sampleCondition + "','" +
          obj.testRequired + "','" + obj.sampling + "','" + obj.SamplingMethod + "','" + obj.reportNo + "','" +
          obj.CustomerReference + "','" + obj.remarks + "')";
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    _sCon.Open();

                    modified = (int)cmd.ExecuteScalar();
                }
            }
            return modified;
        }
