        public DataTable GetResultTablevalues(string sampleId)
        {
            DataTable dt = new DataTable();
            string sQuery = @"
    SELECT 
     tp.TestParameter AS SpecCols,
     CASE 
         WHEN c.TestSubParameter IS NULL THEN tp.TestParameter
         ELSE ts.TestSubParameter
     END AS TestParameter,
     CASE 
         WHEN c.TestSubSubParameter IS NULL THEN tss.TestSubSubParameter
         ELSE ts.TestSubParameter
     END AS [Test Items(s)],
     TestMethod AS [Method(s)],
     c.UnitOfMeasurement AS [Unit(s)],
     CASE 
         WHEN tp.specification IS NOT NULL THEN tp.specification
         WHEN ts.specification IS NOT NULL THEN ts.specification
         ELSE tss.Specification
     END AS Specification,
     CASE 
         WHEN tp.LOD IS NOT NULL THEN tp.LOD
         WHEN ts.LOD IS NOT NULL THEN ts.LOD
         ELSE tss.LOD
     END AS LOD,                            
     TestResult AS [Result(s)]
 FROM crfsampledetails c 
 INNER JOIN TestResults t ON c.crfsampleid = t.crfsampleid
 LEFT JOIN TestParameter tp ON tp.TestParameterid = c.TestParameterid
 LEFT JOIN TestSubParameter ts ON ts.TestSubParameterID = c.TestSubParameterID
 LEFT JOIN TestSubSubParameter tss ON tss.TestSubSubParameterID = c.TestSubSubParameterID
 WHERE t.sampleID = " + sampleId;

            dt = GetDataUsingQuery(sQuery);

            return dt;
        }

