        public DataTable getFoodDetails(int sampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT testreportno, issuedate, ReceivedDate AS Receiveddate, Companyname AS CustomerName,cf.BatchNo,
                    (Addressline1 + ' ' + Addressline2 + ' ' + city + ' ' + pincode + ' ' + country) AS Address,ad.BuyerCustomerName AS Buyer,
                    samplename AS SampleDescription, sampleidseries AS SampleNo, ad.PONo as [Service Confirmation No.],
                    SampleCondition, AnalysisCompletionDate,s.SampleID as SID,t.ReportType,EmployeeName as LabHeadName 
                    FROM testresultdetails t
                   INNER JOIN sampledetails s ON s.ID = t.sampleid
                   INNER JOIN crfclonelist c ON c.sampleid = s.id
                   INNER JOIN customerinquiry ci ON ci.inquiryid = c.enquiryid
                   INNER JOIN CompanyDetails cd ON cd.customermasterid = ci.customermasterid
                   INNER JOIN locationdetails l ON l.customermasterid = ci.customermasterid
                   INNER JOIN crfsampledetails cf ON cf.clonecrfsampleid = c.clonecrfsampleid
                   LEFT JOIN  AdditionalDetails ad on  ad.InquiryID = ci.InquiryId
                   LEFT JOIN Employees e on e.id= t.AuthorizedSignatoryID 
                   WHERE s.id = " + sampleID;

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
