        public void clearTables(string tableName)
        {
            bool result = true;
            sQuery = @"IF OBJECT_ID('" + tableName + "', 'u') IS NOT NULL DROP TABLE " + tableName;
            result = dropTable(sQuery);
        }
        public bool dropTable(string sQuery)
        {
            SqlConnection _sCon = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString);
            bool result = true;
            try
            {
                using (_sCon)
                {
                    _sCon.Open();
                    using (SqlCommand command = new SqlCommand(sQuery, _sCon))
                    {
                        command.ExecuteNonQuery();
                    }

                }
            }
            catch (SystemException ex)
            {
                string str = ex.Message;
                result = false;
            }
            return result;
        }
