        public DataTable getTestSubSubParameters_New(string TestSubParameter)
        {
            string sQuery = @"SELECT TestSubSubParameter, MIN(TestSubSubParameterID) AS TestSubSubParameterID
                         FROM TestSubSubParameter
                         WHERE TestSubParameterID IN (
                             SELECT TestSubParameterID
                             FROM TestSubParameter
                             WHERE TestSubParameter = @TestSubParameter
                         )
                         GROUP BY TestSubSubParameter";

            DataTable dt = new DataTable();
            using (SqlConnection con = new SqlConnection(cs))
            {
                using (SqlCommand command = new SqlCommand(sQuery, con))
                {
                    con.Open();
                    command.Parameters.AddWithValue("@TestSubParameter", TestSubParameter);

                    using (SqlDataAdapter dataAdapter = new SqlDataAdapter(command))
                    {
                        dataAdapter.Fill(dt);
                    }
                }
            }

            return dt;
        }
