        public DataTable getChemicalEnquiryDetails(int InquiryId)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT
                                                t.TestParameterID, 
                                                t.TestParameter, 
                                                ts.TestSubParameterID, 
                                                ts.TestSubParameter, 
                                                sgt.RequirementId,  
                                                sgt.SubGroupName,
                                                tss.TestSubSubParameterID, 
                                                tss.TestSubSubParameter, 
                                                t.UOMName, 
                                                ts.CASNo, 
                                                ts.MDL, 
                                                ts.Specification, 
                                                ts.protocol AS TestMethod
                                            FROM
                                                (SELECT * FROM ProductSubGroup p
                                                CROSS APPLY STRING_SPLIT(TestParameterId, ',')) x
                                            INNER JOIN CustomerInquiry ci ON ci.productCategoryID = x.subgroupid
                                            INNER JOIN TestParameter t ON t.TestParameterID = x.value
                                            INNER JOIN TestSubParameter ts ON ts.TestParameterID = t.TestParameterID
                                            LEFT JOIN TestSubSubParameter tss ON tss.testsubparameterid = ts.TestSubParameterID
                                            LEFT JOIN ProductSubGroup sgt ON sgt.SubGroupID = ci.productCategoryID
                                            WHERE ci.InquiryId = '" + InquiryId + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
