        public DataTable GetCRFListForTestResults_Chemical(int sampleID, int EmployeeID, int AdditionalColourCodeId)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT cd.CRFSampleID, SampleName, BatchNo, TestMethod, cd.TestParameter, TestSubParameterID, TestSubParameter, 
                          TestSubSubParameter, TestResult, cd.RequirementID, cd.UnitOfMeasurement, ISNULL(t.Specification, cd.Specification) AS Specification,
                          StatusName, AnalysisStartingDate, AnalysisCompletionDate, t.DestroyDate, calculations, cd.SampleStatus, ce.EpID, 
                          ce.Equipment, t.EquipmentName, ccs.ColourCodeId, ccs.AdditionalColourCodeId, ccs.ColourCodeId, 
                          t.AdditionalColourCodesId, t.TestResultID
                        FROM crfsampledetails cd 
                        INNER JOIN crfclonelist ci ON cd.clonecrfsampleid = ci.clonecrfsampleid
                        INNER JOIN InquiryStatus s ON s.inquirystatusid = cd.samplestatus
                        LEFT JOIN testresults t ON t.CRFSampleID = cd.CRFSampleId AND t.AdditionalColourCodesId = @AdditionalColourCodeId
                        INNER JOIN sampledetails sd ON ci.sampleid = sd.id 
                        INNER JOIN testparameter tp ON tp.TestParameterID = cd.TestParameterID
                        LEFT JOIN Calibration_Equipment ce ON ce.EpID = tp.EpID
                        LEFT JOIN ColourCodeSave ccs ON ccs.InquiryId = cd.InquiryId AND ccs.AdditionalColourCodeId = @AdditionalColourCodeId
                        WHERE sd.sampleid = @SampleID AND cd.EmployeeID = @EmployeeID AND cd.OrganizationID = @OrganizationID
                        ORDER BY cd.CRFSampleId ASC";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@AdditionalColourCodeId", AdditionalColourCodeId);
                    cmd.Parameters.AddWithValue("@SampleID", sampleID);
                    cmd.Parameters.AddWithValue("@EmployeeID", EmployeeID);
                    cmd.Parameters.AddWithValue("@OrganizationID", HttpContext.Current.Session["OrganizationID"].ToString());

                    dt = GetDataUsingQuery1(cmd);
                }
            }
            return dt;
        }


