        public DataTable GetResultOverallConclusion(string sampleId)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT ROW_NUMBER() OVER (ORDER BY tp.TestParameter, c.TestMethod) AS [No.],
                                tp.TestParameter AS [Test Parameters],
                                c.TestMethod AS [Test Method],
                                MAX(c.Requirement) AS [Requirement],
                                CASE 
                                    WHEN COUNT(DISTINCT t.Conclusion) = 1 THEN MAX(t.Conclusion)
                                    WHEN SUM(CASE WHEN t.Conclusion = 'FAIL' THEN 1 ELSE 0 END) > 0 THEN 'FAIL'
                                    ELSE MAX(t.Conclusion)
                                END AS [Results]
                            FROM crfsampledetails c
                            LEFT JOIN TestResults t ON c.crfsampleid = t.crfsampleid
                            LEFT JOIN TestParameter tp ON tp.TestParameterID = c.TestParameterID
                            WHERE t.sampleID = @SampleId
                            GROUP BY tp.TestParameter, c.TestMethod";
            using (SqlConnection conn = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, conn))
                {
                    conn.Open();
                    cmd.Parameters.AddWithValue("@SampleId", sampleId);
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }

            return dt;
        }
