        public int AddInvoice(DAL.CM obj, DataTable dt)
        {
            int newID = 0;


            // Start Reseed to avoid identity jump
            int prevIdentity = GetReseedIdentity("Invoices", "InvoiceID");
            ReseedIdentity("Invoices", prevIdentity);
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                _sCon.Open();
                // End Reseed to avoid identity jump
                SqlTransaction trans = _sCon.BeginTransaction();

                try
                {
                    string sQuery = @"INSERT INTO Invoices (CompanyID,
                                    InvoiceDate,
                                    DueDate,
                                    TotalAmount,
                                    AmountPaid,
                                    Status,
                                    QuotationID,
                                    InvoiceNumber,
                                    PaymentTermID,
                                    currencyid,
                                    workorderno,
                                    TransactionCodeId,
                                    PIC,
                                    PONumber,
                                    BuyerIDType,
                                    SubTotal,
                                    DownPayment,
                                    VATAmount,
                                    BalanceDue) 
                                output INSERTED.InvoiceID
                                VALUES (@CompanyID,
                                    @InvoiceDate,
                                    @DueDate,
                                    @TotalAmount,
                                    @AmountPaid,
                                    @Status,
                                    @QuotationID,
                                    @InvoiceNumber,
                                    @PaymentTermID,
                                    @currencyid,
                                    @workorderno,
                                    @TransactionCodeId,
                                    @PIC,
                                    @PONumber,
                                    @BuyerIDType,
                                    @SubTotal,
                                    @DownPayment,
                                    @VATAmount,
                                    @BalanceDue)";

                    SqlCommand cmd = new SqlCommand(sQuery, _sCon, trans);
                    {
                        cmd.Parameters.AddWithValue("@CompanyID", obj.companyId);
                        cmd.Parameters.AddWithValue("@InvoiceDate", obj.InvoiceDate);
                        cmd.Parameters.AddWithValue("@DueDate", obj.DueDate);
                        cmd.Parameters.AddWithValue("@TotalAmount", obj.TotalAmount);
                        cmd.Parameters.AddWithValue("@AmountPaid", obj.PaidAmount);
                        cmd.Parameters.AddWithValue("@Status", obj.InvoiceStatus);
                        cmd.Parameters.AddWithValue("@QuotationID", obj.QuotationID);
                        cmd.Parameters.AddWithValue("@InvoiceNumber", obj.InvoiceNumber);
                        cmd.Parameters.AddWithValue("@PaymentTermID", obj.PaymentTermID);
                        cmd.Parameters.AddWithValue("@currencyid", obj.CurrencyID);
                        cmd.Parameters.AddWithValue("@workorderno", obj.WONumber);
                        cmd.Parameters.AddWithValue("@TransactionCodeId", obj.TransactionCodeID);
                        cmd.Parameters.AddWithValue("@PIC", obj.PIC);
                        cmd.Parameters.AddWithValue("@PONumber", obj.PONumber);
                        cmd.Parameters.AddWithValue("@BuyerIDType", obj.BuyerIDType);
                        cmd.Parameters.AddWithValue("@SubTotal", obj.SubTotal);
                        cmd.Parameters.AddWithValue("@DownPayment", obj.DownPayment);
                        cmd.Parameters.AddWithValue("@VATAmount", obj.VATAmount);
                        cmd.Parameters.AddWithValue("@BalanceDue", obj.BalanceDue);

                        newID = (int)cmd.ExecuteScalar();

                        // Insert detail rows
                        foreach (DataRow d in dt.Rows)
                        {
                            string detailSql = @"INSERT INTO InvoiceDetails
                                    (InvoiceId,
                                    ItemDescription,
                                    TestItems,
                                    TestItemDetails,
                                    SampleDescription,
                                    Quantity,
                                    UnitPrice,
                                    TotalAmount,
                                    QuotationDetailsID,
                                    QuotationQty,
                                    AccountCode
                                    )
                                    VALUES (@InvoiceId,
                                            @ItemDescription,
                                            @TestItems,
                                            @TestItemDetails,
                                            @SampleDescription,
                                            @Quantity,
                                            @UnitPrice,
                                            @TotalAmount,
                                            @QuotationDetailsID,
                                            @QuotationQty,
                                            @AccountCode)";

                            SqlCommand cmdDetail = new SqlCommand(detailSql, _sCon, trans);
                            cmdDetail.Parameters.AddWithValue("@InvoiceId", newID);
                            cmdDetail.Parameters.AddWithValue("@ItemDescription", d["TestItems"].ToString() + ' ' + d["sampleDescription"].ToString());
                            cmdDetail.Parameters.AddWithValue("@TestItems", d["TestItems"].ToString());
                            cmdDetail.Parameters.AddWithValue("@TestItemDetails", d["TestItemDetails"].ToString());
                            cmdDetail.Parameters.AddWithValue("@SampleDescription", d["sampleDescription"].ToString());
                            cmdDetail.Parameters.AddWithValue("@Quantity", Convert.ToDecimal(d["Quantity"]));
                            cmdDetail.Parameters.AddWithValue("@UnitPrice", Convert.ToDecimal(d["Price"]));
                            cmdDetail.Parameters.AddWithValue("@TotalAmount", Convert.ToDecimal(d["TotalAmount"]));
                            cmdDetail.Parameters.AddWithValue("@QuotationDetailsID", Convert.ToDecimal(d["QuotationDetailID"]));
                            cmdDetail.Parameters.AddWithValue("@QuotationQty", Convert.ToDecimal(d["Quantity"]));
                            cmdDetail.Parameters.AddWithValue("@AccountCode", d["AccountCode"].ToString());

                            cmdDetail.ExecuteNonQuery();
                        }
                        trans.Commit();
                    }
                }
                catch (Exception ex)
                {
                    trans.Rollback();
                    Console.WriteLine($"SQL Error: {ex.Message}");
                    throw;
                }

                finally
                {


                }
            }
            return newID;
        }

