        public DataTable LoadCustomerLedger(string CustomerID, string From, string To)
        {
            string query = @"SELECT 
                            L.DocDate,
                            L.DocType,
                            L.DocNo,
                            L.Description,
                            L.InvoiceDate,
                            L.Debit,
                            L.Credit,
                            SUM(L.Debit - L.Credit) 
                                OVER (ORDER BY L.DocDate, L.DocNo) AS Balance
                        FROM
                        (
                                SELECT 
                                    i.InvoiceDate AS DocDate,
                                    'RI' AS DocType,
                                    i.InvoiceNumber AS DocNo,
                                    'Invoice' AS Description,
                                    i.InvoiceDate,
                                    i.TotalAmount AS Debit,
                                    0 AS Credit
                                FROM Invoices i
                                WHERE i.CompanyID = 103

                                UNION ALL

                                SELECT 
                                    r.ReceiptDate,
                                    'RC',
                                    CAST(r.ReceiptID AS VARCHAR),
                                    'Cash Receipts',
                                    NULL,
                                    0,
                                    r.ReceiptAmount
                                FROM Receipts r
                                JOIN InvoiceAR ar ON ar.InvoiceARId = r.InvoiceARId
                                WHERE ar.CustomerID = @CustomerID

                        ) L
                        ORDER BY L.DocDate, L.DocNo";

            string cs = ConfigurationManager.ConnectionStrings["CM"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand("sp_CustomerLedgerReport", con))
                {
                    con.Open();
                    cmd.CommandType = CommandType.StoredProcedure;
                    cmd.Parameters.Add("@CustomerID", SqlDbType.Int).Value = CustomerID;
                    cmd.Parameters.Add("@FromDate", SqlDbType.Date).Value = From;
                    cmd.Parameters.Add("@ToDate", SqlDbType.Date).Value = To;

                    SqlDataAdapter da = new SqlDataAdapter(cmd);

                    DataTable dt = new DataTable();
                    da.Fill(dt);
                }
                return dt;
            }
        }

        public DataTable GetInvoicesByIds(List<int> invoiceIds)
        {
            DataTable dt = new DataTable();

            using (SqlConnection con = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(
                @"select 
                        ROW_NUMBER() OVER (Order by InvoiceId) AS RowNumber,
	                        InvoiceDate,
                        'Normal' as	InvoiceType,
	                        TransactionCode,
                        '-' as	AdditionalInformation,
                        '-' as	SupportingDocuments,
                        '-' as	SupportingDocumentPeriod,
	                        InvoiceNumber,
                        '-' as	FacilityStamp,
                        '0311995997402000' as SellerNPWP,
	                        VAT as NPWP,
	                        BuyerIDType,
	                        Country,
                        '-' as	BuyersDocumentNumber,
                        '-' as	BuyersName,
                        '-' as	BuyersAddress,
                        '-' as	BuyersEmail,
                        VAT + '000000' as	BuyerTKU
                        from Invoices i 
                        inner join companyDetails cd on cd.CustomerMasterID = i.CompanyID
                        inner join LocationDetails l on l.CustomerMasterID = i.CompanyID
                        inner join TransactionCode t on t.ID=i.TransactionCodeid
                    WHERE i.InvoiceID IN (SELECT InvoiceID FROM @InvoiceIds)", con))
                {
                    // Convert list to DataTable
                    DataTable tvp = new DataTable();
                    tvp.Columns.Add("InvoiceID", typeof(int));

                    foreach (int id in invoiceIds)
                        tvp.Rows.Add(id);

                    SqlParameter param = cmd.Parameters.AddWithValue("@InvoiceIds", tvp);
                    param.SqlDbType = SqlDbType.Structured;
                    param.TypeName = "InvoiceIdList";

                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }

            return dt;
        }
        public DataTable GetInvoiceDetailsByIds(List<int> invoiceIds)
        {
            DataTable dt = new DataTable();

            using (SqlConnection con = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            using (SqlCommand cmd = new SqlCommand(
                @"select 
                    ROW_NUMBER() OVER (Order by InvoiceId) AS RowNumber,
                    'B' as	GoodsServices,
                    '160404' as	GoodsServicesCode,
	                    ItemDescription,
                    'UM.0033' as UOM,
	                    UnitPrice,
	                    Quantity,
                    0 as Discount,
	                    TotalAmount,
                    TotalAmount*11/12 as VATOther,
                    12 as VATRate,
                    TotalAmount*(11/12)*(12/100) as PPN,
                    0 as TariffPPnBM,
                    0 as PPnBM
                    from InvoiceDetails WHERE InvoiceID IN (SELECT InvoiceID FROM @Ids)", con))
            {
