        public DataTable GetDocumentsOfVendor(int VendorID)
        {
            sQuery = @"select ROW_NUMBER() OVER(ORDER BY dd.DocumentType) AS SlNo,vendorid,dd.DocumentType as DocumentTypeName,DocumentTypeID,documentName,VersionNumber from DocumentVendor dv1 
                        inner join DocumentDetails dd on dd.DocumentID = dv1.DocumentTypeID 
                        where VersionNumber=(select max(VersionNumber) from DocumentVendor where dv1.DocumentTypeID = DocumentVendor.DocumentTypeID and VendorID='" + VendorID + "') and dv1.VendorID='" + VendorID + "' order by VersionNumber desc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

