        public int updateVendorCategory(DAL.CM obj)
        {


            string sQuery = "UPDATE VendorDetails SET " +
                            "PurchaseGroupID = @PurchaseGroupID, " +
                            "PurchaseSubGroupID = @PurchaseSubGroupID " +
                            "WHERE VendorID = @VendorID";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    _sCon.Open();
                    cmd.Parameters.AddWithValue("@PurchaseGroupID", obj.SelectedGroups ?? "");
                    cmd.Parameters.AddWithValue("@PurchaseSubGroupID", obj.SelectedSubGroups ?? "");
                    cmd.Parameters.AddWithValue("@VendorID", obj.VendorID);

                    modified = cmd.ExecuteNonQuery();
                }
            }

            return modified;
        }



        //-----VendorQuotation-----
        public DataTable GetQuotationDetails(string VendorQuotationID, string VendorID)
        {
            sQuery = @"select distinct vd.VendorID as EnquiryVendorID,vd.Rate as QuoteRate,vq.CreatedDate as QuotationDate,vq.Remarks,vd.Remarks AS Remarkforitem,
vd.Discount,vd.DeliveryTime,c.CurrencyName,vq.QuoteCurrencyId,vd.DiscountApplied,pd.Remarks as UserRemarks,um.UOMName,vd.OrderedQty,
vd.SpecialInstruction,v.Reference,vd.VATId,vq.VendorQuotationID,vd.VendorQuotationDetailsID,i.ItemCode,i.ItemDescription,i.Specification,i.ModelNo,v.Reference,
vq.QuotationNumber,vq.Payment,vq.VendorContactPersonID,vq.ValidityDate,vq.QuoteCurrencyId,vq.Delivery,vd.Remarks,vq.SpecialInstruction,vq.Document,vq.Certificate
,vq.EnquiryID,en.Created,vd.PaymentTerms,vq.guarantee,vn.YearlyTurnover1,vn.YearlyTurnover2,vn.YearlyTurnover3,
vn.VendorName,vn.VendorCode,dd.DealerName,vn.TypeOfBusiness,vn.YearOfEstablishment,vn.EstablishmentID,vq.QuoteCurrencyId,vd.EnquiryDetailsID
from Enquiry en 
                            inner join EnquiryDetails ed on en.EnquiryID = ed.EnquiryID
                            inner join Items i on i.ItemID = ed.ItemID
                            inner join PurchaseSubGroup ps on i.PurchaseSubGroupID = ps.PurchaseSubGroupID
                            inner join UOM um on um.UOMID = i.UOMID
                         INNER JOIN (
    SELECT DISTINCT EnquiryID, ItemCode, Remarks
    FROM PurchaseRequisitionDetails
) pd
    ON pd.EnquiryID = en.EnquiryID AND pd.ItemCode = i.ItemCode
                                                        inner join VendorQuotation vq on vq.EnquiryID=en.EnquiryID
                            inner join VendorQuotationDetails vd on vd.EnquiryDetailsID=ed.EnquiryDetailsID
                            inner join VendorDetails vn on vn.VendorID=vd.VendorID
                            left join DealerDetails dd on dd.DealerID=vn.DealerID                    
                                                        left join VAT gt on gt.VATID = vd.VATID
                            inner join Currency c on c.Currencyid =vq.QuoteCurrencyId        
                                                        
inner join Verification v on v.Code=vn.VendorCode where vq.VendorQuotationID='" + VendorQuotationID + "' and vn.VendorID='" + VendorID + "' and DisabledItem='0'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
