        public DataTable GetPurchaseGroupDetails()
        {
            sQuery = @"SELECT 
         p.PurchaseGroupID, 
         p.PurchaseGroupName, 
         ISNULL(p.IsDisabled, 0) as GroupIsDisabled,
         pg.PurchaseSubGroupID, 
         pg.PurchaseSubGroupName, 
         ISNULL(pg.IsDisabled, 0) as SubGroupIsDisabled,
         t.ItemType
         FROM PurchaseGroup p 
         INNER JOIN PurchaseSubGroup pg ON pg.PurchaseGroupId = p.PurchaseGroupId 
         INNER JOIN Itemtype t ON t.ItemtypeID = p.ItemtypeId
         WHERE p.isactive = 1 AND pg.isactive = 1 
         ORDER BY p.PurchaseGroupName ASC";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
