        public int AddItemCode(DAL.CM obj)
        {
            int modified = 0;

            int prevIdentity = GetReseedIdentity("Items", "ItemID");
            ReseedIdentity("Items", prevIdentity);

            string sQuery = @"insert into Items(ItemCode,ItemDescription,PurchaseSubGroupID,UOMID,StockQuantity,MinStock,MaxStock,HSNCode,CreatedDate,LeadTime,Specification,ItemTypeID,DisabledItem,PurchaseGroupID,CreatedBy,Tolerance) output INSERTED.ItemID
                    values (@ItemCode,@ItemDescription,@PurchaseSubGroupID,@UOMID,@StockQuantity,@MinStock,@MaxStock,@HSNCode,@CreatedDate,@LeadTime,@Rate,@Specification,@ItemTypeID,@DisabledItem,@PurchaseGroupID,@CreatedBy,@Tolerance)";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@ItemCode", obj.ItemCode);
                    cmd.Parameters.AddWithValue("@ItemDescription", obj.ItemDescription.Replace("'", "''"));
                    cmd.Parameters.AddWithValue("@PurchaseSubgroupID", obj.PurchaseSubGroupID);
                    cmd.Parameters.AddWithValue("@UOMID", obj.UOMID);
                    cmd.Parameters.AddWithValue("@StockQuantity", obj.Stock);
                    cmd.Parameters.AddWithValue("@MinStock", obj.MinStock);
                    cmd.Parameters.AddWithValue("@MaxStock", obj.MaxStock);
                    cmd.Parameters.AddWithValue("@HSNCode", obj.HSNCode);
                    cmd.Parameters.AddWithValue("@CreatedDate", DateTime.Now.AddHours(12.5));


                    cmd.Parameters.AddWithValue("@LeadTime", obj.LeadTime);
                    cmd.Parameters.AddWithValue("@ModelNo", obj.ModelNo);
                    cmd.Parameters.AddWithValue("@Rate", obj.Rate);
                    cmd.Parameters.AddWithValue("@Specification", obj.Specification);
                    cmd.Parameters.AddWithValue("@ItemTypeID", obj.ItemTypeID);
                    cmd.Parameters.AddWithValue("@DisabledItem", obj.DisableItem);

                    cmd.Parameters.AddWithValue("@PurchaseGroupID", obj.PurchaseGroupID);
                    cmd.Parameters.AddWithValue("@CreatedBy", obj.EmployeeID);
                    cmd.Parameters.AddWithValue("@tolerance", obj.tolerance);

                    sQuery = @"insert into Items(ItemCode,ItemDescription,PurchaseSubGroupID,UOMID,StockQuantity,MinStock,MaxStock,HSNCode,CreatedDate,Remarks,LeadTime,Rate,Specification,ItemTypeID,DisabledItem,,PurchaseGroupID,CreatedBy) output INSERTED.ItemID
                    values ('" + obj.ItemCode + "','" + obj.ItemDescription.Replace("'", "''") + "'," + obj.PurchaseSubGroupID + "," + obj.UOMID + "," + obj.Stock + "," + obj.MinStock + "," + obj.MaxStock + ",'" + obj.HSNCode + "','" + DateTime.Now.AddHours(12.5) + "','" + obj.Remarks + "'," + "," + obj.LeadTime + ",'" + obj.ModelNo + "'," + obj.Rate + ",'" + obj.Specification + "'," + obj.ItemTypeID + "," + obj.DisableItem + "," + "," + obj.PurchaseGroupID + "," + obj.EmployeeID + ")";
                    _sCon.Open();
                    modified = (int)cmd.ExecuteScalar();
                }
            }
            return modified;
        }
