        public ItemDetails GetItemDetails(string itemCode, string ItemTypeID)
        {
            ItemDetails details = new ItemDetails();
            sQuery = @"SELECT i.ItemDescription, i.StockQuantity, 
                           u.UOMName, i.DisabledItem,ps.IsDisabled,
                           ps.PurchaseSubGroupName,i.Itemcode,i.ItemTypeID
                    FROM Items i 
                    LEFT JOIN UOM u ON i.UOMID = u.UOMID 
                    LEFT JOIN PurchaseSubGroup ps ON i.PurchaseSubGroupID = ps.PurchaseSubGroupID
                    WHERE i.ItemCode = '" + itemCode + "' and i.ItemTypeID=" + ItemTypeID + " and i.isActive=1 AND i.DisabledItem = 0";
            dt = GetDataUsingQuery(sQuery);


            if (dt.Rows.Count > 0)
            {
                foreach (DataRow dr in dt.Rows)
                {
                    details.ItemCode = dr["ItemCode"]?.ToString() ?? string.Empty;
                    details.Description = dr["ItemDescription"]?.ToString() ?? string.Empty;
                    details.ItemType = dr["ItemTypeID"]?.ToString() ?? string.Empty;
                    details.UOMName = dr["UOMName"]?.ToString() ?? string.Empty;
                    details.CategoryName = dr["PurchaseSubGroupName"]?.ToString() ?? string.Empty;
                    details.Stock = dr["StockQuantity"]?.ToString() ?? string.Empty;
                }
            }
            return details;
        }

