        public DataTable GetPurchaseItems(string PurchaseGroupID, string search)
        {
            sQuery = @"Select * from Items i 
                inner join UOM u on u.UOMId = i.UOMId
                inner join PurchaseSubGroup ps on ps.PurchaseSubGroupID=i.PurchaseSubGroupID
                inner join PurchaseGroup pg on pg.PurchaseGroupId=ps.PurchaseGroupID where pg.PurchaseGroupID='" + PurchaseGroupID + "' and ItemCode like '%" + search + "%'  and pg.isActive=1 and pg.IsDisabled =0 and ps.isactive = 1 and ps.IsDisabled =0  order by i.ItemCode asc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
