            string sQuery = @"select distinct i.itemID,i.ItemCode,i.ItemDescription,modelNo,UOMName,
                                        PurchaseGroupName,PurchaseSubGroupName,sf. AvailableStock from items i 
                                        inner join purchasesubgroup ps on i.purchasesubgroupID  = ps.purchasesubgroupID
