        public string GetNextQuotationNumber()
        {
            string nextNumber = "";
            string prefix = "QTN-";

            string query = "SELECT MAX(QuotationNumber) FROM VendorQuotation WHERE QuotationNumber LIKE '" + prefix + "%'";
            DataTable dt = GetDataUsingQuery(query);

            if (dt != null && dt.Rows.Count > 0 && dt.Rows[0][0] != DBNull.Value)
            {
                string lastQuotation = dt.Rows[0][0].ToString(); // e.g., QTN-00023
                int lastNumber = 0;

                if (int.TryParse(lastQuotation.Substring(prefix.Length), out lastNumber))
                {
                    nextNumber = prefix + (lastNumber + 1).ToString("D5"); // QTN-00024
                }
                else
                {
                    nextNumber = prefix + "00001";
                }
            }
            else
            {
                nextNumber = prefix + "00001";
            }

            return nextNumber;
        }

