        public DataTable GetEnquiry(string EnquiryDetailsID, string Reference)
        {
            sQuery = @"Select distinct i.ItemCode,
                            ItemDescription,
                            Specification,
                            
                            ModelNo,
                            OrderedQty,
                            PurchaseSubGroupName,
                            en.Remarks,
                            UOMName,
                            VendorQuotationDetailsID,
                            VendorQuotationID,
                            isnull(vq.deliverytime,0) as DeliveryTime,
							isnull(vq.Rate,0) as QuoteRate,
                            pd.Remarks as UserRemarks
                            from Enquiry en 
                            inner join EnquiryDetails ed on en.EnquiryID = ed.EnquiryID                         
                            inner join Items i on i.ItemID = ed.ItemID
                            inner join PurchaseRequisitionDetails pd on pd.EnquiryID = en.EnquiryID and pd.ItemCode = i.itemCode
                            inner join PurchaseSubGroup ps on i.PurchaseSubGroupID = ps.PurchaseSubGroupID
                            inner join UOM um on um.UOMID = i.UOMID
                            inner join VendorQuotationDetails vq on vq.EnquiryDetailsID=ed.EnquiryDetailsID
                            inner join VendorDetails vn on vn.VendorID=vq.VendorID
							left join Verification v on v.Code=vn.VendorCode where en.EnquiryID ='" + EnquiryDetailsID + "' and v.Reference='" + Reference + "' and DisabledItem='0'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetQuotationStatusDetails(string EnquiryID, string Reference)
        {
            sQuery = @"Select * from VendorQuotation vq 
                            inner join VendorQuotationDetails vd on vd.VendorQuotationID = vq.VendorQuotationID
                            inner join VendorDetails v on v.VendorID = vd.VendorID
                            inner join Verification vr on vr.Code = v.VendorCode 
                            where ReceivedDate is not null and vq.EnquiryID='" + EnquiryID + "' and vd.StatusID=2 and vr.Reference='" + Reference + "' or vq.EnquiryID='" + EnquiryID + "' and vd.StatusID=5 and vr.Reference='" + Reference + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
