        public int UpdateVendorQuotationForNotAvailable(DAL.CM obj)
        {


            string sQuery = @"UPDATE VendorQuotation
                                SET 
                                    StatusID = @StatusID,
                                    QuotationNumber = @QuotationNumber,
                                    Payment = @PaymentTerms,
                                    PaymentTermsAdditional = @PaymentTermsAdditional,
                                    QuoteCurrencyId = @QuoteCurrencyId,
                                    VendorContactPersonID = @ContactPersonID,
                                    ValidityDate = @ValidityDate,
                                    Delivery = @Delivery,
                                    SpecialInstruction = @SpecialInstruction,
                                    Remarks = @Remarks,
                                    Revision = @Revision,
                                    Subtotal = @Subtotal,
                                   GrandTotal =@Grandtotal

                                WHERE EnquiryID = @EnquiryID and VendorID =@VendorID";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    _sCon.Open();

                    // Use parameters to prevent SQL injection and handle nulls
                    cmd.Parameters.AddWithValue("@StatusID", obj.QuotationStatusID);
                    cmd.Parameters.AddWithValue("@QuotationNumber", obj.QuotationNumber ?? "N/A");
                    cmd.Parameters.AddWithValue("@PaymentTerms", obj.PaymentTerms ?? "N/A");
                    cmd.Parameters.AddWithValue("@PaymentTermsAdditional", obj.PaymentTermsAdditional ?? "N/A");
                    cmd.Parameters.AddWithValue("@QuoteCurrencyId", obj.QuoteCurrencyid == 0 ? (object)DBNull.Value : obj.QuoteCurrencyid);
                    cmd.Parameters.AddWithValue("@ContactPersonID", obj.ContactPersonID == 0 ? (object)DBNull.Value : obj.ContactPersonID);
                    cmd.Parameters.AddWithValue("@ValidityDate", obj.ValidityDate);
                    cmd.Parameters.AddWithValue("@Delivery", obj.Delivery ?? "N/A");
                    cmd.Parameters.AddWithValue("@SpecialInstruction", obj.SpecialInstruction ?? "N/A");
                    cmd.Parameters.AddWithValue("@Remarks", obj.Remarks ?? "N/A");
                    cmd.Parameters.AddWithValue("@Revision", obj.Revision);
                    cmd.Parameters.AddWithValue("@EnquiryID", obj.EnquiryID);
                    cmd.Parameters.AddWithValue("@VendorID", obj.VendorID);
                    cmd.Parameters.AddWithValue("@Subtotal", obj.Subtotal);
                    cmd.Parameters.AddWithValue("@Grandtotal", obj.GrandTotal);

                    modified = cmd.ExecuteNonQuery();
                }
            }
            return modified;
        }
