        public DataTable GetPendingPRByTier(int Tier)
        {
            sQuery = @"SELECT distinct pr.CurrentTier,
                                RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                                pr.PRID AS PRID,
                                e.EmployeeName,
                                d.EmployeeDepartmentName,
                                pr.RequestDate,
                                ps.Status,
                                pr.StoreType
                            FROM PurchaseRequisition pr
                            inner join PurchaseRequisitionDetails pd on pr.PRID = pd.PRID
                            LEFT JOIN Employees e ON e.ID = pr.RequestBy
                            inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                            inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                        and pr.CurrentTier=" + Tier + " where ps.StatusID not in (1010,1012,1014,1016) ORDER BY pr.PRID DESC";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetPendingPRByTier(int Tier,
                    string DivisionID = null,
                    DateTime? FromDate = null,
                    DateTime? ToDate = null,
                    string PRNumber = null)
        {
            StringBuilder sql = new StringBuilder();

            sql.Append(@"
                        SELECT DISTINCT
                            pr.CurrentTier,
                            RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)),4) + '/' +
                            RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)),2) + '/' +
                            CAST(YEAR(RequestDate) AS VARCHAR) + '/' + deptcode AS PR,
                            pr.PRID,
                            e.EmployeeName,
                            ed.EmployeeDepartmentName,
                            pr.RequestDate,
                            ps.Status,
                            pr.StoreType
                        FROM PurchaseRequisition pr
                        INNER JOIN PurchaseRequisitionDetails pd
                            ON pr.PRID = pd.PRID
                        LEFT JOIN Employees e
                            ON e.ID = pr.RequestBy
                        INNER JOIN PurchaseRequisitionStatus ps
                            ON ps.StatusID = pr.StatusID
                        INNER JOIN EmployeeDepartment ed
                            ON ed.EmployeeDepartmentID = pr.DepartmentID
                        INNER JOIN Department d
                            ON d.DepartmentID = ed.DepartmentID
                        LEFT JOIN Division dv
                            ON dv.DivisionID = d.DivisionID
                        WHERE
                            pr.CurrentTier = @Tier
                            AND ps.StatusID NOT IN (1010,1012,1014,1016)");

            List<SqlParameter> parameters = new List<SqlParameter>();
            parameters.Add(new SqlParameter("@Tier", Tier));

            if (!string.IsNullOrWhiteSpace(DivisionID) && DivisionID != "0")
            {
                sql.Append(" AND d.DivisionID = @DivisionID");
                parameters.Add(new SqlParameter("@DivisionID", DivisionID));
            }

            if (FromDate.HasValue)
            {
                sql.Append(" AND CAST(pr.RequestDate AS DATE) >= @FromDate");
                parameters.Add(new SqlParameter("@FromDate", FromDate.Value.Date));
            }

            if (ToDate.HasValue)
            {
                sql.Append(" AND CAST(pr.RequestDate AS DATE) <= @ToDate");
                parameters.Add(new SqlParameter("@ToDate", ToDate.Value.Date));
            }

            if (!string.IsNullOrWhiteSpace(PRNumber))
            {
                sql.Append(" AND pr.PRNumber = @PRNumber");
                parameters.Add(new SqlParameter("@PRNumber", PRNumber));
            }

            sql.Append(" ORDER BY pr.PRID DESC");

            return GetDataUsingQuery(sql.ToString(), parameters);
        }
