        public DataTable GetAllocationcompletedWL_mechanical(int EmployeeId, int roleID, int year, int month, string sampleSeries = null)
        {
            DataTable dt = new DataTable();
            string sQuery = "";
            string sampleSeriesFilter = !string.IsNullOrEmpty(sampleSeries) ? " AND sd.sampleidseries = '" + sampleSeries + "'" : "";

            switch (roleID)
            {
                case 2:
                    sQuery = @"select distinct c.CloneCRFSampleID,sd.ID,sd.SampleId,sd.sampleidseries,st.StatusName,sd.id, ci.InquiryID  
                    from SampleDetails sd
                    inner join crfclonelist c on c.sampleid = sd.id 
                    inner join CustomerInquiry ci on ci.InquiryId = c.EnquiryID
                    inner join InquiryStatus st on st.InquiryStatusId = c.CRFStatusID 
                    inner join CRFSampleDetails cs on cs.CloneCRFSampleID = c.CloneCRFSampleID 
                    inner join supervisor s on cs.EmployeeId = s.employeeid and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' and cs.supervisorid=" + EmployeeId +
                           @" and sd.samplestatus in(29,25,15,14,13,17,16,20,26,12,27,18,19) and year(sd.created)=" + year +
                           @" and month(sd.created)= " + month + sampleSeriesFilter;
                    dt = GetDataUsingQuery(sQuery);
                    break;
                case 3:
                    sQuery = @"select AllocatedEmployeeID from Employees where ID=" + EmployeeId;
                    dt = GetDataUsingQuery(sQuery);
                    if (dt.Rows.Count > 0)
                    {
                        sQuery = @"select distinct sd.ID,sd.SampleId,sd.sampleidseries, ci.InquiryID,r.ReportName,r.CodeFileName,a.ReportID ,st.StatusName,c.CloneCRFSampleID
                    from SampleDetails sd
                    inner join crfclonelist c on c.sampleid = sd.id 
                    inner join CustomerInquiry ci on ci.sampleID = sd.ID                                    
                    inner join CRFSampleDetails cs on cs.InquiryId = ci.InquiryId
                    inner join Allocation a on a.SampleId=sd.id
                    inner join ReportList r on r.ReportID = a.ReportID
                    inner join InquiryStatus st on st.InquiryStatusId = a.StatusID 
                    where a.StatusID in(27) and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                               " and year(sd.created)=" + year + " and month(sd.created)=" + month +
                               " and a.EmployeeID=" + dt.Rows[0]["AllocatedEmployeeID"].ToString() + sampleSeriesFilter;
                    }
                    dt = GetDataUsingQuery(sQuery);
                    break;
                default: break;
            }
            return dt;
        }
