        public DataTable GetPR(int EnquiryDetailsID)
        {
            sQuery = @"select RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,pr.PRID from  EnquiryDetails ed
                        inner join Enquiry e on e.EnquiryID = ed.EnquiryID
                        inner join purchaserequisitiondetails pd on pd.ItemCode = ed.ItemCode  and pd.enquiryid=e.EnquiryID
                        inner join PurchaseRequisition pr on pr.PRID = pd.PRID
                        LEFT JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                        where EnquiryDetailsID=" + EnquiryDetailsID;
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetPRDetails(string PRID)
        {
            sQuery = @"
                        SELECT 
                        RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                        pr.PRID AS PRID,pd.PurchaseRequisitionID,
                        e.EmployeeName,
                        i.ItemDescription AS Description,
                        d.EmployeeDepartmentName,
                        pr.RequestDate,
                        pd.StatusID as Status,
                        pt.PRType,
                        pr.StoreType
                    FROM PurchaseRequisition pr
                    LEFT JOIN PurchaseRequisitionDetails pd ON pr.PRID = pd.PRID
                    LEFT JOIN Items i ON i.itemcode = pd.ItemCode 
                    LEFT JOIN Employees e ON e.ID = pr.RequestBy
                    LEFT JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                    LEFT JOIN PurchaseRequisitionStatus ps ON ps.StatusID = pd.StatusID
                    LEFT JOIN PRTypes pt ON pt.PRTypesID = pr.PRTypeID
                    WHERE pr.PRID='" + PRID + "' and pd.StatusID not in(1010,1012,1014,1016)";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
