        public int AddTempGridItem(DAL.CM obj)
        {
            int modified = 0;


            //Start Reseed to avoid identity jump
            int prevIdentity = GetReseedIdentity("TempGrid", "TempId");
            ReseedIdentity("TempGrid", prevIdentity);
            //End Reseed to avoid identity jump

            string sQuery = @"INSERT INTO TempGrid (ItemCode, Description, Category, UOM, Qty, 
                         RequiredOn, StockBalance, Purpose) 
                         OUTPUT INSERTED.TempId 
                         VALUES (@ItemCode, @Description, @Category, @UOM, @Qty, 
                         @RequiredOn, @StockBalance, @Purpose)";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@ItemCode", obj.itemCode);
                    cmd.Parameters.AddWithValue("@Description", obj.descriptiontemp);
                    cmd.Parameters.AddWithValue("@Category", obj.category);
                    cmd.Parameters.AddWithValue("@UOM", obj.uom);
                    cmd.Parameters.AddWithValue("@Qty", obj.qty);
                    cmd.Parameters.AddWithValue("@RequiredOn", obj.requiredOn);
                    cmd.Parameters.AddWithValue("@StockBalance", obj.stockBalance);
                    cmd.Parameters.AddWithValue("@Purpose", obj.purpose);

                    _sCon.Open();
                    modified = (int)cmd.ExecuteScalar();


                }
                return modified;
            }
        }

