                        where pd.StatusID=1013 and pg.PurchaseGroupID='" + PurchaseGroupID + "' and psg.PurchaseSubGroupID = '" + PurchaseSubGroupID + "' and pg.isActive = 1 and pg.IsDisabled = 0 and psg.isactive = 1 and psg.IsDisabled = 0 ";
