        public DataTable GetDetailsForFloatEnquiries(
                        int StartIndex,
                        int PageSize,
                        string PurchaseGroupID = null,
                        string PurchaseSubGroupID = null,
                        string DivisionID = null,
                        DateTime? FromDate = null,
                        DateTime? ToDate = null,
                        string PRNumber = null)
        {
            string baseQuery = @"SELECT COUNT(*) OVER() AS TotalRecords,
                                    RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' +
                                    RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' +
                                    CAST(YEAR(RequestDate) AS VARCHAR) + '/' + deptcode AS PR,
                                    pg.PurchaseGroupName,
                                    pd.ItemCode,
                                    ItemDescription,
                                    Specification,
                                    pd.PurchaseRequisitionID,
                                    pd.Quantity AS PRQty,
                                    s.BlockedStock,
                                    s.AvailableStock,
                                    pd.Stock,
                                    psg.PurchaseSubGroupName,
                                    psg.PurchaseSubGroupID,
                                    i.ItemID,
                                    pd.StatusID,
                                    pr.RequestDate AS PRDate,
                                    pr.PRID,
                                    pd.Remarks
                                FROM PurchaseRequisition pr
                                LEFT JOIN PurchaseRequisitionDetails pd
                                    ON pd.PRID = pr.PRID
                                LEFT JOIN Items i
                                    ON i.ItemCode = pd.ItemCode
                                LEFT JOIN PurchaseSubGroup psg
                                    ON psg.PurchaseSubGroupID = i.PurchaseSubGroupID
                                LEFT JOIN PurchaseGroup pg
                                    ON pg.PurchaseGroupID = psg.PurchaseGroupID
                                LEFT JOIN StockFPU s
                                    ON s.ItemCode = i.ItemCode
                                INNER JOIN EmployeeDepartment ed
                                    ON ed.EmployeeDepartmentID = pr.DepartmentID
                                inner join Department d on d.DepartmentID = ed.DepartmentID
                                LEFT JOIN Division dv
                                    ON dv.DivisionID = d.DivisionID
                                WHERE
                                    pd.StatusID = 1013
                                    AND pg.IsActive = 1
                                    AND pg.IsDisabled = 0
                                    AND psg.IsActive = 1
                                    AND psg.IsDisabled = 0";

            StringBuilder sql = new StringBuilder(baseQuery);

            List<SqlParameter> parameters = new List<SqlParameter>();

            if (!string.IsNullOrWhiteSpace(PurchaseGroupID) && PurchaseGroupID != "NA")
            {
                sql.Append(" AND pg.PurchaseGroupID = @PurchaseGroupID");
                parameters.Add(new SqlParameter("@PurchaseGroupID", PurchaseGroupID));
            }

            if (!string.IsNullOrWhiteSpace(PurchaseSubGroupID) && PurchaseSubGroupID != "")
            {
                sql.Append(" AND psg.PurchaseSubGroupID = @PurchaseSubGroupID");
                parameters.Add(new SqlParameter("@PurchaseSubGroupID", PurchaseSubGroupID));
            }

            if (!string.IsNullOrEmpty(DivisionID) && DivisionID != "0")
            {
                sql.Append(" AND d.DivisionID = @DivisionID");
                parameters.Add(new SqlParameter("@DivisionID", DivisionID));
            }

            //if (FromDate.HasValue)
            //{
            //    sql.Append(" AND CAST(pr.RequestDate AS DATE) >= @FromDate");
            //    parameters.Add(new SqlParameter("@FromDate", FromDate.Value.Date));
            //}

            //if (ToDate.HasValue)
            //{
            //    sql.Append(" AND CAST(pr.RequestDate AS DATE) <= @ToDate");
            //    parameters.Add(new SqlParameter("@ToDate", ToDate.Value.Date));
            //}
            if (FromDate.HasValue)
            {
                sql.Append(" AND pr.RequestDate >= @FromDate");

                SqlParameter pFromDate = new SqlParameter("@FromDate", SqlDbType.DateTime);
                pFromDate.Value = FromDate.Value.Date;

                parameters.Add(pFromDate);
            }

            if (ToDate.HasValue)
            {
                sql.Append(" AND pr.RequestDate < @ToDate");

                SqlParameter pToDate = new SqlParameter("@ToDate", SqlDbType.DateTime);
                pToDate.Value = ToDate.Value.Date.AddDays(1);

                parameters.Add(pToDate);
            }
            if (!string.IsNullOrWhiteSpace(PRNumber))
            {
                sql.Append(@" AND (RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' +
                                    RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' +
                                    CAST(YEAR(RequestDate) AS VARCHAR) + '/' + deptcode) = @PRNumber");
                parameters.Add(new SqlParameter("@PRNumber", PRNumber));
            }

            sql.Append(@" ORDER BY pr.RequestDate DESC
                        OFFSET (" + StartIndex + ") * " + PageSize + " ROWS FETCH NEXT " + PageSize + " ROWS ONLY");
            return GetDataUsingQuery(sql.ToString(), parameters);
        }
        public DataTable GetPurchaseRequisition(string PRID)
        {
            sQuery = @" SELECT PR.* , e.EmployeeName as RequestedBy, ed.EmployeeDepartmentName AS Department,ed.DeptCode,ps.Status,PR.ProjectName
                    FROM PurchaseRequisition PR
					left join PurchaseRequisitionDetails  pd on PR.PRID = pd.PRID
                    LEFT JOIN Employees e ON PR.RequestBy = e.ID 
                    LEFT JOIN EmployeeDepartment ed ON PR.DepartmentID = ed.EmployeeDepartmentID 
					left join PurchaseRequisitionStatus ps on pd.StatusID = ps.StatusID
					left join ProjectMaster pm on pr.ProjectName = pm.ProjectName
                    WHERE PR.PRID ='" + PRID + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
