            //End Reseed to avoid identity jump

            string sQuery = @"insert into PRHistory(PurchaseRequisitionDetailsID,
                                PRStatus,
                                userid,
                                employeeid,
                                departmentid,
                                roleid,
                                createddate,
                                Remarks)output INSERTED.PRHistoryID values(@PurchaseRequisitionDetailsID,
                                @PRStatus,
                                @userid,
                                @employeeid,
                                @departmentid,
                                @roleid,
                                @createddate,
                                @Remarks)";
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@PurchaseRequisitionDetailsID", obj.PurchaseRequisitionDetailsID);
                    cmd.Parameters.AddWithValue("@PRStatus", obj.PRStatus);
                    cmd.Parameters.AddWithValue("@userid", obj.UserID);
