        public DataTable GetVendorList(string purchaseSubGroupID)
        {
            string sQuery = @"
                           SELECT DISTINCT 
                                vd.VendorID, 
                                vd.VendorName, 
                                vc.ContactEmail,
                                vc.contactmobile, 
                                vd.TypeOfBusiness,
                                vc.PrimaryContact
                            FROM VendorDetails vd 
                            LEFT JOIN ContactVendor vc ON vd.VendorID = vc.VendorID 
                                AND vc.PrimaryContact = 'Yes' 
                            WHERE vd.PurchaseSubGroupID IS NOT NULL 
                            AND EXISTS (
                                SELECT 1
                                FROM STRING_SPLIT(vd.PurchaseSubGroupID, ',')
                                WHERE value = @SubGroupID )";

            using (SqlConnection connection = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                using (SqlCommand command = new SqlCommand(sQuery, connection))
                {
                    command.Parameters.AddWithValue("@SubGroupID", purchaseSubGroupID);

                    SqlDataAdapter adapter = new SqlDataAdapter(command);
                    DataTable dt = new DataTable();
                    adapter.Fill(dt);
                    return dt;
                }
            }
        }

