        public DataTable GetAllEnquiry(string EnquiryID)
        {
            sQuery = "Select en.EnquiryID,pr.PRID,en.Created,ed.Quantity,i.*,ps.*,um.UOMName,en.VendorID from Enquiry en" +
                " inner join EnquiryDetails ed on en.EnquiryID=ed.EnquiryID " +
                "inner join Items i on ed.ItemCode =i.ItemCode " +
                " inner join PurchaseRequisitionDetails pr on i.ItemCode=pr.ItemCode  and pr.EnquiryID='" + EnquiryID + "' " +
                " inner join PurchaseSubGroup ps on i.PurchaseSubGroupID=ps.PurchaseSubGroupID" +
                " inner join UOM um on um.UOMID=i.UOMID  where en.EnquiryID= '" + EnquiryID + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        //---------enquiry list----------
        public DataTable GetEnquiryList()
        {
            sQuery = @"SELECT DISTINCT 
                 eq.EnquiryID,
                 vd.VendorID as sent,
                 v.VendorName as NameValues,
                 vd.Rate,
                 q.QuotationStatus,
                 eq.created,
                 i.ItemID,
                 i.ItemCode,
                 i.ItemDescription
             FROM Enquiry eq 
             INNER JOIN EnquiryDetails ed ON eq.EnquiryID = ed.EnquiryID 
             INNER JOIN Items i ON i.itemid = ed.itemid
             INNER JOIN VendorQuotationDetails vd ON vd.EnquiryDetailsID = ed.EnquiryDetailsID 
             INNER JOIN VendorDetails v ON vd.VendorID = v.VendorID
             INNER JOIN PurchaseRequisitionDetails pd ON pd.EnquiryId = eq.EnquiryID
             INNER JOIN PurchaseRequisition pr ON pr.prid = pd.prid
             LEFT JOIN QuotationStatus q ON q.QuotationStatusID = vd.statusID
             WHERE eq.EnquiryID NOT IN (
                 SELECT e.EnquiryID 
                 FROM Enquiry e 
                 INNER JOIN PurchaseOrder po ON e.PurchaseOrderID = po.PurchaseOrderID
             )
             AND vd.statusID = 1 
             ORDER BY eq.EnquiryID DESC, v.VendorName";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
