        public DataTable GetEnquiryList(string StatusID, string EnquiryType)
        {
            switch (EnquiryType)
            {
                case "QuoteSent":
                    clearTables("tempenquiry");
                    sQuery = @"select * into tempenquiry from(Select distinct eq.EnquiryID,i.ItemID,i.itemCode,i.ItemDescription,v.vendorID,v.vendorName,eq.VendorID as sent,vd.Rate,q.QuotationStatus,vd.ReportFileName,vq.VendorQuotationID,eq.Created from Enquiry eq " +
                          @"  inner join EnquiryDetails ed on eq.EnquiryID=ed.EnquiryID 
					inner join Items i on i.itemid = ed.itemid
                    inner join VendorQuotationDetails vd on vd.EnquiryDetailsID=ed.EnquiryDetailsID 
					inner join VendorQuotation vq on vq.VendorQuotationID = vd.VendorQuotationID 
					left join VendorDetails v on v.VendorID = vd.VendorID
                    inner join PurchaseRequisitionDetails pd on pd.EnquiryId = eq.EnquiryID
					inner join PurchaseRequisition pr on pr.prid = pd.prid
                    inner join QuotationStatus q on q.QuotationStatusID = vd.statusID
					and vd.statusID in(" + StatusID + ") where ed.EnquiryDetailsID not in (select ed.EnquiryDetailsID from enquirydetails ed inner join PurchaseOrderDetails pd on ed.EnquiryDetailsID = pd.EnquiryDetailsID where enquiryDetailsStatus=1 group by ed.EnquiryDetailsID having avg(ed.Quantity) = sum(pd.Quantity)))x";
                    int modified = UpdateSQLQuery(sQuery);
                    clearTables("tempenquiryfinal");
                    sQuery = @";with MyCTE1 as (
                      SELECT Item = RTRIM(LTRIM(y.i.value('(./text())[1]', 'nvarchar(4000)'))), EnquiryID,vendorID
                      FROM 
                      ( 
	                        SELECT x = CONVERT(XML, '<i>' + REPLACE(VendorID, ',', '</i><i>') + '</i>').query('.'), EnquiryID,vendorID
	                        from Enquiry where vendorID not like '%]%'
                      ) AS a 
                      CROSS APPLY x.nodes('i') AS y(i)
                ),
                MyCTE2 as (
                    select MyCTE1.EnquiryID, vd.VendorName,MyCTE1.VendorID
                    from MyCTE1
                    left join VendorDetails vd on MyCTE1.Item = vd.VendorID
                )
                
                select * into tempenquiryfinal from(SELECT " +
                                 @"   EnquiryID,vendorID,
                    STUFF(
                        (
                            SELECT ',' + VendorName
                            FROM MyCTE2
                            WHERE (EnquiryID = T2.EnquiryID)
                            FOR XML PATH ('')
                        ),1,1,''
                    ) AS NameValues
                FROM MyCTE2 T2
                GROUP BY EnquiryID,t2.VendorID)x";
                    modified = UpdateSQLQuery(sQuery);
                    sQuery = @"select * from tempenquiry e1 " +
                             @"inner join tempenquiryfinal e2 on e1.enquiryid=e2.enquiryid order by e1.EnquiryID desc";
                    break;
                case "Accepted":
                case "POGenerated":
                case "Others":
                    clearTables("tempenquiry");
                    sQuery = @"select * into tempenquiry from(Select distinct eq.EnquiryID,i.ItemID,i.ItemCode,i.ItemDescription,v.vendorID,v.vendorName,eq.VendorID as sent,vd.Rate,q.QuotationStatus,vd.ReportFileName,vq.VendorQuotationID,eq.Created from Enquiry eq " +
                          @"  inner join EnquiryDetails ed on eq.EnquiryID=ed.EnquiryID 
					inner join Items i on i.itemid = ed.itemid
                    inner join VendorQuotationDetails vd on vd.EnquiryDetailsID=ed.EnquiryDetailsID 
					inner join VendorQuotation vq on vq.VendorQuotationID = vd.VendorQuotationID 
					left join VendorDetails v on v.VendorID = vd.VendorID
                    inner join PurchaseRequisitionDetails pd on pd.EnquiryId = eq.EnquiryID
					inner join PurchaseRequisition pr on pr.prid = pd.prid
                    inner join QuotationStatus q on q.QuotationStatusID = vd.statusID
					and vd.statusID in(" + StatusID + "))x";
                    modified = UpdateSQLQuery(sQuery);

                    clearTables("tempenquiryfinal");
                    sQuery = @";with MyCTE1 as (
                      SELECT Item = RTRIM(LTRIM(y.i.value('(./text())[1]', 'nvarchar(4000)'))), EnquiryID,vendorID
                      FROM 
                      ( 
	                        SELECT x = CONVERT(XML, '<i>' + REPLACE(VendorID, ',', '</i><i>') + '</i>').query('.'), EnquiryID,vendorID
	                        from Enquiry where vendorID not like '%]%'
                      ) AS a 
                      CROSS APPLY x.nodes('i') AS y(i)
                ),
                MyCTE2 as (
                    select MyCTE1.EnquiryID, vd.VendorName,MyCTE1.VendorID
                    from MyCTE1
                    left join VendorDetails vd on MyCTE1.Item = vd.VendorID
                )
                
                select * into tempenquiryfinal from(SELECT " +
                                 @"   EnquiryID,vendorID,
                    STUFF(
                        (
                            SELECT ',' + VendorName
                            FROM MyCTE2
                            WHERE (EnquiryID = T2.EnquiryID)
                            FOR XML PATH ('')
                        ),1,1,''
                    ) AS NameValues
                FROM MyCTE2 T2
                GROUP BY EnquiryID,t2.VendorID)x";
                    modified = UpdateSQLQuery(sQuery);

                    sQuery = @"select * from tempenquiry e1 " +
                             @"inner join tempenquiryfinal e2 on e1.enquiryid=e2.enquiryid order by e1.EnquiryID desc";
                    break;
                default: break;
            }
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
