        public DataTable GetVendorQuoteDetails(int VendorID, string EnquiryID)
        {
            sQuery = @"Select vd.VendorID as Vendor, vd.Discount, vd.DiscountApplied, vd.TotalAfterDiscount,
           vq.Subtotal, vq.GrandTotal, vd.StatusID as QuotationStatus, i.ItemID, 
           i.ItemDescription, i.Specification, i.ModelNo, e.EnquiryID,
           ed.EnquiryDetailsID, v.VendorName, vd.AvailableQuantity, u.UOMName, 
           vd.Rate, v.VendorID, vd.DeliveryTime, vd.PaymentTerms, 
           vd.SpecialInstruction as Remarks, vt.VAT as VAT,
           ed.Quantity as ItemQty
           from VendorQuotation vq
           inner join VendorQuotationDetails vd on vq.VendorQuotationID=vd.VendorQuotationID
           inner join Enquiry e on e.EnquiryID=vq.EnquiryID
           inner join EnquiryDetails ed on ed.EnquiryDetailsID=vd.EnquiryDetailsID
           inner join Items i on i.ItemID=ed.ItemID
           inner join UOM u on u.UOMID=i.UOMID
           inner join VendorDetails v on v.VendorID=vd.VendorID
           LEFT join VAT vt on vt.VATID=vd.VATID
        where vq.EnquiryID='" + EnquiryID + "' and vd.vendorid=" + VendorID;
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }


        public DataTable getQuoteVendors(string EnquiryID)
        {
            sQuery = @"Select distinct vd.VendorID as Vendor,v.VendorName,pd.PurchaseOrderID,vq.QuotationNumber,e.EnquiryID,e.created as EnquiryDate,vq.QuoteCurrencyId,vd.ReportFileName
                     from VendorQuotation vq
                  inner join VendorQuotationDetails vd on vq.VendorQuotationID=vd.VendorQuotationID
                  inner join Enquiry e on e.EnquiryID=vq.EnquiryID
                  inner join EnquiryDetails ed on vd.EnquiryDetailsID=ed.EnquiryDetailsID
                  inner join Items i on i.ItemID=ed.ItemID
                     inner join UOM u on u.UOMID=i.UOMID
			inner join VendorDetails v on v.VendorID=vq.VendorID
                     LEFT join PurchaseOrderDetails pd on pd.VendorQuotationDetailsID=vd.VendorQuotationDetailsID
                  where vq.EnquiryID='" + EnquiryID + "' and vq.QuoteCurrencyID is not null group by vd.VendorID,v.VendorName,pd.VendorQuotationDetailsID," +
                        "pd.PurchaseOrderID,vq.QuotationNumber,e.EnquiryID,vq.QuoteCurrencyId,vd.ReportFileName,e.created";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }



        public DataTable GetQuotationDetails()
        {
            sQuery = @"	SELECT 
                            vq.VendorQuotationID,
                            vq.EnquiryID,
                            vq.VendorID,
                            vq.VendorID as VendorID2,
                            vq.StatusID,
                            vq.QuotationNumber,
                            vq.Rate,
                            vq.DeliveryTime,
                            vq.Remarks,
                            vq.StatusID as Action,
                            vn.VendorName,
                            vn.VendorCode,
                            dd.DealerName,
                            v.Code,
                            STUFF((
                                SELECT DISTINCT ', ' + ps2.PurchaseSubGroupName
                                FROM EnquiryDetails ed2
                                INNER JOIN Items i2 ON i2.ItemID = ed2.ItemID
                                INNER JOIN PurchaseSubGroup ps2 ON i2.PurchaseSubGroupID = ps2.PurchaseSubGroupID
                                WHERE ed2.EnquiryID = en.EnquiryID 
                                FOR XML PATH('')
                            ), 1, 2, '') AS PurchaseSubGroupName,
                            (
                                SELECT SUM(CAST(ed3.Quantity AS INT))
                                FROM EnquiryDetails ed3
                                WHERE ed3.EnquiryID = en.EnquiryID  
                            ) AS TotalQuantity,
                            COUNT(DISTINCT ed.ItemID) AS ItemCount
                        FROM Enquiry en 
                        INNER JOIN VendorQuotation vq ON vq.EnquiryID = en.EnquiryID
                        INNER JOIN VendorDetails vn ON vn.VendorID = vq.VendorID
                        INNER JOIN DealerDetails dd ON dd.DealerID = vn.DealerID
                        INNER JOIN Verification v ON v.Code = vn.VendorCode
                        LEFT JOIN EnquiryDetails ed ON en.EnquiryID = ed.EnquiryID  
                        WHERE vq.StatusID != 1 
                        GROUP BY 
                            vq.VendorQuotationID, 
                            vq.EnquiryID, 
                            vq.VendorID, 
                            vq.StatusID,
                            vq.QuotationNumber,
                            vq.Rate,
                            vq.DeliveryTime,
                            vq.Remarks,
                            en.EnquiryID, 
                            vn.VendorName, 
                            vn.VendorCode, 
                            dd.DealerName, 
                            v.Code
                        ORDER BY vq.VendorQuotationID DESC";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
