        public DataTable GetPODetails(string PurchaseOrderID)
        {
            sQuery = @"Select distinct *,vq.VendorContactPersonID as ContactPerson,(cv.FirstName+' '+cv.LastName) as ContactPersonName from PurchaseOrder po 
                            inner join PurchaseOrderDetails pd on po.PurchaseOrderID=pd.PurchaseOrderID 
                            inner join VendorQuotation vq on vq.VendorQuotationID=pd.VendorQuotationID
							inner join VendorQuotationDetails vqd on vqd.VendorQuotationID=vq.VendorQuotationID
                            inner join VendorDetails vd on vd.VendorID=vqd.VendorID
                            inner join EnquiryDetails ed on ed.EnquiryDetailsID=vqd.EnquiryDetailsID
                            inner join Items i on i.ItemID=ed.ItemID
                            inner join UOM u on u.UOMID=i.UOMID 
                            left join VAT v on v.VATID=pd.VATID
							left join ContactPersonVendor cv on cv.VendorContactPersonID=vqd.VendorContactPersonID
                            where po.PurchaseOrderID='" + PurchaseOrderID + "' and DisabledItem='0'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetPODetails(string PurchaseOrderID, string VendorID)
        {
            sQuery = @"Select distinct *,vqd.ReportFilename AS QuoteNo,vq.VendorContactPersonID as ContactPerson,
                            (cv.FirstName+' '+cv.LastName) as ContactPersonName,vqd.EnquiryDetailsID from PurchaseOrder po 
                            inner join PurchaseOrderDetails pd on po.PurchaseOrderID=pd.PurchaseOrderID 
                            inner join VendorQuotation vq on vq.VendorQuotationID=pd.VendorQuotationID
							inner join VendorQuotationDetails vqd on vqd.VendorQuotationID=vq.VendorQuotationID
                            inner join VendorDetails vd on vd.VendorID=vqd.VendorID
                            inner join EnquiryDetails ed on ed.EnquiryDetailsID=vqd.EnquiryDetailsID
                            inner join Items i on i.ItemID=ed.ItemID
			                left JOIN Currency c ON c.CurrencyID = vq.QuoteCurrencyId
                            inner join UOM u on u.UOMID=i.UOMID 
                            left join VAT v on v.VATID=pd.VATID   
							left join ContactPersonVendor cv on cv.VendorContactPersonID=vqd.VendorContactPersonID
                            where po.PurchaseOrderID='" + PurchaseOrderID + "' and vqd.VendorID='" + VendorID + "' and DisabledItem='0'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
