            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@ItemID", obj.ItemID);
                    cmd.Parameters.AddWithValue("@PurchaseOrderID", obj.PurchaseOrderID);
                    cmd.Parameters.AddWithValue("@Discount", obj.Discount);
                    cmd.Parameters.AddWithValue("@DiscountAmount", obj.DiscountAmount);
                    cmd.Parameters.AddWithValue("@Tax", obj.Tax);
                    cmd.Parameters.AddWithValue("@TotalAmount", obj.TotalAmount);
                    cmd.Parameters.AddWithValue("@CreatedDate", obj.CreatedDate);
                    cmd.Parameters.AddWithValue("@DeliveryDate", obj.DeliveryDate);
                    cmd.Parameters.AddWithValue("@VendorQuotationID", obj.VendorQuotationID);
                    cmd.Parameters.AddWithValue("@Quantity", obj.Quantity);
                    cmd.Parameters.AddWithValue("@Rate", obj.Rate);
                    cmd.Parameters.AddWithValue("@Amount", obj.Amount);
                    cmd.Parameters.AddWithValue("@POStatusID", obj.StatusID);
                    cmd.Parameters.AddWithValue("@AllocatedStock", obj.AllocatedQty);
                    cmd.Parameters.AddWithValue("@ReceivedQty", obj.ReceivedQty);
                    cmd.Parameters.AddWithValue("@TaxAmount", obj.TaxAmount);
                    cmd.Parameters.AddWithValue("@VATID", obj.VATID);
                    cmd.Parameters.AddWithValue("@VendorQuotationDetailsID", obj.VendorQuotationDetailsID);
                    cmd.Parameters.AddWithValue("@EnquiryDetailsID", obj.EnquiryDetailsID);
                    cmd.Parameters.AddWithValue("@PO_OrderedQty", obj.Quantity);
                    cmd.Parameters.AddWithValue("@PO_BalanceQty", obj.Quantity);
                    cmd.Parameters.AddWithValue("@PO_StatusForIT", 0);
                    _sCon.Open();
                    modified = (int)cmd.ExecuteScalar();
                }
            }
            return modified;
        }
