        public DataTable GetPurchaseOrderItemInward(string POID)
        {
            sQuery = @"SELECT
                pod.PODetailsID,
                i.ItemID,
                i.ItemCode,
                i.ItemName,
                pod.Quantity,
                pod.ReceivedQty AS POReceivedQty,
                STUFF((
                    SELECT DISTINCT ', ' + e2.EmployeeName
                    FROM PurchaseRequisitionDetails pd2
                    INNER JOIN PurchaseRequisition pr2 ON pr2.PRID = pd2.PRID
                    INNER JOIN Employees e2 ON e2.ID = pr2.RequestBy
                    WHERE pd2.PurchaseOrderID = po.PurchaseOrderID
                    FOR XML PATH(''), TYPE
                ).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS EmployeeName
            FROM PurchaseOrder po
            INNER JOIN PurchaseOrderDetails pod
                ON pod.PurchaseOrderID = po.PurchaseOrderID
            INNER JOIN Items i
                ON i.ItemID = pod.ItemID
            WHERE po.PurchaseOrderID ='" + POID + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }


