        public DataTable GetAllPendingPO(string from, string to, string PONumber, string description,
                            string Unit, string VendorID, string StoreType, string Amount, string ProjectID)
        {
            sQuery = @"SELECT DISTINCT e.enquiryid, po.PODate, po.PONumber, pd.DeliveryDate, i.itemDescription,
         po.ReportFileName, vd.VendorName, po.PurchaseOrderID, vd.VendorID, ps.POStatus,
         pd.Quantity, ISNULL(Securityreceived, 0) AS SecurityReceived, 
         ISNULL(ReceivedQty, 0) AS POReceivedQty,
         (pd.rate * pd.quantity) AS price, ProjectName                        
         FROM PurchaseOrder po 
         LEFT JOIN ProjectMaster pm ON pm.ProjectID = po.projectid
         LEFT JOIN PurchaseOrderDetails pd ON po.PurchaseOrderID = pd.PurchaseOrderID
         LEFT JOIN EnquiryDetails e ON e.EnquiryDetailsID = pd.EnquiryDetailsID
         LEFT JOIN POStatus ps ON ps.POStatusID = po.PurchaseOrderStatus
         INNER JOIN items i ON i.ItemID = pd.ItemID
         LEFT JOIN VendorDetails vd ON vd.VendorID = po.VendorID 
         WHERE 1=1 
         AND StoreType = 'Engineering' 
         AND POStatus NOT IN('PO Generated', 'Rejected', 'PO Closed') 
         AND pd.Quantity > pd.ReceivedQty";

            if (!string.IsNullOrEmpty(from))
            {
                sQuery += " AND " + from;
            }
            if (!string.IsNullOrEmpty(to))
            {
                sQuery += " AND " + to;
            }
            if (!string.IsNullOrEmpty(PONumber))
            {
                sQuery += " AND " + PONumber;
            }
            if (!string.IsNullOrEmpty(Unit))
            {
                sQuery += " AND " + Unit;
            }
            if (!string.IsNullOrEmpty(VendorID))
            {
                sQuery += " AND " + VendorID;
            }
            if (!string.IsNullOrEmpty(StoreType))
            {
                sQuery += " AND " + StoreType;
            }
            if (!string.IsNullOrEmpty(Amount))
            {
                sQuery += " AND " + Amount;
            }
            if (!string.IsNullOrEmpty(ProjectID))
            {
                sQuery += " AND " + ProjectID;
            }

            sQuery += " ORDER BY po.PODate DESC";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
