        public DataTable getworkorderdetails(int InquiryID, int SampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"		Select distinct ad.CreatedDate AS ReceivedDate,
                                    ad.ServiceRequired AS [Priority],
                                    ad.BuyerCustomerName as Buyer,
                                    sd.Deliverydate AS TargetDate,
                                     isnull(s.StandardName,'') + ' ' + isnull(crf.SampleName,'') + ' ' 
									+ isnull(crf.SampleType,'') + ' ' + isnull(crf.SizeOfSample,'') + ' ' 
									+ isnull(crf.Voltage,'') AS SampleDescription,
                                    crf.Remarks as Remark,
						            sampleIDSeries AS SampleCode,ad.Quantityofproduct AS SampleQuantity,
						            ad.BuyerAddressLine1 + ',' + ad.BuyerAddressLine2 + ',' + ad.BuyerCountry + ',' +ad.BuyerPincode AS CustomerAddress,
                                    ad.PayerContactPerson AS Customer, ad.FactoryName,ad.FactoryAddress
                                    from SampleDetails sd
									inner join CRFCloneList cl on sd.ID = cl.sampleID
									inner join CRFSampleDetails crf on crf.CloneCRFSampleID = cl.CloneCRFSampleID 
									inner join AdditionalDetails ad on ad.InquiryID = crf.InquiryId
                                    inner join CustomerInquiry ci on ad.inquiryid = ci.InquiryId
					                left join Standards s on ci.StandardID=s.StandardID
                                    where ad.InquiryID=" + InquiryID + " and sd.ID =" + SampleID + "";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
