        public DataTable[] getDashboardPurchaseCount(string Period)
        {
            DataTable[] dtDashboardPurchase = new DataTable[5];

            try
            {
                // Initialize all DataTables
                for (int i = 0; i < 5; i++)
                {
                    dtDashboardPurchase[i] = new DataTable();
                }




                // Query 1: Enquiries Sent (statusID = 1)
                if (Period == "ALL")
                {
                    sQuery = @"SELECT DISTINCT 
              eq.EnquiryID,
              vd.VendorID as sent,
              v.VendorName as NameValues,
              vd.Rate,
              q.QuotationStatus,
              eq.created,
              i.ItemID,
              i.ItemCode,
              i.ItemDescription
          FROM Enquiry eq 
          INNER JOIN EnquiryDetails ed ON eq.EnquiryID = ed.EnquiryID 
          INNER JOIN Items i ON i.itemid = ed.itemid
          INNER JOIN VendorQuotationDetails vd ON vd.EnquiryDetailsID = ed.EnquiryDetailsID 
          INNER JOIN VendorDetails v ON vd.VendorID = v.VendorID
          INNER JOIN PurchaseRequisitionDetails pd ON pd.EnquiryId = eq.EnquiryID
          INNER JOIN PurchaseRequisition pr ON pr.prid = pd.prid
          LEFT JOIN QuotationStatus q ON q.QuotationStatusID = vd.statusID
          WHERE vd.statusID = 1";
                }
                else
                {
                    sQuery = @"SELECT DISTINCT 
              eq.EnquiryID,
              vd.VendorID as sent,
              v.VendorName as NameValues,
              vd.Rate,
              q.QuotationStatus,
              eq.created,
              i.ItemID,
              i.ItemCode,
              i.ItemDescription
          FROM Enquiry eq 
          INNER JOIN EnquiryDetails ed ON eq.EnquiryID = ed.EnquiryID 
          INNER JOIN Items i ON i.itemid = ed.itemid
          INNER JOIN VendorQuotationDetails vd ON vd.EnquiryDetailsID = ed.EnquiryDetailsID 
          INNER JOIN VendorDetails v ON vd.VendorID = v.VendorID
          INNER JOIN PurchaseRequisitionDetails pd ON pd.EnquiryId = eq.EnquiryID
          INNER JOIN PurchaseRequisition pr ON pr.prid = pd.prid
          LEFT JOIN QuotationStatus q ON q.QuotationStatusID = vd.statusID
          CROSS APPLY Get_Date_Range('" + Period + @"') dr 
          WHERE eq.created BETWEEN dr.From_Date AND dr.To_Date AND vd.statusID = 1";
                }


                dtDashboardPurchase[0] = GetDataUsingQuery(sQuery);


                // Query 2: Quotation Received (statusID in 2,7)
                if (Period == "ALL")
                {
                    sQuery = @"SELECT DISTINCT 
              eq.EnquiryID,
              i.ItemID,
              i.itemCode,
              i.ItemDescription,
              v.vendorID,
              v.vendorName,
              eq.VendorID as sent,
              vd.Rate,
              q.QuotationStatus,
              vd.ReportFileName,
              vq.VendorQuotationID,
              eq.Created 
          FROM Enquiry eq 
          INNER JOIN EnquiryDetails ed ON eq.EnquiryID = ed.EnquiryID 
          INNER JOIN Items i ON i.itemid = ed.itemid
          INNER JOIN VendorQuotationDetails vd ON vd.EnquiryDetailsID = ed.EnquiryDetailsID 
          INNER JOIN VendorQuotation vq ON vq.VendorQuotationID = vd.VendorQuotationID 
          LEFT JOIN VendorDetails v ON v.VendorID = vd.VendorID
          INNER JOIN PurchaseRequisitionDetails pd ON pd.EnquiryId = eq.EnquiryID
          INNER JOIN PurchaseRequisition pr ON pr.prid = pd.prid
          INNER JOIN QuotationStatus q ON q.QuotationStatusID = vd.statusID
          WHERE vd.statusID IN (2,7)";
                }
                else
                {
                    sQuery = @"SELECT DISTINCT 
              eq.EnquiryID,
              i.ItemID,
              i.itemCode,
              i.ItemDescription,
              v.vendorID,
              v.vendorName,
              eq.VendorID as sent,
              vd.Rate,
              q.QuotationStatus,
              vd.ReportFileName,
              vq.VendorQuotationID,
              eq.Created 
          FROM Enquiry eq 
          INNER JOIN EnquiryDetails ed ON eq.EnquiryID = ed.EnquiryID 
          INNER JOIN Items i ON i.itemid = ed.itemid
          INNER JOIN VendorQuotationDetails vd ON vd.EnquiryDetailsID = ed.EnquiryDetailsID 
          INNER JOIN VendorQuotation vq ON vq.VendorQuotationID = vd.VendorQuotationID 
          LEFT JOIN VendorDetails v ON v.VendorID = vd.VendorID
          INNER JOIN PurchaseRequisitionDetails pd ON pd.EnquiryId = eq.EnquiryID
          INNER JOIN PurchaseRequisition pr ON pr.prid = pd.prid
          INNER JOIN QuotationStatus q ON q.QuotationStatusID = vd.statusID
          CROSS APPLY Get_Date_Range('" + Period + @"') dr 
          WHERE vq.createddate BETWEEN dr.From_Date AND dr.To_Date AND vd.statusID IN (2,7)";
                }

                dtDashboardPurchase[1] = GetDataUsingQuery(sQuery);


                // Query 3: Pending PO (PurchaseOrderStatus = 1)
                if (Period == "ALL")
                {
                    sQuery = @"Select distinct e.enquiryid,po.PONumber,po.PODate,po.SpecialInstructions,po.StoreType,po.ReportFileName,vd.VendorName,po.PurchaseOrderID,vd.VendorID,po.reason,pd.POStatusID from PurchaseOrder po 
                      inner join PurchaseOrderDetails pd on po.PurchaseOrderID=pd.PurchaseOrderID
                      inner join EnquiryDetails e on e.EnquiryDetailsID = pd.EnquiryDetailsID
                      inner join VendorDetails vd on vd.VendorID=po.VendorID 
                      where po.PurchaseOrderStatus=1 and po.ReportFileName is not null";
                }
                else
                {
                    sQuery = @" Select distinct e.enquiryid,po.PONumber,po.PODate,po.SpecialInstructions,po.StoreType,po.ReportFileName,vd.VendorName,po.PurchaseOrderID,vd.VendorID,po.reason,pd.POStatusID from PurchaseOrder po 
                      inner join PurchaseOrderDetails pd on po.PurchaseOrderID=pd.PurchaseOrderID
                      inner join EnquiryDetails e on e.EnquiryDetailsID = pd.EnquiryDetailsID
                      inner join VendorDetails vd on vd.VendorID=po.VendorID 
				CROSS APPLY Get_Date_Range('" + Period + "') dr WHERE po.createddate BETWEEN dr.From_Date AND dr.To_Date AND po.PurchaseOrderStatus = 1 and po.ReportFileName is not null";
                }

                dtDashboardPurchase[2] = GetDataUsingQuery(sQuery);


                // Query 4: Pending Approval Details (statusid in 1,6,9,1005)
                if (Period == "ALL")
                {
                    sQuery = @"SELECT pr.CurrentTier,
                                RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                                pr.PRID AS PRID,
                                e.EmployeeName,
                                d.EmployeeDepartmentName,
                                pr.RequestDate,
                                ps.Status,
                                pr.StoreType
                            FROM PurchaseRequisition pr
                            LEFT JOIN Employees e ON e.ID = pr.RequestBy
                            inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                            inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                        and pr.CurrentTier in(1,2,3,4)";
                }
                else
                {
                    sQuery = @"SELECT pr.CurrentTier,
                                RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                                pr.PRID AS PRID,
                                e.EmployeeName,
                                d.EmployeeDepartmentName,
                                pr.RequestDate,
                                ps.Status,
                                pr.StoreType
                            FROM PurchaseRequisition pr
                            LEFT JOIN Employees e ON e.ID = pr.RequestBy
                            inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                            inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                        and pr.CurrentTier in(1,2,3,4)
          CROSS APPLY Get_Date_Range('" + Period + @"') dr 
          WHERE pr.RequestDate BETWEEN dr.From_Date AND dr.To_Date AND pd.statusid IN (1,6,9,1005)";
                }

                dtDashboardPurchase[3] = GetDataUsingQuery(sQuery);


                // Query 5: Purchase Requisition (statusID = 3)
                if (Period == "ALL")
                {
                    sQuery = @"SELECT *
          FROM purchaserequisition pr
          INNER JOIN purchaserequisitionstatus ps ON pr.StatusID = ps.StatusID 
          WHERE pr.statusID = 3";
                }
                else
                {
                    sQuery = @"SELECT *
          FROM purchaserequisition pr
          INNER JOIN purchaserequisitionstatus ps ON pr.StatusID = ps.StatusID
          CROSS APPLY Get_Date_Range('" + Period + @"') dr 
          WHERE pr.RequestDate BETWEEN dr.From_Date AND dr.To_Date AND pr.statusID = 3";
                }

                dtDashboardPurchase[4] = GetDataUsingQuery(sQuery);


                // Debug output
                System.Diagnostics.Debug.WriteLine("=== Dashboard Purchase Query Results ===");
                for (int i = 0; i < dtDashboardPurchase.Length; i++)
                {
                    int count = dtDashboardPurchase[i]?.Rows.Count ?? 0;
                    System.Diagnostics.Debug.WriteLine($"DataTable[{i}] Row Count: {count}");
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Error in getDashboardPurchase: {ex.Message}");
                System.Diagnostics.Debug.WriteLine($"Stack Trace: {ex.StackTrace}");

                // Ensure connection is closed



                // Initialize empty DataTables if there was an error
                for (int i = 0; i < 5; i++)
                {
                    if (dtDashboardPurchase[i] == null)
                        dtDashboardPurchase[i] = new DataTable();
                }
            }

            return dtDashboardPurchase;
        }
