        public DataTable getTopVendors(int count, string Type)
        {
            switch (Type)
            {
                case "Value":
                    sQuery = @"select top " + count + " VendorName,sum(GrandTotal) as Total from purchaseorder po " +
                        @" inner join VendorDetails v on po.vendorID = v.VendorID 
                      where purchaseorderstatus not in(1,7) and StoreType='Engineering'
                        
                      group by VendorName,GrandTotal order by grandtotal desc";
                    break;
                case "Count":
                    sQuery = @"select top " + count + " VendorName,count(po.vendorid) as Total from purchaseorder po " +
                        @" inner join VendorDetails v on po.vendorID = v.VendorID 
                      where purchaseorderstatus not in(1,7) and StoreType='Engineering'
                     
                      group by VendorName order by count(po.vendorid) desc";
                    break;
                default: break;
            }

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
