        public DataTable getQuotationNEW()
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT 
                        CompanyName AS CustomerName,
                        qm.QuotationMasterId,
                        qm.grandTotal,
                        qs.QuotationStatus,
                        QuotationNumber,
                        qm.Revisioncount,
                        qm.EnquiryId,
                        MAX(qd.revisioncount) AS revisioncount,
                        FORMAT(CAST(QuotationDate AS DATETIME), 'dd-MMM-yyyy') AS FormattedDate,
                        QuotationDate,RequestNo,DepartmentID
                    FROM 
                        QuotationMaster qm
                    INNER JOIN 
                        QuotationDetails qd ON qd.QuotationMasterID = qm.QuotationMasterID
                    INNER JOIN 
                        CompanyDetails cd ON cd.CustomerMasterId = qm.CustomerMasterID
                    INNER JOIN 
                        CustomerQuotationStatus qs ON qs.QuotationStatusID = qm.QuotationStatusId
                    INNER JOIN 
						CustomerInquiry c on c.InquiryId = qm.EnquiryId
                    GROUP BY 
                        CompanyName, 
                        qm.QuotationMasterId, 
                        qm.grandTotal, 
                        qs.QuotationStatus, 
                        QuotationNumber, qm.Revisioncount,qm.EnquiryId,
                        QuotationDate,RequestNo,DepartmentID
                    ORDER BY 
                        QuotationMasterID DESC;";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable searchQuotationNEW(string search)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT 
                        CompanyName AS CustomerName,
                        qm.QuotationMasterId,
                        qm.grandTotal,
                        qs.QuotationStatus,
                        QuotationNumber,
                        qm.Revisioncount,
                        qm.EnquiryId,
                        MAX(qd.revisioncount) AS revisioncount,
                        FORMAT(CAST(QuotationDate AS DATETIME), 'dd-MMM-yyyy') AS FormattedDate,
                        QuotationDate,RequestNo,DepartmentID
                    FROM 
                        QuotationMaster qm
                    INNER JOIN 
                        QuotationDetails qd ON qd.QuotationMasterID = qm.QuotationMasterID
                    INNER JOIN 
                        CompanyDetails cd ON cd.CustomerMasterId = qm.CustomerMasterID
                    INNER JOIN 
                        CustomerQuotationStatus qs ON qs.QuotationStatusID = qm.QuotationStatusId
                    INNER JOIN 
						CustomerInquiry c on c.InquiryId = qm.EnquiryId
                    where QuotationNumber like '%" + search + "%' or CompanyName like '%" + search + "%'" +
                 @"   GROUP BY 
                        CompanyName, 
                        qm.QuotationMasterId, 
                        qm.grandTotal, 
                        qs.QuotationStatus, 
                        QuotationNumber, qm.Revisioncount,qm.EnquiryId,
                        QuotationDate,RequestNo,DepartmentID                     
                      ORDER BY QuotationMasterID DESC;";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable getQuotationFilter(DAL.CM obj)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT 
             CompanyName AS CustomerName,
             qm.QuotationMasterId,
             qm.grandTotal,
             qs.QuotationStatus,
             QuotationNumber,
                                     qm.Revisioncount,
                                     qm.EnquiryId,
             MAX(qd.revisioncount) AS revisioncount,
             FORMAT(CAST(QuotationDate AS DATETIME), 'dd-MMM-yyyy') AS FormattedDate,
             QuotationDate,RequestNo,DepartmentID
         FROM 
             QuotationMaster qm
         INNER JOIN 
             QuotationDetails qd ON qd.QuotationMasterID = qm.QuotationMasterID
         INNER JOIN 
             CompanyDetails cd ON cd.CustomerMasterId = qm.CustomerMasterID
         INNER JOIN 
             CustomerQuotationStatus qs ON qs.QuotationStatusID = qm.QuotationStatusId
         INNER JOIN 
				CustomerInquiry c on c.InquiryId = qm.EnquiryId
		WHERE 1=1";
            string queryEnd = @" GROUP BY 
             CompanyName, 
             qm.QuotationMasterId, 
             qm.grandTotal, 
             qs.QuotationStatus, 
             QuotationNumber, qm.Revisioncount,qm.EnquiryId,
             QuotationDate,RequestNo,DepartmentID
         ORDER BY 
             QuotationMasterID DESC";
            if (!string.IsNullOrEmpty(obj.customerName))
                sQuery += " AND CompanyName LIKE @customerName";

            if (!string.IsNullOrEmpty(obj.QuotationStatus))
                sQuery += " AND qs.QuotationStatus LIKE @QuotationStatus";

            if (!string.IsNullOrEmpty(obj.QuotationNumber))
                sQuery += " AND QuotationNumber LIKE @QuotationNumber";

            if (!string.IsNullOrEmpty(obj.Date.ToString("dd-MM-yyyy")))
            {
                if (obj.Date != DateTime.MinValue)
                {
                    sQuery += " AND FORMAT(CAST(QuotationDate AS DATETIME), 'dd-MM-yyyy') LIKE @FormattedDate";
                }
            }

            sQuery += queryEnd;
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    _sCon.Open();


                    if (!string.IsNullOrEmpty(obj.customerName))
                        cmd.Parameters.AddWithValue("@customerName", "%" + obj.customerName + "%");

                    if (!string.IsNullOrEmpty(obj.QuotationStatus))
                        cmd.Parameters.AddWithValue("@QuotationStatus", "%" + obj.QuotationStatus + "%");

                    if (!string.IsNullOrEmpty(obj.QuotationNumber))
                        cmd.Parameters.AddWithValue("@QuotationNumber", "%" + obj.QuotationNumber + "%");

                    if (!string.IsNullOrEmpty(obj.Date.ToString("dd-MM-yyyy")))
                    {
                        if (obj.Date != DateTime.MinValue)
                        {
                            cmd.Parameters.AddWithValue("@FormattedDate", "%" + obj.Date.ToString("dd-MM-yyyy") + "%");
                        }
                    }

                    using (SqlDataReader dr = cmd.ExecuteReader())
                    {
                        dt.Load(dr);   // ✔ Convert to DataTable
                    }
                }
            }
            return dt;
        }
