        public bool IsEmailExistsForOtherVendors(string email, int currentVendorId)
        {
            string query = "";

            if (currentVendorId == 0)
            {
                // If vendor not saved yet, check if email exists for any vendor
                query = "SELECT COUNT(*) FROM ContactVendor WHERE ContactEmail = '" + email + "'";
            }
            else
            {
                // If vendor exists, check if email exists for other vendors
                query = "SELECT COUNT(*) FROM ContactVendor WHERE ContactEmail = '" + email + "' AND VendorID != " + currentVendorId;
            }

            DataTable dt = GetDataUsingQuery(query);
            if (dt != null && dt.Rows.Count > 0)
            {
                int count = Convert.ToInt32(dt.Rows[0][0]);
                return count > 0;
            }

            return false;
        }
