        public string ToUSD(decimal amount)
        {
            // USD
            CultureInfo usdCulture = new CultureInfo("en-US");
            //return string.Format(usdCulture, "{0:C}", amount);// do not show curreny sybmol - aldiyan 2Feb26
            return amount.ToString("N2", usdCulture);
        }
        public string ToIDR(decimal amount)
        {
            // IDR
            CultureInfo rupiahCulture = new CultureInfo("id-ID");
            //return string.Format(rupiahCulture, "{0:C}", amount); // do not show curreny sybmol - aldiyan 2Feb26
            return amount.ToString("N2", rupiahCulture);
        }
        public decimal ConvertCurrencyStringToDecimal(string input)
        {
            if (string.IsNullOrWhiteSpace(input))
                return 0m;

            // Remove any letters, currency symbols, spaces
            string cleaned = System.Text.RegularExpressions.Regex.Replace(input, @"[^\d,.\-]", "");

            // If both ',' and '.' present, determine which one is decimal separator
            int lastComma = cleaned.LastIndexOf(',');
            int lastDot = cleaned.LastIndexOf('.');

            if (lastComma > lastDot)
            {
                // Comma is decimal separator, remove dots (thousands separator)
                cleaned = cleaned.Replace(".", "").Replace(',', '.');
            }
            else if (lastDot > lastComma)
            {
                // Dot is decimal separator, remove commas (thousands separator)
                cleaned = cleaned.Replace(",", "");
            }
            else
            {
                // Only one or none present, treat ',' as decimal if no dots
                if (cleaned.Contains(",") && !cleaned.Contains("."))
                {
                    cleaned = cleaned.Replace(',', '.');
                }
                else
                {
                    // else no changes needed
                }
            }

            // Parse as invariant culture decimal
            if (decimal.TryParse(cleaned, NumberStyles.AllowDecimalPoint | NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out decimal result))
            {
                return result;
            }

            return 0m;
        }
