        public DataTable getCustomerPO(string DepartmentID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT 
                        CompanyName AS CustomerName,
                        cd.CustomerMasterID,
                        qm.QuotationMasterId,qm.POFile,
                        qm.grandTotal,
                        qs.QuotationStatus as QuotationStatus,
                        QuotationNumber,
                        qm.Revisioncount,
                        qm.EnquiryId,
                        MAX(qd.revisioncount) AS revisioncount,
                        FORMAT(CAST(QuotationDate AS DATETIME), 'dd-MMM-yyyy') AS FormattedDate,
                        WorkOrderNumber,SampleReturn,
                        QuotationDate, ci.DepartmentID, PONumber, ServiceDueDate,qm.CalibrationStatusID, 
						CalibrationStatus                       
                    FROM 
                        QuotationMaster qm
                    INNER JOIN 
                        QuotationDetails qd ON qd.QuotationMasterID = qm.QuotationMasterID
                    INNER JOIN 
                        CompanyDetails cd ON cd.CustomerMasterId = qm.CustomerMasterID
                    INNER JOIN 
                        CustomerQuotationStatus qs ON qs.QuotationStatusID = qm.QuotationStatusId
                    INNER JOIN CustomerInquiry ci on ci.InquiryId = qm.EnquiryId
					INNER JOIN Department d on d.DepartmentID = ci.DepartmentID
                    LEFT JOIN CalibrationStatus cs on cs.CalibrationStatusID = qm.CalibrationStatusID
                    where PONumber is not null and ci.DepartmentID='" + DepartmentID + "'" +
                  @"  GROUP BY 
                        CompanyName, 
						cd.CustomerMasterID,
                        qm.QuotationMasterId, 
                        qm.grandTotal, 
                        qs.QuotationStatus, 
                        WorkOrderNumber,SampleReturn,
                        QuotationNumber, qm.Revisioncount,qm.EnquiryId,qm.POFile,
                        QuotationDate, ci.DepartmentID, PONumber, ServiceDueDate,qm.CalibrationStatusID, 
						CalibrationStatus
                    ORDER BY 
                        QuotationMasterID DESC";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
