        public DataTable getStandardAndReportsData(int inquiryId)
        {
            DataSet ds = new DataSet();
            string sQuery = @"SELECT * FROM CustomerInquiry WHERE InquiryId = " + inquiryId;
            DataTable standardIdsTable = GetDataUsingQuery(sQuery);

            if (standardIdsTable.Rows.Count > 0)
            {
                List<string> standardIds = new List<string>();
                foreach (DataRow row in standardIdsTable.Rows)
                {
                    standardIds.Add(row["StandardID"].ToString());
                }
                string standardIdsList = string.Join(",", standardIds);

                sQuery = @"SELECT * FROM Standards WHERE StandardID IN (" + standardIdsList + ")";
                DataTable standardsTable = GetDataUsingQuery(sQuery);
                standardsTable.TableName = "Standards";
                ds.Tables.Add(standardsTable);

                if (standardsTable.Rows.Count > 0)
                {
                    List<string> allReportIds = new List<string>();

                    foreach (DataRow row in standardsTable.Rows)
                    {
                        string reportList = row["ReportList"].ToString();
                        if (!string.IsNullOrEmpty(reportList))
                        {
                            string[] reportIds = reportList.Split(',');
                            foreach (string reportId in reportIds)
                            {
                                string trimmedId = reportId.Trim();
                                if (!string.IsNullOrEmpty(trimmedId) && !allReportIds.Contains(trimmedId))
                                {
                                    allReportIds.Add(trimmedId);
                                }
                            }
                        }
                    }
                    if (allReportIds.Count > 0)
                    {
                        string reportIdsList = string.Join(",", allReportIds);
                        sQuery = @"SELECT * FROM ReportList WHERE ReportId IN (" + reportIdsList + ") ORDER BY ReportName ASC";
                        DataTable reportsTable = GetDataUsingQuery(sQuery);
                        reportsTable.TableName = "Reports";
                        ds.Tables.Add(reportsTable);
                    }
                }
            }

            return standardIdsTable;
        }
