        public DataTable getStandardAndReportsData(string EnquiryID)
        {
            DataTable dt = new DataTable();
            DataTable dt1 = new DataTable();
            DataTable dt2 = new DataTable();
            sQuery = @"select * from CustomerInquiry where inquiryid= '" + EnquiryID + "'";
            dt = GetDataUsingQuery(sQuery);
            if (dt.Rows.Count > 0)
            {
                string[] ReportID = dt.Rows[0]["TestList"].ToString().Split(new[] { ']' }, StringSplitOptions.RemoveEmptyEntries);
                string[] ReportName = dt.Rows[0]["TestList"].ToString().Split(new[] { ']' }, StringSplitOptions.RemoveEmptyEntries);
                int i = 0;
                foreach (string test in ReportID)
                {
                    string s = test.Replace("[", ""), reportname = "";
                    sQuery = @"select * from ReportList where ReportID in (" + s + ")";
                    dt2 = GetDataUsingQuery(sQuery);
                    if (dt2.Rows.Count > 0)
                    {
                        s = "";
                        foreach (DataRow dr2 in dt2.Rows)
                        {
                            s += dr2["ReportID"].ToString() + ",";
                            reportname += dr2["ReportName"].ToString() + ",";
                        }
                        s = s.Remove(s.Length - 1);
                    }
                    ReportID[i] = s;
                    ReportName[i] = reportname;
                    i++;
                }
                string[] MethodList = dt.Rows[0]["MethodList"].ToString().Split(new[] { ']' }, StringSplitOptions.RemoveEmptyEntries);
                i = 0;
                foreach (string method in MethodList)
                {
                    string s = method.Replace("[", "");
                    MethodList[i] = s; i++;
                }
                string[] PartList = dt.Rows[0]["Part"].ToString().Split(new[] { ']' }, StringSplitOptions.RemoveEmptyEntries);
                i = 0;
                foreach (string Part in PartList)
                {
                    string s = Part.Replace("[", "");
                    PartList[i] = s; i++;
                }
                string[] ReqmtList = dt.Rows[0]["Requirement"].ToString().Split(new[] { ']' }, StringSplitOptions.RemoveEmptyEntries);
                i = 0;
                foreach (string Reqmt in ReqmtList)
                {
                    string s = Reqmt.Replace("[", "");
                    ReqmtList[i] = s; i++;
                }
                string[] RemarkList = dt.Rows[0]["Remarks"].ToString().Split(new[] { ']' }, StringSplitOptions.RemoveEmptyEntries);
                i = 0;
                foreach (string Remark in RemarkList)
                {
                    string s = Remark.Replace("[", "");
                    RemarkList[i] = s; i++;
                }

                dt1.Columns.Add("ReportID");
                dt1.Columns.Add("ReportName");
                dt1.Columns.Add("TestMethodID");
                dt1.Columns.Add("Part");
                dt1.Columns.Add("Requirement");
                dt1.Columns.Add("Remarks");

                for (i = 0; i < ReportID.Length; i++)
                {
                    string[] rid = ReportID[i].Split(',');
                    string[] rn = ReportName[i].Split(',');
                    string[] m = MethodList[i].Split(',');
                    string[] p = PartList[i].Split(',');
                    string[] rq = ReqmtList[i].Split(',');
                    string[] rm = RemarkList[i].Split(',');
                    for (int j = 0; j < rid.Length; j++)
                    {
                        DataRow dr1 = dt1.NewRow();
                        dr1["ReportID"] = rid[j];
                        dr1["ReportName"] = rn[j];
                        dr1["TestMethodID"] = m[j];
                        dr1["Part"] = p[j];
                        dr1["Requirement"] = rq[j];
                        dr1["Remarks"] = rm[j];
                        dt1.Rows.Add(dr1);
                    }
                }
            }
            return dt1;
        }
