        public DataTable GetAllDetailsForFloatEnquiries(int StartIndex, int PageSize)
        {
            sQuery = @"Select COUNT(*) OVER() AS TotalRecords, RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                 pg.PurchaseGroupName,pd.ItemCode,ItemDescription,Specification,pd.PurchaseRequisitionID,
                 pd.Quantity as PRQty,s.BlockedStock,s.AvailableStock,pd.stock,psg.PurchaseSubGroupName,psg.PurchaseSubGroupID,i.ItemID,
                 pd.StatusID,pr.RequestDate as PRDate,pr.PRID,pd.Remarks
                 from PurchaseRequisition pr 
                 left join PurchaseRequisitionDetails pd on pd.PRID=pr.PRID 
                 left join Items i on i.ItemCode=pd.ItemCode 
                 left join PurchaseSubGroup psg on psg.PurchaseSubGroupID=i.PurchaseSubGroupID
                 left join PurchaseGroup pg on pg.PurchaseGroupID=psg.PurchaseGroupID 
                 left join StockFPU s on s.itemcode=i.ItemCode
                 inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                 where pd.StatusID=1013 and pg.isActive=1 and pg.IsDisabled =0 and psg.isactive = 1 
                 and psg.IsDisabled =0 
                 ORDER BY
                    pr.RequestDate DESC, pd.PurchaseRequisitionID DESC
                OFFSET (" + StartIndex + ") * " + PageSize + " ROWS FETCH NEXT " + PageSize + " ROWS ONLY";//Approved by Tier-4 - Director
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
