        public DataTable GetAllPO(string from, string to, string PONumber, string Unit, string VendorID, string StoreType, string Amount, string ProjectID)
        {
            sQuery = @"SELECT DISTINCT e.enquiryid, po.PONumber, po.PODate, pd.DeliveryDate,po.SpecialInstructions,
        po.ReportFileName, vd.VendorName, po.PurchaseOrderID, vd.VendorID, ps.POStatus, po.reason
        FROM PurchaseOrder po 
        LEFT JOIN PurchaseOrderDetails pd ON po.PurchaseOrderID = pd.PurchaseOrderID
        LEFT JOIN EnquiryDetails e ON e.EnquiryDetailsID = pd.EnquiryDetailsID
        LEFT JOIN POStatus ps ON ps.POStatusID = po.PurchaseOrderStatus
        INNER JOIN items i ON i.ItemID = pd.ItemID
        LEFT JOIN VendorDetails vd ON vd.VendorID = po.VendorID 
        WHERE 1=1";

            if (from != "")
            {
                sQuery += " AND " + from;
            }
            if (to != "")
            {
                sQuery += " AND " + to;
            }
            if (PONumber != "")
            {
                sQuery += " AND " + PONumber;
            }
            if (Unit != "")
            {
                sQuery += " AND " + Unit;
            }
            if (VendorID != "")
            {
                sQuery += " AND " + VendorID;
            }
            if (StoreType != "")
            {
                sQuery += " AND " + StoreType;
            }
            if (Amount != "")
            {
                sQuery += " AND " + Amount;
            }
            if (ProjectID != "")
            {
                sQuery += " AND " + ProjectID;
            }

            sQuery += " ORDER BY po.PODate DESC";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        private string[][] ParseGroupedFieldData(string fieldData)
        {
            if (string.IsNullOrEmpty(fieldData))
                return new string[0][];

            List<string[]> groups = new List<string[]>();

            // Remove outer brackets and split by "]["
            string cleaned = fieldData.Trim();
            if (cleaned.StartsWith("[") && cleaned.EndsWith("]"))
            {
                cleaned = cleaned.Substring(1, cleaned.Length - 2);
            }

            // Split into groups
            string[] groupStrings = cleaned.Split(new[] { "][" }, StringSplitOptions.RemoveEmptyEntries);

            foreach (string groupStr in groupStrings)
            {
                // Split each group by commas
                string[] items = groupStr.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

                // Trim each item and filter out empty strings
                List<string> cleanedItems = new List<string>();
                foreach (string item in items)
                {
                    string cleanedItem = item.Trim();
                    if (!string.IsNullOrEmpty(cleanedItem))
                        cleanedItems.Add(cleanedItem);
                }

                groups.Add(cleanedItems.ToArray());
            }

            return groups.ToArray();
        }

        public DataTable getStandardAndReportsDataNew(string EnquiryID)
        {
            DataTable dt = new DataTable();
            DataTable dt1 = new DataTable();

            string sQuery = @"SELECT * FROM CustomerInquiry WHERE InquiryID = " + EnquiryID;
            dt = GetDataUsingQuery(sQuery);

            if (dt.Rows.Count > 0)
            {
                // --- Split Standards ---
                string[] standards = dt.Rows[0]["StandardID"].ToString()
                                        .Split(new[] { ",," }, StringSplitOptions.RemoveEmptyEntries);

                // --- Parse all fields with the same grouping logic ---
                string[][] testListGroups = ParseGroupedFieldData(dt.Rows[0]["TestList"].ToString());
                string[][] methodListGroups = ParseGroupedFieldData(dt.Rows[0]["MethodList"].ToString());
                string[][] partListGroups = ParseGroupedFieldData(dt.Rows[0]["Part"].ToString());
                string[][] reqmtListGroups = ParseGroupedFieldData(dt.Rows[0]["Requirement"].ToString());
                string[][] remarkListGroups = ParseGroupedFieldData(dt.Rows[0]["Remarks"].ToString());

                // --- Define result table ---
                dt1.Columns.Add("StandardID");
                dt1.Columns.Add("StandardName");
                dt1.Columns.Add("ReportID");
                dt1.Columns.Add("ReportName");
                dt1.Columns.Add("TestMethodID");
                dt1.Columns.Add("Part");
                dt1.Columns.Add("Requirement");
                dt1.Columns.Add("Remarks");

                // Process each group (each standard)
                for (int groupIndex = 0; groupIndex < testListGroups.Length; groupIndex++)
                {
                    string[] reportIDs = testListGroups[groupIndex];
                    string[] methods = (groupIndex < methodListGroups.Length) ? methodListGroups[groupIndex] : new string[0];
                    string[] parts = (groupIndex < partListGroups.Length) ? partListGroups[groupIndex] : new string[0];
                    string[] requirements = (groupIndex < reqmtListGroups.Length) ? reqmtListGroups[groupIndex] : new string[0];
                    string[] remarks = (groupIndex < remarkListGroups.Length) ? remarkListGroups[groupIndex] : new string[0];

                    // Get StandardID for this group
                    string stdId = "";
                    if (groupIndex < standards.Length)
                        stdId = standards[groupIndex].Trim(',');
                    else if (standards.Length > 0)
                        stdId = standards[0].Trim(','); // Fallback to first standard

                    // Get Standard Name
                    string stdName = "";
                    if (!string.IsNullOrEmpty(stdId))
                    {
                        DataTable dtStd = GetDataUsingQuery("SELECT StandardName FROM Standards WHERE StandardID = " + stdId);
                        if (dtStd.Rows.Count > 0)
                            stdName = dtStd.Rows[0]["StandardName"].ToString();
                    }

                    // Process each report in this group
                    for (int reportIndex = 0; reportIndex < reportIDs.Length; reportIndex++)
                    {
                        string rid = reportIDs[reportIndex].Trim();

                        // Skip empty report IDs
                        if (string.IsNullOrEmpty(rid))
                            continue;

                        string method = (reportIndex < methods.Length && !string.IsNullOrEmpty(methods[reportIndex]) && methods[reportIndex] != "-")
                            ? methods[reportIndex] : "";
                        string part = (reportIndex < parts.Length && !string.IsNullOrEmpty(parts[reportIndex]) && parts[reportIndex] != "-")
                            ? parts[reportIndex] : "";
                        string req = (reportIndex < requirements.Length && !string.IsNullOrEmpty(requirements[reportIndex]) && requirements[reportIndex] != "-")
                            ? requirements[reportIndex] : "";
                        string remark = (reportIndex < remarks.Length && !string.IsNullOrEmpty(remarks[reportIndex]) && remarks[reportIndex] != "-")
                            ? remarks[reportIndex] : "";

                        string reportname = "";
                        DataTable dt2 = GetDataUsingQuery("SELECT ReportName FROM ReportList WHERE ReportID = " + rid);
                        if (dt2.Rows.Count > 0)
                            reportname = dt2.Rows[0]["ReportName"].ToString();

                        DataRow dr1 = dt1.NewRow();
                        dr1["StandardID"] = stdId;
                        dr1["StandardName"] = stdName;
                        dr1["ReportID"] = rid;
                        dr1["ReportName"] = reportname;
                        dr1["TestMethodID"] = method;
                        dr1["Part"] = part;
                        dr1["Requirement"] = req;
                        dr1["Remarks"] = remark;

                        dt1.Rows.Add(dr1);
                    }
                }
            }
            return dt1;
        }
