        }
        // Helper method to parse field data in both formats
        private string[] ParseFieldData(string data)
        {
            if (string.IsNullOrEmpty(data))
                return new string[0];

            if (data.Contains("]["))
            {
                // Format 1: [value1][value2][value3]
                string[] result = data.Split(new[] { ']' }, StringSplitOptions.RemoveEmptyEntries);
                for (int i = 0; i < result.Length; i++)
                    result[i] = result[i].Replace("[", "").Trim();
                return result;
            }
            else
            {
                // Format 2: [value1,value2,value3]
                string cleaned = data.Trim('[', ']');
                string[] result = cleaned.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                for (int i = 0; i < result.Length; i++)
                    result[i] = result[i].Trim();
                return result;
            }
        }
