        public DataTable Getgeneratetestallocation_PV(string CloneCRFSampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"select s.sampleIDSeries,cs.TestsRequested,cs.SampleName,cs.BatchNo,cs.DescriptionOfTest,
            cs.Specification,cs.TestMethod,cs.ReportName,cs.AllocatedAt,cs.Remarks,
			s.sampleID as sampleUID, e.EmployeeName,e1.EmployeeName  as Supervisor
			from  sampledetails s 
            inner join crfclonelist c on c.sampleid = s.id 
			inner join crfsampledetails cs on cs.CloneCRFSampleID = c.CloneCRFSampleID
            inner join employees e on e.id = cs.employeeid 
			inner join Employees e1 on e1.ID = cs.SupervisorID	
		    where c.CloneCRFSampleID='" + CloneCRFSampleID + "' and s.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetAllocation_PV(int EmployeeId, int roleID, int year, int month, string sampleSeries = null)
        {
            DataTable dt = new DataTable();

            string sampleSeriesFilter = !string.IsNullOrEmpty(sampleSeries) ? " AND sd.sampleidseries = '" + sampleSeries + "'" : "";

            sQuery = @"select distinct sd.ID,sd.SampleId,sd.sampleidseries, csd.InquiryID,r.ReportName,r.codefilename, r.ReportID,
               st.StatusName, cl.CloneCRFSampleID from SampleDetails sd
               INNER JOIN CRFCloneList cl ON cl.sampleID = sd.ID
               INNER JOIN CRFSampleDetails csd ON csd.CloneCRFSampleID = cl.CloneCRFSampleID
               INNER JOIN ReportList r ON r.ReportID = csd.ReportID
               INNER JOIN InquiryStatus st ON st.InquiryStatusId = csd.samplestatus
               where  csd.SampleStatus in(19) and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "'" +
                       " and year(sd.created)=" + year + " and month(sd.created)=" + month +
                       " and csd.EmployeeID=" + EmployeeId + sampleSeriesFilter +
                       " ORDER BY sd.ID";

            dt = GetDataUsingQuery(sQuery);
            if (dt.Rows.Count > 0)
            {

            }
            return dt;
        }

        public DataTable getSampleDetailsForReportGenerationfordepartment_Pv(string Department, string SampleStatus, int year, int month)
        {
            DataTable dt = new DataTable();
            string sQuery = @"select distinct ci.departmentid,sd.id,sd.sampleid,sd.sampleidseries,sd.receiveddate,sd.samplestatus,i.statusname,ReportName ,cr.CloneCRFSampleID 
                          from TestResultsPTQualis td 								
                          inner join sampledetails sd on td.SampleId = sd.id 
                          inner join crfclonelist cr on cr.sampleid = sd.id
                          inner join customerinquiry ci on ci.inquiryID = cr.enquiryid
                          inner join inquirystatus i on i.inquirystatusid=sd.SampleStatus
                          inner join ReportFormat r on r.ReportFormatID = ci.ReportFormat
                          where sd.SampleStatus in(" + SampleStatus + ") and ci.departmentid in(" + Department + ") and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' and year(sd.created)=" + year + " and month(sd.created) =" + month;
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public string generateReportNo_Pv(string SampleID)
        {
            string LastTestReportNo = "", TestReportNo = "";
            string sYear = DateTime.Now.AddHours(12.5).ToString("yy");
            string sMonth = DateTime.Now.AddHours(12.5).ToString("MM");
            string DepartmentID = "";
            DataTable dt2 = getLastTestReportNo(SampleID);

            if (dt2.Rows.Count > 0 && !string.IsNullOrEmpty(dt2.Rows[0]["TestReportNo"].ToString()))
            {
                DepartmentID = dt2.Rows[0]["DepartmentID"].ToString();
                LastTestReportNo = dt2.Rows[0]["TestReportNo"].ToString();
                string[] TestReportString = new string[4];
                string[] firstTerm = new string[2];

                switch (DepartmentID)
                {
                    case "1":   // Transportation        QI-yy/MM/xxxx
                    case "3006":// Electrical            QI-yy/MM/xxxx
                    case "4009":// LED                   QI-yy/MM/xxxx
                        if (!string.IsNullOrEmpty(LastTestReportNo))
                        {
                            TestReportString = LastTestReportNo.Split('/');
                            if (TestReportString.Length >= 3)
                            {
                                int lastItem = Convert.ToInt32(TestReportString[TestReportString.Length - 1]);
                                firstTerm = TestReportString[0].Split('-');
                                try
                                {
                                    if (firstTerm.Length >= 2)
                                    {
                                        string midTerm = firstTerm[1];
                                        if (midTerm.Substring(0, 2) != sYear)
                                        {
                                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                                        }
                                        else
                                        {
                                            int nextItem = lastItem + 1;
                                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/" + nextItem.ToString().PadLeft(4, '0');
                                        }
                                    }
                                    else
                                    {
                                        TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                                    }
                                }
                                catch (Exception ex)
                                {
                                    Console.Write(ex.Message);
                                    TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                                }
                            }
                            else
                            {
                                TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                            }
                        }
                        else
                        {
                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                        }
                        break;

                    case "4017":// LED                   QI-yy/MM/xxxx
                        if (!string.IsNullOrEmpty(LastTestReportNo))
                        {
                            TestReportString = LastTestReportNo.Split('/');
                            if (TestReportString.Length >= 3)
                            {
                                int lastItem = Convert.ToInt32(TestReportString[TestReportString.Length - 1]);
                                firstTerm = TestReportString[0].Split('-');
                                try
                                {
                                    if (firstTerm.Length >= 2)
                                    {
                                        string midTerm = firstTerm[1];
                                        if (midTerm.Substring(0, 2) != sYear)
                                        {
                                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                                        }
                                        else
                                        {
                                            int nextItem = lastItem + 1;
                                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/" + nextItem.ToString().PadLeft(4, '0');
                                        }
                                    }
                                    else
                                    {
                                        TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                                    }
                                }
                                catch (Exception ex)
                                {
                                    Console.Write(ex.Message);
                                    TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                                }
                            }
                            else
                            {
                                TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                            }
                        }
                        else
                        {
                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                        }
                        break;
                    case "4": // Softline                QI/yy/MM/xxxx
                        if (!string.IsNullOrEmpty(LastTestReportNo))
                        {
                            TestReportString = LastTestReportNo.Split('/');
                            if (TestReportString.Length >= 4)
                            {
                                int lastItem = Convert.ToInt32(TestReportString[TestReportString.Length - 1]);
                                try
                                {
                                    if (TestReportString[1] != sYear)
                                    {
                                        TestReportNo = "QI/" + sYear + "/" + sMonth + "/0001";
                                    }
                                    else
                                    {
                                        int nextItem = lastItem + 1;
                                        TestReportNo = "QI/" + sYear + "/" + sMonth + "/" + nextItem.ToString().PadLeft(4, '0');
                                    }
                                }
                                catch (Exception ex)
                                {
                                    Console.Write(ex.Message);
                                    TestReportNo = "QI/" + sYear + "/" + sMonth + "/0001";
                                }
                            }
                            else
                            {
                                TestReportNo = "QI/" + sYear + "/" + sMonth + "/0001";
                            }
                        }
                        else
                        {
                            TestReportNo = "QI/" + sYear + "/" + sMonth + "/0001";
                        }
                        break;

                    case "5": // Food                    QF/yyyyMMxxxx
                        string foodYear = DateTime.Now.AddHours(12.5).ToString("yyyy");
                        string foodMonth = DateTime.Now.AddHours(12.5).ToString("MM");
                        if (!string.IsNullOrEmpty(LastTestReportNo))
                        {
                            TestReportString = LastTestReportNo.Split('/');
                            if (TestReportString.Length >= 2 && TestReportString[1].Length >= 8)
                            {
                                int lastItem = Convert.ToInt32(TestReportString[1].Substring(TestReportString[1].Length - 4));
                                try
                                {
                                    if (TestReportString[1].Substring(0, 4) != foodYear)
                                    {
                                        TestReportNo = "QF/" + foodYear + foodMonth + "0001";
                                    }
                                    else
                                    {
                                        int nextItem = lastItem + 1;
                                        TestReportNo = "QF/" + foodYear + foodMonth + nextItem.ToString().PadLeft(4, '0');
                                    }
                                }
                                catch (Exception ex)
                                {
                                    Console.Write(ex.Message);
                                    TestReportNo = "QF/" + foodYear + foodMonth + "0001";
                                }
