                            else
                            {
                                TestReportNo = "QF/" + foodYear + foodMonth + "0001";
                            }
                        }
                        else
                        {
                            TestReportNo = "QF/" + foodYear + foodMonth + "0001";
                        }
                        break;

                    default:
                        TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                        break;
                }
            }
            else
            {
                // Handle case when no previous data exists (first time)
                // You need to get DepartmentID from another source when there's no previous data
                int roleID = Convert.ToInt32(HttpContext.Current.Session["RoleID"].ToString());
                if (roleID == 5)
                {
                    Console.Error.WriteLine("Error: Sample Management can't generate Report Number");
                }
                else
                {
                    DepartmentID = HttpContext.Current.Session["DeptID"].ToString();

                    switch (DepartmentID)
                    {
                        case "1":   // Transportation
                        case "3006":// Electrical
                        case "4009":// LED
                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                            break;
                        case "4": // Softline
                            TestReportNo = "QI/" + sYear + "/" + sMonth + "/0001";
                            break;
                        case "5": // Food
                            string foodYear = DateTime.Now.AddHours(12.5).ToString("yyyy");
                            string foodMonth = DateTime.Now.AddHours(12.5).ToString("MM");
                            TestReportNo = "QF/" + foodYear + foodMonth + "0001";
                            break;
                        default:
                            TestReportNo = "QI-" + sYear + "/" + sMonth + "/0001";
                            break;
                    }

                }

            }

            return TestReportNo;
        }
