        public DataTable GetTestReportDetails_Pv(string SampleId)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT 
    sd.ID, 
    sd.SampleId, 
    sd.sampleidseries, 
    csd.InquiryID, 
    r.ReportName, 
    r.codefilename, 
    r.ReportID,
    st.StatusName, 
    cl.CloneCRFSampleID, 
    CONCAT('TestReport-SID=', sd.ID, '_RPID=', r.ReportID, '.pdf') as ReportURL,
    tr.PDFPath,
    tr.FileName,
    tr.createdDate
FROM SampleDetails sd
INNER JOIN CRFCloneList cl ON cl.sampleID = sd.ID
INNER JOIN CRFSampleDetails csd ON csd.CloneCRFSampleID = cl.CloneCRFSampleID
INNER JOIN ReportList r ON r.ReportID = csd.ReportID
INNER JOIN InquiryStatus st ON st.InquiryStatusId = csd.samplestatus
LEFT JOIN TestResultsPTQualis tr ON tr.SampleID = sd.ID AND tr.ReportID = r.ReportID
WHERE sd.ID = " + SampleId;
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
