        public int AddTestResultPV(DAL.CM obj, string excelFileName, string excelFilePath, string pdfFilePath,
          DateTime? AnalysisStartingDate, DateTime? AnalysisCompletionDate)

        {
            int modified = 0;

            try
            {



                string sQuery = @"
    INSERT INTO TestResultsPTQualis 
    (createdDate, SampleID, SampleIDSeries, ReportID, FileName, Result, Parameter, PDFPath,AnalysisStartingDate,AnalysisCompletionDate) 
    VALUES (@createdDate, @SampleID, @SampleIDSeries, @ReportID, @FileName, @Result, NULL, @PDFPath,@AnalysisStartingDate,@AnalysisCompletionDate)";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@createdDate", DateTime.Now);
                        cmd.Parameters.AddWithValue("@SampleID", obj.sampleId);
                        cmd.Parameters.AddWithValue("@SampleIDSeries", obj.sampleIDSeries);
                        cmd.Parameters.AddWithValue("@ReportID", obj.ReportID);
                        cmd.Parameters.AddWithValue("@FileName", excelFileName); // Store filename in FileName column
                        cmd.Parameters.AddWithValue("@Result", excelFilePath); // Store Excel path in Result column
                        cmd.Parameters.AddWithValue("@PDFPath", pdfFilePath); // Store PDF path in PDFPath column
                        cmd.Parameters.AddWithValue("@AnalysisStartingDate", (object)AnalysisStartingDate ?? DBNull.Value);
                        cmd.Parameters.AddWithValue("@AnalysisCompletionDate", (object)AnalysisCompletionDate ?? DBNull.Value);


                        _sCon.Open();
                        cmd.ExecuteNonQuery();


                        modified++;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error saving test result: " + ex.Message);


            }
            return modified;
        }




        public int UpdateTestResultPV(DAL.CM obj, string excelFileName, string excelFilePath, string pdfFilePath, DateTime? AnalysisStartingDate,
    DateTime? AnalysisCompletionDate)
        {
            int modified = 0;
            try
            {



                string sQuery = @"
UPDATE TestResultsPTQualis 
SET 
    createdDate = @createdDate,
    SampleIDSeries = @SampleIDSeries,
    FileName = @FileName,
    Result = @Result,
    PDFPath = @PDFPath,
 AnalysisStartingDate = @AnalysisStartingDate,
    AnalysisCompletionDate = @AnalysisCompletionDate
WHERE 
    ReportID = @ReportID 
    AND SampleID = @SampleID";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@createdDate", DateTime.Now);
                        cmd.Parameters.AddWithValue("@SampleID", obj.sampleId);
                        cmd.Parameters.AddWithValue("@SampleIDSeries", obj.sampleIDSeries);
                        cmd.Parameters.AddWithValue("@ReportID", obj.ReportID);
                        cmd.Parameters.AddWithValue("@FileName", excelFileName);
                        cmd.Parameters.AddWithValue("@Result", excelFilePath);
                        cmd.Parameters.AddWithValue("@PDFPath", pdfFilePath);
                        cmd.Parameters.AddWithValue("@AnalysisStartingDate", (object)AnalysisStartingDate ?? DBNull.Value);
                        cmd.Parameters.AddWithValue("@AnalysisCompletionDate", (object)AnalysisCompletionDate ?? DBNull.Value);


                        _sCon.Open();
                        int rowsAffected = cmd.ExecuteNonQuery();


                        if (rowsAffected > 0)
                            modified++;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error updating test result: " + ex.Message);


            }
            return modified;
        }




