            string sampleIdSeries, string inputType, string language, int reportID, int reportParamMapID, string equipmentIds, string workOrderNo,
            string productName, string productBrand, string productModel, string standardID, string standardName, string testMethod, string temperature, string humidity)
        {
            int modified = 0;

            //Start Reseed to avoid identity jump
            int prevIdentity = GetReseedIdentity("TestResultsLED", "ResultID");
            ReseedIdentity("TestResultsLED", prevIdentity);
            //End Reseed to avoid identity jump

            string GetDateTime = DateTime.Today.ToString("dd-MMM-yyyy") + " " + DateTime.Now.ToString("h:mm:ss tt");

            string sQuery = @"INSERT INTO TestResultsLED 
                                (ClauseID, TestDate,TestCompletationDate, Result, Remark, SampleID, SampleIDSeries, InputType, Language, 
                                 ReportID, ReportParamMapID, EquipmentIds, CreatedDateTime, WorkOrderNo, ProductName, ProductBrand, 
                                 ProductModel, StandardID, StandardName, TestMethod, Temperature, Humidity)
                                output INSERTED.ResultID values
                                (@ClauseID, @TestDate, @TestCompletationDate, @Result, @Remark, @SampleID, @SampleIDSeries, @InputType, @Language, 
                                 @ReportID, @ReportParamMapID, @EquipmentIds, @CreatedDateTime, @WorkOrderNo, @ProductName, @ProductBrand, 
