        public DataTable getSampleDetailsForReportGeneration_LED(string Department, string SampleStatus, int year, int month)
        {
            DataTable dt = new DataTable();
            string sQuery = @"select distinct ci.departmentid,sd.id,sd.sampleid,sd.sampleidseries,sd.receiveddate,sd.samplestatus,i.statusname,ReportName ,cr.CloneCRFSampleID 
                                from TestResultsLED td 								
                                inner join sampledetails sd on td.SampleId = sd.id 
                                inner join crfclonelist cr on cr.sampleid = sd.id
                                inner join customerinquiry ci on ci.inquiryID = cr.enquiryid
                                inner join inquirystatus i on i.inquirystatusid=sd.SampleStatus
                                inner join ReportFormat r on r.ReportFormatID = ci.ReportFormat
                                where sd.SampleStatus in(" + SampleStatus + ") and ci.departmentid in(" + Department + ") and sd.OrganizationID ='" + HttpContext.Current.Session["OrganizationID"].ToString() + "' and year(sd.created)=" + year + " and month(sd.created) =" + month;
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
