        public DataTable getworkorderdetailsLED(int InquiryID, int SampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT ad.CreatedDate AS ReceivedDate, ad.ServiceRequired AS [Priority], ad.BuyerCustomerName AS Buyer, ad.Deliverydate AS TargetDate,
                        ad.ProductName AS SampleDescription,crf.Remarks AS Remark,sampleIDSeries AS SampleCode,ad.Quantityofproduct AS SampleQuantity,
                        ad.BuyerAddressLine1 + ',' + ad.BuyerAddressLine2 + ',' + ad.BuyerCountry + ',' + ad.BuyerPincode AS CustomerAddress,ad.PayerContactPerson AS Customer,
                        rf.ReportName, rf.ReportFormatNumber, ci.DepartmentID, d.DepartmentName, ad.FactoryName, ad.FactoryAddress
                       FROM AdditionalDetails ad
                       INNER JOIN CustomerCRFSampleDetails crf ON ad.inquiryid = crf.InquiryId
                       INNER JOIN CRFCloneList cl ON crf.inquiryid = cl.EnquiryID
                       INNER JOIN CustomerInquiry ci ON ad.inquiryid = ci.InquiryId
                        CROSS APPLY STRING_SPLIT(ci.StandardID, ',') AS ids
                       LEFT JOIN Standards s ON s.StandardID = TRY_CAST(ids.value AS INT)
                       INNER JOIN SampleDetails sd ON cl.sampleID = sd.ID
                       INNER JOIN ReportFormat rf ON rf.ReportFormatID = ci.ReportFormat
                       INNER JOIN Department d ON d.DepartmentID = ci.DepartmentID
                      where ad.InquiryID=" + InquiryID + " and sd.ID =" + SampleID + "";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetExistingTestResults_LED_RP(string sampleId, string reportId)
        {
            Dictionary<string, string> parameterResults = new Dictionary<string, string>();

            try
            {
                using (SqlConnection conn = new SqlConnection(ConfigurationManager.ConnectionStrings["CM"].ConnectionString))
                {
                    conn.Open();
                    string query = @"SELECT * FROM TestResultsLED WHERE SampleID = @SampleID AND ReportID = @ReportID AND ClauseID = 0";

                    using (SqlCommand cmd = new SqlCommand(query, conn))
                    {
                        cmd.Parameters.AddWithValue("@SampleID", sampleId);
                        cmd.Parameters.AddWithValue("@ReportID", reportId);

                        using (SqlDataReader reader = cmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string paramId = reader["ReportParamMapID"].ToString();
                                string result = reader["Result"].ToString();
                                parameterResults[paramId] = result;
                            }
                        }
                    }
                }

                DataTable dt = new DataTable();
                dt.Columns.Add("ParameterID", typeof(string));
                dt.Columns.Add("Result", typeof(string));

                foreach (var param in parameterResults)
                {
                    dt.Rows.Add(param.Key, param.Value);
                }

                return dt;
            }
            catch (Exception ex)
            {
                //ScriptManager.RegisterStartupScript(this, GetType(), "DataFetchError",
                //   $"alert('Error fetching existing data: {ex.Message}');", true);
                return null;
            }
        }
