        public DataTable getworkorderdetailsPV(int InquiryID, int SampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT 
                                ad.CreatedDate AS ReceivedDate,ci.DepartmentID,d.DepartmentName,rf.ReportFormatNumber,
ad.BuyerAddressLine1,ad.FactoryAddress,ad.BuyerCustomerName,
                                ad.ServiceRequired AS [Priority],
                                ad.BuyerCustomerName AS Buyer,
                                ad.Deliverydate AS TargetDate,
                                s.StandardName + ' , ' + crf.SampleName + ' , ' + crf.SampleType + ' , ' + crf.SizeOfSample + ' , ' + crf.Voltage AS SampleDescription,
                                crf.SampleName + ' , ' + crf.SizeOfSample + ' , ' + crf.Voltage AS Remark,
                                sampleIDSeries AS SampleCode,
                                ad.Quantityofproduct AS SampleQuantity,
                                ad.BuyerAddressLine1 + ',' + ad.BuyerAddressLine2 + ',' + ad.BuyerCountry + ',' + ad.BuyerPincode AS CustomerAddress,
                                ad.PayerContactPerson AS Customer, ad.FactoryName,ad.FactoryAddress
                            FROM AdditionalDetails ad
                            INNER JOIN CustomerCRFSampleDetails crf ON ad.inquiryid = crf.InquiryId
                            INNER JOIN CRFCloneList cl ON crf.inquiryid = cl.EnquiryID
                            INNER JOIN CustomerInquiry ci ON ad.inquiryid = ci.InquiryId
	inner join Department d on d.DepartmentID =ci.DepartmentID
INNER join ReportFormat rf on rf.ReportFormatID = ci.ReportFormat
                            CROSS APPLY STRING_SPLIT(ci.StandardID, ',') AS ids
                            LEFT JOIN Standards s ON s.StandardID = TRY_CAST(ids.value AS INT)
                            INNER JOIN SampleDetails sd ON cl.sampleID = sd.ID
                            where ad.InquiryID=" + InquiryID + " and sd.ID =" + SampleID + "";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

