        public DataTable getAllSampleDetailsForReportGeneration_New(string DepartmentID, string SampleStatus, int year, int month)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT ci.DepartmentId, sd.Id, sd.SampleId, sd.SampleIdSeries, sd.ReceivedDate, sd.SampleStatus, i.StatusName, r.ReportName,cr.CloneCRFSampleID
                        FROM (
                            SELECT SampleId FROM TestResults
                            UNION ALL
                            SELECT SampleId FROM TestResultsLed
                            UNION ALL
                            SELECT SampleId FROM TestResultsPTQualis
                        ) AS td
                        INNER JOIN SampleDetails sd ON td.SampleId = sd.Id
                        INNER JOIN CrfCloneList cr ON cr.SampleId = sd.Id
                        INNER JOIN CustomerInquiry ci ON ci.InquiryID = cr.EnquiryID
                        INNER JOIN ReportFormat r ON r.ReportFormatID = ci.ReportFormat
                        INNER JOIN InquiryStatus i ON i.InquiryStatusID = sd.SampleStatus
                        INNER JOIN EmployeeDepartment ed on ed.DepartmentID = ci.DepartmentID
                        WHERE ed.EmployeeDepartmentID='" + DepartmentID + "' and sd.SampleStatus IN (" + SampleStatus + ") AND sd.OrganizationID = '" + HttpContext.Current.Session["OrganizationID"].ToString() + "' and year(sd.created)= " + year + " and month(sd.created)= " + month + " ORDER BY sd.ReceivedDate DESC";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }


        public string generateReportNo(string SampleID)
        {
            string LastTestReportNo = "", TestReportNo = "";
            string sYear = DateTime.Now.AddHours(12.5).ToString("yy");
            string sMonth = DateTime.Now.AddHours(12.5).ToString("MM");
            string DepartmentID = "";
            DataTable dt2 = getLastTestReportNo(SampleID);
            if (dt2.Rows.Count > 0)
            {
                DepartmentID = dt2.Rows[0]["DepartmentID"].ToString();
                LastTestReportNo = dt2.Rows[0]["TestReportNo"].ToString();
                string[] TestReportString = new string[4];
                string[] firstTerm = new string[2];
                switch (DepartmentID)
                {
                    case "1":   // Transportation	QI-yy/MM/xxxx

                    case "3006":// Electrical	    QI-yy/MM/xxxx

                    case "4009":// LED	            QI-yy/MM/xxxx
                    case "5020":// Phy. Softline    QI-yy/MM/xxxx
                    case "4006":// PV	            QI-yy/MM/xxxx
                        TestReportString = LastTestReportNo.Split('/');
                        int lastItem = Convert.ToInt32(TestReportString[TestReportString.Length - 1]);
                        //Check year change. Reset series to '0001'
                        firstTerm = TestReportString[0].Split('-');
                        try
                        {
                            string midTerm = firstTerm[1];
                            if (midTerm.Substring(0, 2) != sYear)
                            {
                                TestReportNo = "QI-" + sYear + "/" + sMonth + "/" + "0001";
                            }
                            else
                            {
                                int nextItem = lastItem + 1;
                                TestReportNo = nextItem.ToString().PadLeft(4, '0');
                                TestReportNo = "QI-" + sYear + "/" + sMonth + "/" + TestReportNo;
                            }
                        }
                        catch (Exception ex)
                        {
                            Console.Write(ex.Message);
                        }
                        break;
                    case "4": // Softline QI/yy/MM/xxxx

                        TestReportString = LastTestReportNo.Split('/');

                        lastItem = Convert.ToInt32(TestReportString[3]);

                        // Reset if year changes
                        if (TestReportString[1] != sYear)
                        {
                            TestReportNo = "QI/" + sYear + "/" + sMonth + "/0001";
                        }
                        // Reset if month changes
                        else if (TestReportString[2] != sMonth)
                        {
                            TestReportNo = "QI/" + sYear + "/" + sMonth + "/0001";
                        }
                        else
                        {
                            int nextItem = lastItem + 1;
                            TestReportNo = "QI/" + sYear + "/" + sMonth + "/" + nextItem.ToString("D4");
                        }

                        break;


                    case "5": // Food	            QF/yyyyMMxxxx
                        sYear = DateTime.Now.AddHours(12.5).ToString("yyyy");
                        sMonth = DateTime.Now.AddHours(12.5).ToString("MM");
                        TestReportString = LastTestReportNo.Split('/');
                        lastItem = Convert.ToInt32(TestReportString[1].Substring(TestReportString[1].Length - 4));
                        //Check year change. Reset series to '0001'
                        try
                        {

                            if (TestReportString[1].Substring(0, 4) != sYear)
                            {
                                TestReportNo = "QF/" + sYear + sMonth + "0001";
                            }
                            else
                            {
                                int nextItem = lastItem + 1;
                                TestReportNo = nextItem.ToString().PadLeft(4, '0');
                                TestReportNo = "QF/" + sYear + sMonth + TestReportNo;
                            }
                        }
                        catch (Exception ex)
                        {
                            Console.Write(ex.Message);
                        }
                        break;
                    default:
                        TestReportNo = "QI-" + sYear + "/" + sMonth + "/" + "0001";
                        break;

                }
            }

            return TestReportNo;
        }



        public DataTable getPVdetails(int sampleID)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT t.TestReportNo, cd.CompanyName AS [Applicant],(Title + ' ' + FirstName + ' ' + LastName) AS Attention,
                                FORMAT(sd.ReceivedDate, 'MMMM dd yyyy') AS SampleReceivedDate,
                                STRING_AGG(cf.TestMethod, ' , ') AS TestMethod,
                                ctd.Email,
                                CONCAT_WS(', ', NULLIF(Addressline1, ''), NULLIF(Addressline2, ''), NULLIF(AddressLine3, ''), 
                                    NULLIF(city, ''), NULLIF(pincode, ''), NULLIF(country, '')) AS Address,
                                    samplename AS [SampleDescription],
                                    SampleCondition AS [SampleCondition],
                                    CreatedDate AS [Date],
                                    AnalysisStartingDate AS [TestSample],
                                    AnalysisCompletionDate AS [TestPeriod],
                                    ad.BuyerCustomerName AS [Buyer'sName],
IssueDate,
                                    BatchNo,
                                        ad.CountryOrigin AS [CountryofOrigin],
                                        ad.CountryDestination AS [CountryOfDestination],
                                        InquiryDetail AS [TestPackage],
                                        BrandProduct,
                                        ProductGroupName,
                                        cf.Remarks AS [Remark],
                                        ad.ProductType,
                                        FactoryName,
                                        FactoryAddress,
                                        ad.PersonID,
                                        DateOfExp,
                                        ArticleNumber,
                                    MaterialType,
                                    ItemStyleNo,
                                    pg.ProductGroupName,
                                    ad.LotNumber,
                                    ci.Remarks,
                                    sd.sampleIDSeries,
                                    cf.SizeOfSample AS ProductQuantity,
                                    t.FinalTestResult,
                                    ad.ProductName,
                                    ad.ProductSerialNo,
                                    ad.ProductSpecification,
                                    ad.Color,
                                    cf.WorkorderNumber AS WorkorderNumber
                                FROM testresultdetails t
                                INNER JOIN crfclonelist c ON c.sampleid = t.SampleId
                                INNER JOIN customerinquiry ci ON ci.inquiryid = c.enquiryid
                                LEFT JOIN ProductGroup pg ON pg.ProductGroupID = ci.productCategoryID
                                LEFT JOIN CompanyDetails cd ON cd.customermasterid = ci.customermasterid
                                INNER JOIN LocationDetails lo ON lo.customermasterid = ci.customermasterid
                                INNER JOIN crfsampledetails cf ON cf.clonecrfsampleid = c.clonecrfsampleid
                                INNER JOIN AdditionalDetails ad ON ad.InquiryID = ci.InquiryId
                                INNER JOIN ContactPersonDetails cpd ON ad.PersonID = cpd.PersonId
                                LEFT JOIN ContactDetails ctd ON ctd.PersonId = cpd.PersonId
                                INNER JOIN SampleDetails sd ON sd.ID = t.SampleId 
                                WHERE t.SampleId = '" + sampleID + "'  GROUP BY t.TestReportNo, cd.CompanyName, Title, FirstName, LastName, sd.ReceivedDate, ctd.Email, Addressline1, Addressline2, AddressLine3, city, pincode, country," +
                                "samplename, SampleCondition, CreatedDate, AnalysisStartingDate, AnalysisCompletionDate," +
                                "ad.BuyerCustomerName, BatchNo, ad.CountryOrigin, ad.CountryDestination, InquiryDetail," +
                                "BrandProduct, ProductGroupName, cf.Remarks, ad.ProductType, FactoryName, FactoryAddress," +
                                "ad.PersonID, DateOfExp, ArticleNumber, MaterialType, ItemStyleNo, pg.ProductGroupName," +
                                "ad.LotNumber, ci.Remarks, sd.sampleIDSeries, cf.SizeOfSample, t.FinalTestResult," +
                                "ad.ProductName, ad.ProductSerialNo, ad.ProductSpecification, ad.Color, cf.WorkorderNumber,IssueDate";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

