        public DataTable GetResultOverallConclusion_BH(string sampleId)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT ROW_NUMBER() OVER (ORDER BY tp.TestParameter_BH, c.TestMethod) AS [No.],
                        tp.TestParameter_BH AS [Parameter Uji],
                        c.TestMethod AS [Metode Uji],
                        MAX(c.Requirement) AS [Requirement],
                        CASE 
                            WHEN COUNT(DISTINCT t.Conclusion_BH) = 1 THEN MAX(t.Conclusion_BH)
                            WHEN SUM(CASE WHEN t.Conclusion_BH = 'TIDAK LULUS' THEN 1 ELSE 0 END) > 0 THEN 'TIDAK LULUS'
                            ELSE MAX(t.Conclusion_BH)
                        END AS [Hasil Uji]
                    FROM crfsampledetails c
                    LEFT JOIN TestResults t ON c.crfsampleid = t.crfsampleid
                    LEFT JOIN TestParameter tp ON tp.TestParameterID = c.TestParameterID
                    WHERE t.sampleID = @SampleId
                    GROUP BY tp.TestParameter_BH, c.TestMethod";

            using (SqlConnection conn = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, conn))
                {
                    cmd.Parameters.AddWithValue("@SampleId", sampleId);
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }
            return dt;
        }

        public DataTable GetCRFSampleDetailsList(string searchText)
        {
            string search = searchText ?? string.Empty;

            string sQuery = @"
                SELECT distinct 
                 crf.InquiryId,RequestId,SOWfile,
                 ad.CreatedDate,
                 ad.SRNumber,
                 ad.Suppliername,
                 ad.PayerContactEmail,
                 ist.StatusName,
                 cm.CustomerUID AS CustomerCode
                  FROM CustomerCRFSampleDetails crf
                  INNER JOIN AdditionalDetails ad ON crf.InquiryId = ad.InquiryID
                  INNER JOIN CustomerInquiry ci ON crf.InquiryId = ci.InquiryId
                  INNER JOIN InquiryStatus ist ON ci.InquiryStatusId = ist.InquiryStatusId
                  INNER JOIN CustomerMaster cm ON ci.CustomerMasterId = cm.CustomerMasterId
                  WHERE ci.InquiryStatusId in (21,1041,6)
                  AND ('" + search + @"' = '' OR ad.SRNumber LIKE '%" + search + @"%')
              ORDER BY ad.CreatedDate DESC";

            DataTable dt = GetDataUsingQuery(sQuery);
            return dt;
        }

        public string Encode(string s)
        {
            string encodedEventID = Convert.ToBase64String(Encoding.UTF8.GetBytes(s));
            return encodedEventID;
        }
        public string Decode(string s)
        {
            string encodedString1 = s;
            byte[] decodedBytes1 = Convert.FromBase64String(encodedString1);
            string decodedEventListId1 = Encoding.UTF8.GetString(decodedBytes1);
            return decodedEventListId1;
        }
        public int AddItemInward(DAL.CM obj)
        {
            int modified = 0;
            try
            {



                // Start Reseed to avoid identity jump
                int prevIdentity = GetReseedIdentity("TransactionMaster", "InwardID");
                ReseedIdentity("TransactionMaster", prevIdentity);
                // End Reseed to avoid identity jump

                string sQuery = @"INSERT INTO TransactionMaster (PurchaseOrderID,
