        public DataTable GetGRNDetails(int InwardID)
        {
            sQuery = @"select distinct pod.PODetailsID,i.ItemID,i.ItemCode, ItemName,v.VendorID,PONumber, po.PurchaseOrderID,PODate,
                            PO_OrderedQty,PO_ReceivedQty,
                            STUFF((
                                SELECT DISTINCT ', ' + e2.EmployeeName
                                FROM PurchaseRequisitionDetails pd2
                                INNER JOIN PurchaseRequisition pr2
                                    ON pr2.PRID = pd2.PRID
                                INNER JOIN Employees e2
                                    ON e2.ID = pr2.RequestBy
                                WHERE pd2.PurchaseOrderID = po.PurchaseOrderID
                                  AND pd2.ItemCode = i.ItemCode
                                FOR XML PATH(''), TYPE
                            ).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS EmployeeName,
                            tm.ReceivedDate,td.receivedqty,GRNNumber from TransactionMaster tm
                            inner join Transactiondetails td on tm.InwardID = td.InwardID
                            inner join Items i on i.ItemID = td.ItemID
                            inner join PurchaseOrderDetails pod on pod.PODetailsID = td.PODetailsID
                            inner join PurchaseOrder po on po.PurchaseOrderID = pod.PurchaseOrderID
                            inner join VendorDetails v on v.VendorID = po.VendorID
                            where tm.InwardID=" + InwardID;
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
