        public DataTable GetPRStatus(string PRDID)
        {
            sQuery = @"SELECT  
                    pr.PRID,
                    pr.PRNumber, MAX(ps.StatusID) AS StatusID, 

                    MAX(CASE WHEN ps.ApprovalLevel = 1 THEN ps.StatusType END) AS DeptStatus,
                    MAX(CASE WHEN ps.ApprovalLevel = 2 THEN ps.StatusType END) AS ITHCGAStatus,
                    MAX(CASE WHEN ps.ApprovalLevel = 3 THEN ps.StatusType END) AS DirSalesStatus,
                    MAX(CASE WHEN ps.ApprovalLevel = 4 THEN ps.StatusType END) AS DirectorStatus,

                    CASE 
                        WHEN MAX(vq.PurchaseRequisitionid) IS NULL THEN 'No'
                        ELSE 'Created'
                    END AS QuoteStatus,

                    CASE 
                        WHEN MAX(po.VendorQuotationDetailsID) IS NULL THEN 'No'
                        ELSE 'Created'
                    END AS POStatus,

                    CASE 
                        WHEN MAX(gr.TransactionID) IS NULL THEN 'No'
                        ELSE 'Created'
                    END AS GRNStatus

                FROM PurchaseRequisition pr
                INNER JOIN PurchaseRequisitionDetails pd 
                    ON pr.PRID = pd.PRID

                LEFT JOIN PRHistory pa 
                    ON pd.PurchaseRequisitionid = pa.PurchaseRequisitiondetailsID

                LEFT JOIN PurchaseRequisitionStatus ps 
                    ON ps.StatusID = pa.PRStatus

                LEFT JOIN VendorQuotationDetails vq 
                    ON pd.PurchaseRequisitionid = vq.PurchaseRequisitionid

                LEFT JOIN PurchaseOrderDetails po 
                    ON po.VendorQuotationDetailsID = vq.VendorQuotationDetailsID

                LEFT JOIN TransactionDetails gr 
                    ON po.PODetailsID = gr.PODetailsID

                WHERE pd.PurchaseRequisitionID = " + PRDID +

                @" GROUP BY 
                    pr.PRID,
                    pr.PRNumber;";
            //            sQuery = @"SELECT 
            //    pr.PRID,
            //    pr.PRNumber,ps.StatusID,

            //    MAX(CASE WHEN ps.ApprovalLevel = 1 THEN ps.StatusType END) AS DeptStatus,
            //    MAX(CASE WHEN ps.ApprovalLevel = 2 THEN ps.StatusType END) AS ITHCGAStatus,
            //    MAX(CASE WHEN ps.ApprovalLevel = 3 THEN ps.StatusType END) AS DirSalesStatus,
