            //    CASE WHEN vq.PurchaseRequisitionid IS NULL THEN 'No' ELSE 'Create' END AS QuoteStatus,
            //    CASE WHEN po.VendorQuotationDetailsID IS NULL THEN 'No' ELSE 'Create' END AS POStatus,
            //    CASE WHEN gr.TransactionID IS NULL THEN 'No' ELSE 'Create' END AS GRNStatus

            //FROM PurchaseRequisition pr
            //inner join PurchaseRequisitiondetails pd on pr.prid=pd.prid
            //LEFT JOIN PRHistory pa ON pd.PurchaseRequisitionid = pa.PurchaseRequisitiondetailsID
            //LEFT JOIN VendorQuotationdetails vq ON pd.PurchaseRequisitionid = vq.PurchaseRequisitionid
            //LEFT JOIN PurchaseOrderDetails po ON po.VendorQuotationDetailsID = vq.VendorQuotationDetailsID
            //LEFT JOIN Transactiondetails gr ON po.podetailsid = gr.podetailsid
            //inner join PurchaseRequisitionStatus ps on ps.StatusID = pd.StatusID
            //where pd.prid='" + PRID + "'" +
            //@" GROUP BY 
            //pr.PRID, pr.PRNumber, vq.PurchaseRequisitionid, po.VendorQuotationDetailsID, gr.podetailsid,gr.TransactionID,ps.StatusID";
