        public int AddAdditionalDetailsHomeAppliances_HA(DAL.CM obj)
        {
            int modified = 0;


            {

            }

            int prevIdentity = GetReseedIdentity("AdditionalDetails", "AdditionalDetailsID");
            ReseedIdentity("AdditionalDetails", prevIdentity);

            string sQuery = @"INSERT INTO AdditionalDetails(
                                InquiryID,
                                RequestId,
                                CustomerMasterID,
                                PersonID,
                                BuyerCustomerName,
                                BuyerAddressLine1,
                                BuyerAddressLine2,
                                BuyerPincode,
                                BuyerCountry,
                                ServiceRequired,
                                SampleReturn,
                                ReportRecipient,
                                InvoiceRecipient,
                                PayerName,
                                PayerContactPerson,
                                PayerContactNo,
                                PayerContactEmail,
                                ProductType,
                                PONo,
                                CountryOrigin,
                                CountryDestination,
                                ItemStyleNo,
                                CreatedDate,
                                Suppliername,
                             
                                BrandProduct,
                                FactoryName,
                                FactoryAddress,
                              
                                MaterialType,
                                Servicereceivedby, 
                          
                                Quantityofproduct, 
                                Deliverydate, 
                                ProductName, 
                                ProductSpecification,
Identifier,TypeNumber,FileName
                            ) 
                            OUTPUT INSERTED.AdditionalDetailsID 
                            VALUES (
                                @InquiryID,
                                @RequestId,
                                @CustomerMasterID,
                                @PersonID,
                                @BuyerCustomerName,
                                @BuyerAddressLine1,
                                @BuyerAddressLine2,
                                @BuyerPincode,
                                @BuyerCountry,
                                @ServiceRequired,
                                @SampleReturn,
                                @ReportRecipient,
                                @InvoiceRecipient,
                                @PayerName,
                                @PayerContactPerson,
                                @PayerContactNo,
                                @PayerContactEmail,
                                @ProductType,
                                @PONo,
                                @CountryOrigin,
                                @CountryDestination,
                                @ItemStyleNo,
                                @CreatedDate,
                                @Suppliername,                              
                                @BrandProduct,
                                @FactoryName,
                                @FactoryAddress,                                
                                @MaterialType,
                                @Servicereceivedby,                                                               
                                @Quantityofproduct, 
                                @Deliverydate, 
                                @ProductName, 
                                @ProductSpecification,
                                @Identifier,@TypeNumber,@FileName
                            )";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    // Helper for DateTime safety
                    object SafeSqlDateTime(DateTime date) =>
                        (date > System.Data.SqlTypes.SqlDateTime.MinValue.Value &&
                         date < System.Data.SqlTypes.SqlDateTime.MaxValue.Value)
                            ? (object)date
                            : DBNull.Value;

                    string dateTime = DateTime.Today.ToString("MMM dd yyyy hh:mmtt");

                    // Add parameters
                    cmd.Parameters.AddWithValue(@"InquiryID", obj.inquiryId);
                    cmd.Parameters.AddWithValue(@"RequestId", obj.RequestID);
                    cmd.Parameters.AddWithValue(@"CustomerMasterID", obj.CustomerMasterId);
                    cmd.Parameters.AddWithValue(@"PersonID", obj.personId);
                    cmd.Parameters.AddWithValue(@"BuyerCustomerName", obj.BuyerCustomerName);
                    cmd.Parameters.AddWithValue(@"BuyerAddressLine1", obj.BuyerAddressLine1);
                    cmd.Parameters.AddWithValue(@"BuyerAddressLine2", obj.BuyerAddressLine2);
                    cmd.Parameters.AddWithValue(@"BuyerPincode", obj.BuyerPincode);
                    cmd.Parameters.AddWithValue(@"BuyerCountry", obj.BuyerCountry);
                    cmd.Parameters.AddWithValue(@"ServiceRequired", obj.ServiceRequired);
                    cmd.Parameters.AddWithValue(@"SampleReturn", obj.SampleReturn);
                    cmd.Parameters.AddWithValue(@"ReportRecipient", obj.ReportRecipient);
                    cmd.Parameters.AddWithValue(@"InvoiceRecipient", obj.InvoicePayment);
                    cmd.Parameters.AddWithValue(@"PayerName", obj.PayerName);
                    cmd.Parameters.AddWithValue(@"PayerContactPerson", obj.PayerContactPerson);
                    cmd.Parameters.AddWithValue(@"PayerContactNo", obj.PayerContactNo);
                    cmd.Parameters.AddWithValue(@"PayerContactEmail", obj.PayerEmail);
                    cmd.Parameters.AddWithValue(@"ProductType", obj.ProductType);
                    cmd.Parameters.AddWithValue(@"PONo", obj.PO);
                    cmd.Parameters.AddWithValue(@"CountryOrigin", obj.CountryOfOrigin);
                    cmd.Parameters.AddWithValue(@"CountryDestination", obj.CountryOfDestination);
                    cmd.Parameters.AddWithValue(@"ItemStyleNo", obj.ItemStyle);
                    cmd.Parameters.AddWithValue(@"CreatedDate", SafeSqlDateTime(DateTime.Now));
                    cmd.Parameters.AddWithValue(@"Suppliername", obj.SupplierName);
                    // cmd.Parameters.AddWithValue(@"ArticleNumber", obj.ArticleNumber);
                    cmd.Parameters.AddWithValue(@"BrandProduct", obj.BrandProduct);
                    cmd.Parameters.AddWithValue(@"FactoryName", obj.FactoryName);
                    cmd.Parameters.AddWithValue(@"FactoryAddress", obj.FactoryAddress);
                    //cmd.Parameters.AddWithValue(@"LotNumber", obj.LotNumber);
                    cmd.Parameters.AddWithValue(@"MaterialType", obj.ProductType);

                    cmd.Parameters.AddWithValue(@"Servicereceivedby", SafeSqlDateTime(obj.ServiceRequiredBy));



                    cmd.Parameters.AddWithValue(@"Quantityofproduct", obj.Quantityofproduct);
