                    cmd.Parameters.AddWithValue("@StandardName", standardName);
                    cmd.Parameters.AddWithValue("@TestMethod", testMethod);
                    cmd.Parameters.AddWithValue("@Temperature", temperature);
                    cmd.Parameters.AddWithValue("@Humidity", humidity);
                    cmd.Parameters.AddWithValue("@StandardID", standardID);

                    cmd.Parameters.AddWithValue("@TestCategory", TestCategory);
                    cmd.Parameters.AddWithValue("@Ranking", Ranking);
                    cmd.Parameters.AddWithValue("@SampleCode", sampleCode);
                    cmd.Parameters.AddWithValue("@RequestNumber", RequestNo);
                    cmd.Parameters.AddWithValue("@TestEquipmentNumber", TestEquipmentNo);

                    try
                    {
                        _sCon.Open();
                        modified = (int)cmd.ExecuteScalar();
                    }
                    catch (Exception ex)
                    {
                        string s = ex.Message;
                    }

                }
            }
            return modified;
        }

