        public DataTable GetCOADetails()
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT 
                            L4.AccountID AS AccountID,
                            L4.AccountCode AS AccountCode,
                            L4.AccountName AS AccountName,
                            L4.AccountNameEng AS AccountNameEng,
                            'N-T' as Tax,0 as Balance,

                            L3.AccountID AS ParentID,
                            L3.AccountCode AS Level3Code,
                            L3.AccountName AS Level3Name,

                            H.AccountID AS Level2ID,
                            H.AccountCode AS Level2Code,
                            H.AccountName AS Level2Name

                        FROM ChartOfAccountsDetail L4

                        INNER JOIN ChartOfAccountsHeader L3 
                            ON L4.ParentID = L3.AccountID      

                        INNER JOIN ChartOfAccountsHeader H
                            ON L3.ParentID = H.AccountID 
            ORDER BY L4.AccountCode
                        ";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

        public DataTable getQuotationdetails(int InquiryID, int SampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"		Select distinct 
                                    ad.CreatedDate AS ReceivedDate,
                                    ad.ServiceRequired AS [Priority],
                                    ad.BuyerCustomerName as Buyer,cf.BatchNo,
                                    ad.Deliverydate AS TargetDate,dp.DepartmentName,
                                    s.StandardName + ' , ' + crf.SampleName + ' , ' + crf.SampleType + ' , ' + crf.SizeOfSample + ' , ' + crf.Voltage AS SampleDescription,
                                    crf.SampleName + ' , '+  crf.SizeOfSample + ' , ' + crf.Voltage AS Remark,
						            sampleIDSeries AS SampleCode,ad.Quantityofproduct AS SampleQuantity,
						            ad.BuyerAddressLine1 + ',' + ad.BuyerAddressLine2 + ',' + ad.BuyerCountry + ',' +ad.BuyerPincode AS CustomerAddress,
                                    ad.PayerContactPerson AS Customer
                                    from AdditionalDetails ad
                                    inner join CustomerCRFSampleDetails crf on ad.inquiryid = crf.InquiryId
                                    inner join CRFCloneList cl on crf.inquiryid = cl.EnquiryID
					                inner join CustomerInquiry ci on ad.inquiryid = ci.InquiryId
					                left join Standards s on ci.StandardID=s.StandardID
inner join Department dp on dp.DepartmentID = ci.DepartmentID
                                    inner join SampleDetails sd on cl.sampleID = sd.ID
	inner join CRFSampleDetails cf on cf.InquiryId = ci.InquiryId
                                    where ad.InquiryID=" + InquiryID + " and sd.ID =" + SampleID + "";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

        public DataTable GetManagementreport_FOODCHEMICAL(int InquiryID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"
                    WITH DistinctTestMethods AS (
                        SELECT 
                            InquiryId,
                            samplename,
                            STRING_AGG(testmethod, ', ') AS TestMethods
                        FROM (
                            SELECT DISTINCT InquiryId, samplename, testmethod
                            FROM CRFSampleDetails
                        ) d
                        GROUP BY InquiryId, samplename
                    )
                    SELECT DISTINCT
                        ci.RequestNo,
                        ci.InquiryId,ci.DepartmentID,vt.Percentage,
                        cf.samplename,cf.TAFNo,qd.TotalAmount, 
                        dtm.TestMethods,qm.Discount,qm.VatAmount,qm.VATId,qm.GrandTotal,
                        qm.QuotationMasterID,ci.InquiryDetail,cf.batchno,
                        qm.QuotationNumber,
                        cf.WorkorderNumber,
                        qd.Price,
                        qd.Quantity,
                        qd.UOMId,
                        qm.GrandTotal
                    FROM CustomerInquiry ci
                    INNER JOIN QuotationMaster qm 
                        ON qm.EnquiryId = ci.InquiryId
                    INNER JOIN CRFSampleDetails cf  
                        ON cf.InquiryId = ci.InquiryId
                    INNER JOIN DistinctTestMethods dtm 
                        ON dtm.InquiryId = cf.InquiryId
                       AND dtm.samplename = cf.samplename
                    INNER JOIN CRFCloneList cl 
                        ON cl.EnquiryID = cf.InquiryId
                    INNER JOIN QuotationDetails qd 
                        ON qd.QuotationMasterID = qm.QuotationMasterID
                    LEFT JOIN VAT vt on vt.VATID = qm.VATId
                    WHERE ci.InquiryId = '" + InquiryID + "'";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
