        public DataTable GetWorkOrderDetailsByInquiryID_FOODCHEMICAL(int InquiryID)
        {
            DataTable dt = new DataTable();
            string sQuery = @" SELECT  
    cf.WorkOrderNumber,
    ad.CreatedDate AS ReceivedDate,
    ad.ServiceRequired AS Priority,
    ad.BuyerCustomerName AS Buyer, 
    tr.analysisstartingdate AS StartTest,
    cf.TestParameter,
    cf.TestSubParameter,
    cf.TestSubSubParameter,ci.DepartmentID,
    tr.AnalysisCompletionDate AS EndTest, 
    cf.TestMethod,  
