        public DataTable GetWorkOrderDetailsByInquiryID_ForALlDepartment(int InquiryID)
        {
            DataTable dt = new DataTable();
            string sQuery = @" SELECT  distinct 
    cf.WorkOrderNumber,
    ad.CreatedDate AS ReceivedDate,
    ad.ServiceRequired AS Priority,
    ad.BuyerCustomerName AS Buyer, 
    tr.analysisstartingdate AS StartTest,
  cf.ReportName,cf.TestStandardID,ci.DepartmentID,
    tr.AnalysisCompletionDate AS EndTest, 
    cf.TestMethod,  
    ad.Deliverydate AS TargetDate,
    ISNULL(cf.SampleName, '') + ',' +
    ISNULL(cf.SampleType, '')   + ',' +
    ISNULL(cf.SizeOfSample, '') 
 AS SampleDescription,
    ISNULL(cf.SampleName, 'NA') + ' , ' +
    ISNULL(cf.SizeOfSample, 'NA') + ' , ' +
    ISNULL(cf.Voltage, 'NA')      AS Remark,
    sampleIDSeries AS SampleCode,
    ad.Quantityofproduct AS SampleQuantity,cf.Part,cf.Requirement,
    ISNULL(ad.BuyerAddressLine1, 'NA') + ',' +
    ISNULL(ad.BuyerAddressLine2, 'NA') + ',' +
    ISNULL(ad.BuyerCountry, 'NA') + ',' +
    ISNULL(ad.BuyerPincode, 'NA') AS CustomerAddress,
    ISNULL(ad.PayerContactPerson, 'NA') AS Customer
FROM AdditionalDetails ad
INNER JOIN CustomerInquiry ci ON ad.inquiryid = ci.InquiryId
INNER JOIN CRFSampleDetails cf ON cf.InquiryId = ci.InquiryId	      
INNER JOIN CRFCloneList cl ON cf.inquiryid = cl.EnquiryID
INNER  join Department d on d.DepartmentID =ci.DepartmentID
INNER join ReportFormat rf on rf.ReportFormatID = ci.ReportFormat
CROSS APPLY STRING_SPLIT(ci.StandardID, ',') AS ids
LEFT JOIN Standards s ON s.StandardID = TRY_CAST(ids.value AS INT)
INNER JOIN SampleDetails sd ON cl.sampleID = sd.ID
INNER JOIN TestResultDetails tr ON tr.sampleid = sd.id
WHERE ad.InquiryID  = '" + InquiryID + "'AND s.StandardName IS NOT NULL ORDER BY cf.WorkOrderNumber, sampleIDSeries";


            dt = GetDataUsingQuery(sQuery);
            return dt;
        }



