        public int UpdateVendorContact(DAL.CM obj)
        {

            string sQuery = @"UPDATE ContactVendor 
                      SET ContactMobile = @ContactMobile,
                          ContactEmail = @ContactEmail,
                          PrimaryContact = @PrimaryContact 
                      WHERE VendorContactID = @VendorContactID";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    _sCon.Open();
                    cmd.Parameters.AddWithValue("@ContactMobile", obj.ContactMobile);
                    cmd.Parameters.AddWithValue("@ContactEmail", obj.ContactEmail);
                    cmd.Parameters.AddWithValue("@PrimaryContact", obj.IsPrimaryContact); // <-- use IsPrimaryContact here
                    cmd.Parameters.AddWithValue("@VendorContactID", obj.ContactID);

                    modified = cmd.ExecuteNonQuery();

                }
            }
            return modified;
        }

