        public int AddPaymentRequisition(DAL.CM obj)
        {
            int modified = 0;
            try
            {



                // Start Reseed to avoid identity jump
                int prevIdentity = GetReseedIdentity("PaymentRequisitionmaster", "PaymentRequisitionID");
                ReseedIdentity("PaymentRequisitionMaster", prevIdentity);
                // End Reseed to avoid identity jump

                string sQuery = @"INSERT INTO PaymentRequisitionMaster 
                                   (RequisitionDate,
                                    RequisitionBy,
                                    DepartmentID,
                                    createddate,
                                    RequisitionNumber,
                                    RequisitionYear,
                                    RequisitionCount,
                                    RequisitionStatus,
                                    TotalAmount,
                                    RequisitionType,RequisitionSubType,Remarks, CurrencyID
                                    ) output INSERTED.PaymentRequisitionID values 
                                   (@RequisitionDate,
                                    @RequisitionBy,
                                    @DepartmentID,
                                    @createddate,
                                    @RequisitionNumber,
                                    @RequisitionYear,
                                    @RequisitionCount,
                                    @RequisitionStatus,
                                    @TotalAmount,
                                    @RequisitionType,@RequisitionSubType,@Remarks,@CurrencyID)";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@RequisitionDate", obj.RequisitionDate);
                        cmd.Parameters.AddWithValue("@RequisitionBy", obj.RequisitionBy);
                        cmd.Parameters.AddWithValue("@DepartmentID", obj.departmentID);
                        cmd.Parameters.AddWithValue("@createddate", DateTime.Now);
                        cmd.Parameters.AddWithValue("@RequisitionNumber", obj.RequisitionNumber);
                        cmd.Parameters.AddWithValue("@RequisitionYear", obj.RequisitionYear);
                        cmd.Parameters.AddWithValue("@RequisitionCount", obj.RequisitionCount);
                        cmd.Parameters.AddWithValue("@RequisitionStatus", obj.RequisitionStatus);
                        cmd.Parameters.AddWithValue("@TotalAmount", obj.TotalAmount);
                        cmd.Parameters.AddWithValue("@RequisitionType", obj.RequisitionType);
                        cmd.Parameters.AddWithValue("@RequisitionSubType", obj.RequisitionSubType);
                        cmd.Parameters.AddWithValue("@Remarks", obj.Remarks);
                        cmd.Parameters.AddWithValue("@CurrencyID", obj.CurrencyID);
                        _sCon.Open();
                        modified = (int)cmd.ExecuteScalar();


                    }
                }
            }
            catch (Exception ex) { }
            return modified;
        }

