        public DataTable GetPaymentRequisitionHistory(string PaymentRequisitionID, string PRStatus)
        {
            sQuery = @"select distinct EmployeeName,EmployeeDepartmentName,DesignationName, PRStatus,e.ID,DigiSign,ph.CreatedDate as ApprovedDate from PaymentRequisitionDetails pr
                    inner join PaymentRequisitionHistory ph on pr.PaymentRequisitionDetailsID = ph.PaymentRequisitionDetailsID
					inner join Employees e on e.ID = ph.employeeid
					inner join EmployeeDepartment ed on ed.EmployeeDepartmentID = e.DepartmentID
					inner join designation d on d.DesignationID=e.DesignationID
                    where pr.PaymentRequisitionID ='" + PaymentRequisitionID + "' and ph.PRStatus in(" + PRStatus + ") ";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
