        public DataTable getAllPRCount(string EmployeeID, string Period)
        {
            if (Period == "ALL")
            {
                sQuery = @"SELECT 
                            RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                            pr.PRID AS PRID,
                            e.EmployeeName,
                            d.EmployeeDepartmentName,
                            pr.RequestDate,
                            ps.Status,
                            pr.StoreType
                        FROM PurchaseRequisition pr
                        LEFT JOIN Employees e ON e.ID = pr.RequestBy
                        inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                        inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                        where pr.PRID in(
                        select distinct PRID from PRHistory ph
                        inner join PurchaseRequisitionDetails pd on ph.PurchaseRequisitionDetailsID = pd.PurchaseRequisitionID
                        where ph.employeeid=" + Convert.ToInt32(EmployeeID) + ")";
            }
            else
            {
                sQuery = @"SELECT
                            RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                            pr.PRID AS PRID,
                            e.EmployeeName,
                            d.EmployeeDepartmentName,
                            pr.RequestDate,
                            ps.Status,
                            pr.StoreType
                        FROM PurchaseRequisition pr
                        LEFT JOIN Employees e ON e.ID = pr.RequestBy
                        inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                        inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
						CROSS APPLY Get_Date_Range('" + Period + "') dr  WHERE FORMAT(pr.RequestDate, 'yyyy-MM-dd') BETWEEN dr.From_Date AND dr.To_Date " +
                     @" and pr.PRID in(
                        select distinct PRID from PRHistory ph
                        inner join PurchaseRequisitionDetails pd on ph.PurchaseRequisitionDetailsID = pd.PurchaseRequisitionID
                        where ph.employeeid=" + Convert.ToInt32(EmployeeID) + ")";
            }
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable getPRCount(string Department, string Period)
        {
            if (Period == "ALL")
            {
                sQuery = @"SELECT 
                            RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                            pr.PRID AS PRID,
                            e.EmployeeName,
                            d.EmployeeDepartmentName,
                            pr.RequestDate,
	                        ps.Status,
                            pr.StoreType
                        FROM PurchaseRequisition pr
                        LEFT JOIN Employees e ON e.ID = pr.RequestBy
                        inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                        inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                    AND pr.DepartmentID = '" + Department + "' and pr.CurrentTier=1";
            }
            else
            {
                sQuery = @"SELECT 
                            RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                            pr.PRID AS PRID,
                            e.EmployeeName,
                            d.EmployeeDepartmentName,
                            pr.RequestDate,
	                        ps.Status,
                            pr.StoreType
                        FROM PurchaseRequisition pr
                        LEFT JOIN Employees e ON e.ID = pr.RequestBy
                        inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                        inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID                    
					 CROSS APPLY Get_Date_Range('" + Period + "') dr " +
                  @" WHERE FORMAT(pr.RequestDate, 'yyyy-MM-dd') BETWEEN dr.From_Date AND dr.To_Date AND pr.DepartmentID = '" + Department + "' and pr.CurrentTier=1";
            }

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable getPRCount(string Role, int CurrentTier, string Period)
        {
            if (Period == "ALL")
            {
                sQuery = @"
                            SELECT 
                            RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                            pr.PRID AS PRID,
                            e.EmployeeName,
                            d.EmployeeDepartmentName,
                            pr.RequestDate,
	                        ps.Status,
                            pr.StoreType
                        FROM PurchaseRequisition pr
                        LEFT JOIN Employees e ON e.ID = pr.RequestBy
                        inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                        inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                    and pr.CurrentTier=" + CurrentTier + " and CurrentApproverRole='" + Role + "'";
            }
            else
            {
                sQuery = @"SELECT 
                            RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR,
                            pr.PRID AS PRID,
                            e.EmployeeName,
                            d.EmployeeDepartmentName,
                            pr.RequestDate,
                            ps.Status,
                            pr.StoreType
                        FROM PurchaseRequisition pr
                        LEFT JOIN Employees e ON e.ID = pr.RequestBy
                        inner join PurchaseRequisitionStatus ps on ps.StatusID = pr.StatusID
                        inner JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
	                    CROSS APPLY Get_Date_Range('" + Period + "') dr " +
                   @"  WHERE FORMAT(pr.RequestDate, 'yyyy-MM-dd') BETWEEN dr.From_Date AND dr.To_Date
                    and pr.CurrentTier=" + CurrentTier + " and CurrentApproverRole='" + Role + "'";
            }
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
