        public int AddAdditionalRecordDetails(DAL.CM obj, string excelFilePath, string pdfFilePath)
        {
            int modified = 0;
            try
            {



                string sQuery = @"
            INSERT INTO AdditionalRecordDetails 
            (Reportid, SampleId, DepartmentID,Analysisstartingdate, AnalysisCompletionDate, 
             Brand, CertificateNo, CalibrationDate, ToolName, CalibrationLocation, 
             NoSeries, CalibrationMethod, Model, Type, Reference, Capacity, 
             Resolution, OwnerName, Address, HumidityBegining, HumidityEnd, 
             RoomTemperatureBegining, RoomTemperatureEnd, Standardsused, Uncertainty, 
             TracedtoSI, CalibratedBy, Checkedby, ExcelFilePath, WordFilePath,ReceiptDate)
            VALUES 
            (@Reportid, @SampleId,@DepartmentID, @Analysisstartingdate, @AnalysisCompletionDate, 
             @Brand, @CertificateNo, @CalibrationDate, @ToolName, @CalibrationLocation, 
             @NoSeries, @CalibrationMethod, @Model, @Type, @Reference, @Capacity, 
             @Resolution, @OwnerName, @Address, @HumidityBegining, @HumidityEnd, 
             @RoomTemperatureBegining, @RoomTemperatureEnd, @Standardsused, @Uncertainty, 
             @TracedtoSI, @CalibratedBy, @Checkedby, @ExcelFilePath, @WordFilePath,@ReceiptDate)";

                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        cmd.Parameters.AddWithValue("@Reportid", obj.ReportID);
                        cmd.Parameters.AddWithValue("@SampleId", obj.sampleId);
                        cmd.Parameters.AddWithValue("@Analysisstartingdate", (object)obj.CalibrationDate ?? DBNull.Value);
                        cmd.Parameters.AddWithValue("@AnalysisCompletionDate", (object)obj.CalibrationDate ?? DBNull.Value);
                        cmd.Parameters.AddWithValue("@Brand", obj.Brand ?? "");
                        cmd.Parameters.AddWithValue("@DepartmentID", 4012);
                        cmd.Parameters.AddWithValue("@CertificateNo", obj.CertificateNo ?? "");
                        cmd.Parameters.AddWithValue("@CalibrationDate", (object)obj.CalibrationDate ?? DBNull.Value);
                        cmd.Parameters.AddWithValue("@ReceiptDate", (object)obj.ReceiptDate ?? DBNull.Value);

                        cmd.Parameters.AddWithValue("@ToolName", obj.ToolName ?? "");
                        cmd.Parameters.AddWithValue("@CalibrationLocation", obj.CalibrationLocation ?? "");
                        cmd.Parameters.AddWithValue("@NoSeries", obj.NoSeries ?? "");
                        cmd.Parameters.AddWithValue("@CalibrationMethod", obj.CalibrationMethod ?? "");
                        cmd.Parameters.AddWithValue("@Model", obj.Model ?? "");
                        cmd.Parameters.AddWithValue("@Type", obj.Type ?? "");
                        cmd.Parameters.AddWithValue("@Reference", obj.Reference ?? "");
                        cmd.Parameters.AddWithValue("@Capacity", obj.Capacity ?? "");
                        cmd.Parameters.AddWithValue("@Resolution", obj.Resolution ?? "");
                        cmd.Parameters.AddWithValue("@OwnerName", obj.OwnerName ?? "");
                        cmd.Parameters.AddWithValue("@Address", obj.Address ?? "");
                        cmd.Parameters.AddWithValue("@HumidityBegining", obj.HumidityBegining ?? "");
                        cmd.Parameters.AddWithValue("@HumidityEnd", obj.HumidityEnd ?? "");
                        cmd.Parameters.AddWithValue("@RoomTemperatureBegining", obj.RoomTemperatureBegining ?? "");
                        cmd.Parameters.AddWithValue("@RoomTemperatureEnd", obj.RoomTemperatureEnd ?? "");
                        cmd.Parameters.AddWithValue("@Standardsused", obj.Standardsused ?? "");
                        cmd.Parameters.AddWithValue("@Uncertainty", obj.Uncertainty ?? "");
                        cmd.Parameters.AddWithValue("@TracedtoSI", obj.TracedtoSI ?? "");
                        cmd.Parameters.AddWithValue("@CalibratedBy", obj.CalibratedBy ?? "");
                        cmd.Parameters.AddWithValue("@Checkedby", obj.Checkedby ?? "");
                        cmd.Parameters.AddWithValue("@ExcelFilePath", excelFilePath ?? "");
                        cmd.Parameters.AddWithValue("@WordFilePath", pdfFilePath ?? "");


                        _sCon.Open();
                        cmd.ExecuteNonQuery();

                        modified++;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error saving additional record details: " + ex.Message);


            }
            return modified;
        }

