        public bool DeleteSampleImage(int id)
        {
            using (SqlConnection conn = new SqlConnection(cs))
            {
                string query = "DELETE FROM SampleImages WHERE ID = @ID";
                SqlCommand cmd = new SqlCommand(query, conn);
                cmd.Parameters.AddWithValue("@ID", id);
                conn.Open();
                int result = cmd.ExecuteNonQuery();
                return result > 0;
            }
        }
        public void UpdateCustomerInquiryTestDetails(DAL.CustomerInquiry obj)
        {
            string query = @"UPDATE customerinquiry
                            SET 
                                TAFSampleName = @SampleName,
                                TAFtestitems   = @testitems,
                                TAFtestmethods = @testmethods
                            WHERE inquiryid = @inquiryid";
            using (SqlConnection con = new SqlConnection(cs))
            using (SqlCommand cmd = new SqlCommand(query, con))
            {
                try
                {
                    cmd.Parameters.Add("@SampleName", SqlDbType.NVarChar).Value = obj.SampleName;
                    cmd.Parameters.Add("@testitems", SqlDbType.NVarChar).Value = obj.TestItems;
                    cmd.Parameters.Add("@testmethods", SqlDbType.NVarChar).Value = obj.TestMethods;
                    cmd.Parameters.Add("@inquiryid", SqlDbType.Int).Value = obj.InquiryID;

                    con.Open();
                    cmd.ExecuteNonQuery();
                }
                catch (Exception ex)
                {
                    string s = ex.Message;
                }
            }

        }
