        public DataTable GetAccountMapping(string quotationdetailID, string DepartmentID, string ItemType)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT * from quotationmaster qm
                                inner join CustomerInquiry c on c.InquiryID= qm.EnquiryID
                                inner join quotationdetails qd on qm.QuotationMasterID = qd.QuotationMasterID
                                inner join UOM um ON um.UOMId = qd.UOMId									
								inner join AccountMapping a on a.DepartmentID = c.DepartmentID 
								inner join RevenueMapping r on r.id=a.revenuemappingID and r.parameter = qd.ItemType and a.RevenueMappingID = r.ID
                                inner join ChartOfAccountsDetail cd on cd.AccountCode = a.AccountCode
                                where qd.quotationdetailID='" + quotationdetailID + "' and c.DepartmentID='" + DepartmentID + "' and qd.ItemType='" + ItemType + "'";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public void AuditLog(
                                    int userId,
                                    string userName,
                                    string actionType,
                                    string remarks)
        {
            string cs = ConfigurationManager.ConnectionStrings["CM"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand(@"
            INSERT INTO AuditLog
            (UserId, UserName, ActionType, IPAddress, MachineName, ApplicationName, Remarks)
            VALUES
            (@UserId, @UserName, @ActionType, @IPAddress, @MachineName, @AppName, @Remarks)", con);

                cmd.Parameters.AddWithValue("@UserId", userId);
                cmd.Parameters.AddWithValue("@UserName", userName);
                cmd.Parameters.AddWithValue("@ActionType", actionType);
                cmd.Parameters.AddWithValue("@IPAddress", HttpContext.Current.Request.UserHostAddress);
                cmd.Parameters.AddWithValue("@MachineName", Environment.MachineName);
                cmd.Parameters.AddWithValue("@AppName", "RNI ERP");
                cmd.Parameters.AddWithValue("@Remarks", remarks ?? "");

                con.Open();
                cmd.ExecuteNonQuery();
            }
        }
