        public DataTable Getgeneratetestallocation_Transport(string CloneCRFSampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"select s.sampleIDSeries,cs.TestParameter as TestsRequested,cs.SampleName,cs.BatchNo,cs.DescriptionOfTest,
                         cs.Specification,cs.TestMethod,cs.TestParameter as ReportName,cs.AllocatedAt,cs.Remarks,
							s.sampleID as sampleUID, e.EmployeeName,e1.EmployeeName  as Supervisor
							from  sampledetails s 
                         inner join crfclonelist c on c.sampleid = s.id 
							inner join crfsampledetails cs on cs.CloneCRFSampleID = c.CloneCRFSampleID
                         inner join employees e on e.id = cs.employeeid 
							inner join Employees e1 on e1.EmployeeID = cs.SupervisorID	
						    where c.CloneCRFSampleID='" + CloneCRFSampleID + "' and s.OrganizationID =1";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetCategoryTypeStdTest(string sampleId)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT ci.InquiryId, s.orig_part,
                                    TRY_CAST(PARSENAME(REPLACE(s.norm_part, ':', '.'), 3) AS INT) AS CategoryId,
                                    TRY_CAST(NULLIF(PARSENAME(REPLACE(s.norm_part, ':', '.'), 2), 'NULL') AS INT) AS TypeId,
                                    TRY_CAST(PARSENAME(REPLACE(s.norm_part, ':', '.'), 1) AS INT) AS StandardId,
                                    tc.TestCategory,st.StandardName,tm.Type
                                FROM CustomerInquiry ci
                                CROSS APPLY STRING_SPLIT(ci.CategoryTypeStdTest, ',') AS ssplit
                                CROSS APPLY (SELECT LTRIM(RTRIM(ssplit.value)) AS orig_part, REPLACE(LTRIM(RTRIM(ssplit.value)), '::', ':NULL:') AS norm_part) AS s
                                LEFT JOIN TestCategory tc ON tc.TestCategoryId = TRY_CAST(PARSENAME(REPLACE(s.norm_part, ':', '.'), 3) AS INT)
                                LEFT JOIN Standards st ON st.StandardID = TRY_CAST(PARSENAME(REPLACE(s.norm_part, ':', '.'), 1) AS INT)
                                LEFT JOIN TypeMechanical tm ON tm.TypeID = TRY_CAST(PARSENAME(REPLACE(s.norm_part, ':', '.'), 2) AS INT)
                                INNER JOIN CRFCloneList ccl ON ccl.EnquiryID = ci.InquiryId
                                where ccl.sampleID = '" + sampleId + "'  ";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }

        /*17-12-2025*/
        public DataTable EA_DetailsGet(int sampleID)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT DISTINCT TestReportNo, cd.CompanyName AS [Applicant],  (Title + ' ' + FirstName + ' ' + LastName) AS Attention, 
                            ctd.Email, CONCAT_WS(', ', NULLIF(Addressline1, ''), NULLIF(Addressline2, ''), NULLIF(AddressLine3, ''), 
                            NULLIF(city, ''), NULLIF(pincode, ''), NULLIF(country, '')) AS Address, samplename AS [SampleDescription], 
                            SampleCondition AS [SampleCondition],  CreatedDate AS [Date], AnalysisStartingDate AS [TestSample], 
                            AnalysisCompletionDate AS [TestPeriod], IssueDate, ColorName_Code, MaterialName_Code,
                            ad.BuyerCustomerName AS [Buyer'sName], ad.AgeGroup, ad.PONo, ad.Suppliername, 
                            BatchNo, ad.CountryOrigin AS [CountryofOrigin], ad.CountryDestination AS [CountryOfDestination], 
                            InquiryDetail AS [TestPackage], BrandProduct, ProductGroupName, cf.Remarks AS [Remark], ad.ProductType, 
                            FactoryName, FactoryAddress, ad.PersonID, DateOfExp, ArticleNumber, MaterialType, ItemStyleNo, pg.ProductGroupName, 
                            ad.LotNumber, ci.Remarks, sd.sampleIDSeries,cf.SizeOfSample as ProductQuantity,
                            t.FinalTestResult, ad.ProductName, ad.ProductSerialNo, ad.ProductSpecification, ad.Color, 
                            cf.WorkorderNumber as WorkorderNumber, ci.RequestNo,
							trl.TestCategory,trl.Humidity,trl.Temperature,trl.ProductBrand,trl.Ranking,trl.SampleCode,trl.TestMethod,trl.StandardName
                        FROM testresultdetails t
                        INNER JOIN crfclonelist c ON c.sampleid = t.SampleId
                        INNER JOIN customerinquiry ci ON ci.inquiryid = c.enquiryid
                        LEFT JOIN ProductGroup pg ON pg.ProductGroupID = ci.productCategoryID
                        LEFT JOIN CompanyDetails cd ON cd.customermasterid = ci.customermasterid
                        INNER JOIN LocationDetails lo ON lo.customermasterid = ci.customermasterid 
                        INNER JOIN crfsampledetails cf ON cf.clonecrfsampleid = c.clonecrfsampleid
                        INNER JOIN AdditionalDetails ad ON ad.InquiryID = ci.InquiryId
                        INNER JOIN ContactPersonDetails cpd ON ad.PersonID = cpd.PersonId
                        LEFT JOIN ContactDetails ctd ON ctd.PersonId = cpd.PersonId
                        INNER JOIN SampleDetails sd ON sd.ID = t.SampleId 
						inner join TestResultsLED trl ON trl.SampleID = t.SampleId
                        WHERE t.SampleId = '" + sampleId + "' ";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
