            ) 
            OUTPUT INSERTED.AdditionalDetailsID 
            VALUES (
                @InquiryID,
                @RequestId,
                @CustomerMasterID,
                @PersonID,
                @BuyerCustomerName,
                @BuyerAddressLine1,
                @BuyerAddressLine2,
                @BuyerPincode,
                @BuyerCountry,
                @ServiceRequired,
                @SampleReturn,
                @ReportRecipient,
                @InvoiceRecipient,
