        public int UpdateTestResultDetails_Transport(DAL.CM obj)
        {
            string sQuery = @"UPDATE TestResultDetails 
                      SET IssueDate = @IssueDate,
                          ULRNo = @ULRNo,
                          AnalysisStartingDate = @AnalysisStartingDate,
                          AnalysisCompletionDate = @AnalysisCompletionDate,
                          NameOfProduct = @NameOfProduct,
                          DateOfMfg = NULL,
                          DateOfExp = NULL,
                          SampleQuality = @SampleQuality,
                          SampleCondition = @SampleCondition,
                          TestRequired = @TestRequired,
                          Sampling = @Sampling,
                          SamplingMethod = @SamplingMethod,
                          TestReportNo = @TestReportNo,
                          CustomerReference = @CustomerReference,
                          Remarks = @Remarks,
                          FinalTestResult = @FinalTestResult
                      WHERE SampleID = @SampleID";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    _sCon.Open();
                    // Parameters handle all conversions automatically
                    cmd.Parameters.AddWithValue("@IssueDate", (object)obj.issueDate ?? DBNull.Value);
                    cmd.Parameters.AddWithValue("@AnalysisStartingDate", (object)obj.analysisStartingDate ?? DBNull.Value);
                    cmd.Parameters.AddWithValue("@AnalysisCompletionDate", (object)obj._analysisCompletionDate ?? DBNull.Value);
                    cmd.Parameters.AddWithValue("@ULRNo", obj.ulrNo ?? "");
                    cmd.Parameters.AddWithValue("@NameOfProduct", obj.nameOfProduct ?? "");
                    cmd.Parameters.AddWithValue("@SampleQuality", obj.sampleQuality ?? "");
                    cmd.Parameters.AddWithValue("@SampleCondition", obj.samplingCondition ?? "");
                    cmd.Parameters.AddWithValue("@TestRequired", obj.testRequired ?? "");
                    cmd.Parameters.AddWithValue("@Sampling", obj.sampling ?? "");
                    cmd.Parameters.AddWithValue("@SamplingMethod", obj.SamplingMethod ?? "");
                    cmd.Parameters.AddWithValue("@TestReportNo", obj.TestReportNo ?? "");
                    cmd.Parameters.AddWithValue("@CustomerReference", obj.CustomerReference ?? "");
                    cmd.Parameters.AddWithValue("@Remarks", obj.remarks ?? "");
                    cmd.Parameters.AddWithValue("@FinalTestResult", obj.FinalTestResult ?? "");
                    cmd.Parameters.AddWithValue("@SampleID", obj.sampleId);

                    modified = cmd.ExecuteNonQuery();
                }
            }
            return modified;
        }
