        public DataTable GetTestReportDetails_Transport(string SampleId)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT DISTINCT 
                                sd.ID, 
                                sd.SampleId, 
                                sd.sampleidseries, 
                                csd.InquiryID, 
                                r.ReportName, 
                                r.codefilename, 
                                r.ReportID,
                                st.StatusName, 
                                cl.CloneCRFSampleID, 
                                CONCAT('TestReport-SID=', sd.ID, '_RPID=', r.ReportID, '.pdf') as ReportURL,
                                tr.PDFPath,
                                tr.FileName,
                                tr.createdDate
                            FROM SampleDetails sd
                            INNER JOIN CRFCloneList cl ON cl.sampleID = sd.ID
                            INNER JOIN CRFSampleDetails csd ON csd.CloneCRFSampleID = cl.CloneCRFSampleID
                            INNER JOIN ReportList r ON r.ReportID = csd.ReportID
                            INNER JOIN InquiryStatus st ON st.InquiryStatusId = csd.samplestatus
                            LEFT JOIN TestResultsPTQualis tr ON tr.SampleID = sd.ID AND tr.ReportID = r.ReportID
                            WHERE sd.ID = " + SampleId;
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable getdetails_Transport(int sampleID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT t.TestReportNo, cd.CompanyName AS [Applicant],(Title + ' ' + FirstName + ' ' + LastName) AS Attention,
                                FORMAT(sd.ReceivedDate, 'MMMM dd yyyy') AS SampleReceivedDate,
                                STRING_AGG(cf.TestMethod, ' , ') AS TestMethod,
                                ctd.Email,
                                CONCAT_WS(', ', NULLIF(Addressline1, ''), NULLIF(Addressline2, ''), NULLIF(AddressLine3, ''), 
                                    NULLIF(city, ''), NULLIF(pincode, ''), NULLIF(country, '')) AS Address,
                                    samplename AS [SampleDescription],
                                    SampleCondition AS [SampleCondition],
                                    CreatedDate AS [Date],
                                    AnalysisStartingDate AS [TestSample],
                                    AnalysisCompletionDate AS [TestPeriod],
                                    ad.BuyerCustomerName AS [Buyer'sName],
                                    IssueDate,BatchNo,ad.CountryOrigin AS [CountryofOrigin],
                                        ad.CountryDestination AS [CountryOfDestination],
                                        InquiryDetail AS [TestPackage],
                                        BrandProduct,
                                        CONCAT_WS(' - ', pg.ProductGroupName,psg.SubGroupName) AS TestCategory,
                                        cf.Remarks AS [Remark],
                                        ad.ProductType,
                                        FactoryName,
                                        FactoryAddress,
                                        ad.PersonID,
                                        DateOfExp,
                                        ArticleNumber,
                                    MaterialType,
                                    ItemStyleNo,                                  
                                    ad.LotNumber,
                                    ci.Remarks,
                                    sd.sampleIDSeries,
                                    cf.SizeOfSample AS ProductQuantity,
                                    t.FinalTestResult,
                                    ad.ProductName,
                                    ad.ProductSerialNo,
                                    ad.ProductSpecification,
                                    ad.Color,
                                    cf.WorkorderNumber AS WorkorderNumber
                            FROM testresultdetails t
                                INNER JOIN crfclonelist c ON c.sampleid = t.SampleId
                                INNER JOIN customerinquiry ci ON ci.inquiryid = c.enquiryid
                                LEFT JOIN ProductSubGroup psg ON psg.SubGroupID = ci.productCategoryID
								INNER join ProductGroup pg on pg.ProductGroupID = psg.ProductGroupID
                                LEFT JOIN CompanyDetails cd ON cd.customermasterid = ci.customermasterid
                                INNER JOIN LocationDetails lo ON lo.customermasterid = ci.customermasterid
                                INNER JOIN crfsampledetails cf ON cf.clonecrfsampleid = c.clonecrfsampleid
                                INNER JOIN AdditionalDetails ad ON ad.InquiryID = ci.InquiryId
                                INNER JOIN ContactPersonDetails cpd ON ad.PersonID = cpd.PersonId
                                LEFT JOIN ContactDetails ctd ON ctd.PersonId = cpd.PersonId
                                INNER JOIN SampleDetails sd ON sd.ID = t.SampleId 
                                WHERE t.SampleId = '" + sampleID + "'  GROUP BY t.TestReportNo, cd.CompanyName, Title, FirstName, LastName," +
                                            " sd.ReceivedDate, ctd.Email, Addressline1, Addressline2, AddressLine3, city, pincode, country," +
                                            "samplename, SampleCondition, CreatedDate, AnalysisStartingDate, AnalysisCompletionDate," +
                                            "ad.BuyerCustomerName, BatchNo, ad.CountryOrigin, ad.CountryDestination, InquiryDetail," +
                                            "BrandProduct, ProductGroupName, cf.Remarks, ad.ProductType, FactoryName, FactoryAddress," +
                                            "ad.PersonID, DateOfExp, ArticleNumber, MaterialType, ItemStyleNo, pg.ProductGroupName," +
                                            "ad.LotNumber, ci.Remarks, sd.sampleIDSeries, cf.SizeOfSample, t.FinalTestResult,psg.SubGroupName," +
                                            "ad.ProductName, ad.ProductSerialNo, ad.ProductSpecification, ad.Color, cf.WorkorderNumber,IssueDate";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
