        private int InsertReceiptHeader(
            SqlConnection con,
            SqlTransaction tran,
            int customerId,
            DateTime receiptDate,
            decimal totalAmount)
        {
            string sql = @"
                INSERT INTO ReceiptHeader
                (ReceiptNo, ReceiptDate, CustomerID, TotalReceivedAmount, CreatedOn)
                VALUES
                ('RC-' + RIGHT('00000' + CAST(NEXT VALUE FOR ReceiptSeq AS VARCHAR), 5),
                 @ReceiptDate, @CustomerID, @Amount, GETDATE());

                SELECT SCOPE_IDENTITY();";

            using (SqlCommand cmd = new SqlCommand(sql, con, tran))
            {
                cmd.Parameters.AddWithValue("@ReceiptDate", receiptDate);
                cmd.Parameters.AddWithValue("@CustomerID", customerId);
                cmd.Parameters.AddWithValue("@Amount", totalAmount);

                return Convert.ToInt32(cmd.ExecuteScalar());
            }
        }

        private void InsertReceiptDetail(
                    SqlConnection con,
                    SqlTransaction tran,
                    int receiptId,
                    int invoiceId,
                    decimal paidAmount,
                    decimal balanceAfter)
        {
            string sql = @"
                        INSERT INTO ReceiptDetail
                        (ReceiptID, InvoiceID, PaidAmount, BalanceAfterPayment)
                        VALUES
                        (@ReceiptID, @InvoiceID, @PaidAmount, @BalanceAfter);";

            using (SqlCommand cmd = new SqlCommand(sql, con, tran))
            {
                cmd.Parameters.AddWithValue("@ReceiptID", receiptId);
                cmd.Parameters.AddWithValue("@InvoiceID", invoiceId);
                cmd.Parameters.AddWithValue("@PaidAmount", paidAmount);
                cmd.Parameters.AddWithValue("@BalanceAfter", balanceAfter);

                cmd.ExecuteNonQuery();
            }
        }


        private void UpdateInvoice(
                    SqlConnection con,
                    SqlTransaction tran,
                    int invoiceId,
                    decimal paidAmount)
        {
            string sql = @"
                        UPDATE Invoice
                        SET 
                            PaidAmount = ISNULL(PaidAmount,0) + @PaidAmount,
                            BalanceAmount = GrandTotal - (ISNULL(PaidAmount,0) + @PaidAmount),
                            Status = CASE 
                                        WHEN GrandTotal = (ISNULL(PaidAmount,0) + @PaidAmount)
                                        THEN 'Paid'
                                        ELSE 'Partially Paid'
                                     END
                        WHERE InvoiceID = @InvoiceID;";

            using (SqlCommand cmd = new SqlCommand(sql, con, tran))
            {
                cmd.Parameters.AddWithValue("@PaidAmount", paidAmount);
                cmd.Parameters.AddWithValue("@InvoiceID", invoiceId);

                cmd.ExecuteNonQuery();
            }
        }

