        public DataTable GetPOPR(string PurchaseOrderID)
        {
            return DbHelper.ExecuteQuery(
               @"select STRING_AGG(PR, ', ') as PR from(
                    select RIGHT('0000' + CAST(PRNumber AS VARCHAR(4)), 4) + '/' + RIGHT('0' + CAST(MONTH(RequestDate) AS VARCHAR(2)), 2) + '/' + cast(year(RequestDate) as varchar) + '/' + deptcode AS PR
                    from purchaserequisitiondetails pd
                    inner join purchaserequisition pr on pr.PRID = pd.PRID
                    LEFT JOIN EmployeeDepartment d ON d.EmployeeDepartmentID = pr.DepartmentID
                    where pd.purchaseorderID='" + PurchaseOrderID + "')x");
        }
        public DataTable GetPIDetails(int PIInvoiceID)//Purchase InvoiceID
        {
            DataTable dt = new DataTable();
            string sQuery = @"select tm.InwardID,
                                tm.ReceivedDate,
                                tm.GRNNumber,
                                i.ItemCode,
                                i.ItemDescription,
                                td.ReceivedQty as Quantity,
                                u.UOMName,pd.rate,pd.discount,
                                (pd.rate * td.ReceivedQty)- (pd.rate * td.ReceivedQty * pd.discount/100) as amount
								from TransactionMaster tm
								inner join Transactiondetails td on td.InwardID = tm.InwardID
								inner join PurchaseOrderDetails pd on td.PODetailsID=pd.PODetailsID
								inner join items i on i.ItemID = pd.ItemID
                                inner join UOM u on u.UOMId = i.UOMID
								WHERE tm.InwardID IN (
								SELECT TRY_CAST(value AS INT)
								FROM InvoiceAP
								CROSS APPLY STRING_SPLIT(GRNID, ',')
								WHERE InvoiceID = " + PIInvoiceID + ") order by tm.ReceivedDate asc,tm.GRNNumber asc";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
