        public DataTable getSalesAchievementYearly(string year)
        {
            string query = @"SELECT DepartmentName,sum(grandTotal) AS TotalSales,
                                200000000 AS TotalTarget, 
                                (SUM(grandTotal) * 100.0 / 200000000) AS AchievementPercent
                                FROM QuotationMaster q
                                inner join CustomerInquiry c on c.InquiryId = q.EnquiryId
                                inner join Department d on d.DepartmentID = c.DepartmentID
                                WHERE YEAR(QuotationDate) = '" + year + "' and QuotationStatusID>1" +
                                @" GROUP BY DepartmentName
                                ORDER BY DepartmentName";
            return GetDataUsingQuery(query);
        }
        public DataTable getSalesAchievementMonthly(string year)
        {
            string query = @"SELECT DepartmentName, MONTH(QuotationDate) AS SaleMonth,
                                sum(grandTotal) AS TotalSales,
                                200000000 AS TotalTarget, 
                                (SUM(grandTotal) * 100.0 / 200000000) AS AchievementPercent
                                FROM QuotationMaster q
                                inner join CustomerInquiry c on c.InquiryId = q.EnquiryId
                                inner join Department d on d.DepartmentID = c.DepartmentID
                                WHERE YEAR(QuotationDate) = '" + year + "' and QuotationStatusID>1" +
                                @" GROUP BY DepartmentName,MONTH(QuotationDate)
                                ORDER BY DepartmentName,SaleMonth";
            return GetDataUsingQuery(query);
        }
        public int UpdateTestResults_ToysAndBabyWear(DAL.CM obj)
        {
            int modified = 0;


            string sQuery = @"Update TestResults set EquipmentName = @EquipmentName, TestResult= @TestResult, UnitOfMeasurement = @UnitOfMeasurement, 
                                Specification = @Specification,AnalysisStartingDate = @AnalysisStartingDate,AnalysisCompletionDate = @AnalysisCompletionDate, 
                                AdditionalColourCodesId=@AdditionalColourCodesId, Conclusion = @Conclusion, Conclusion_BH = @Conclusion_BH 
                                where CRFSampleID = @CRFSampleID and AdditionalColourCodesId = @AdditionalColourCodesId";
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@EquipmentName", obj.equipmentSelect);
                    cmd.Parameters.AddWithValue("@TestResult", obj.testResult);

                    if (obj.testResult == "N.D")
                    {
                        cmd.Parameters.AddWithValue("@Conclusion", "PASS");
                        cmd.Parameters.AddWithValue("@Conclusion_BH", "LULUS");
                    }
                    else
                    {
                        cmd.Parameters.AddWithValue("@Conclusion", obj.Conclusion);
                        if (obj.Conclusion == "Fail")
                        {
                            cmd.Parameters.AddWithValue("@Conclusion_BH", "TIDAK LULUS");
                        }
                        else
                        {
                            cmd.Parameters.AddWithValue("@Conclusion_BH", "LULUS");
                        }

                    }

                    cmd.Parameters.AddWithValue("@UnitOfMeasurement", obj.unit);
                    cmd.Parameters.AddWithValue("@Specification", obj.specification);
                    cmd.Parameters.AddWithValue("@AnalysisStartingDate", obj.analysisStartingDate);
                    cmd.Parameters.AddWithValue("@AnalysisCompletionDate", obj.analysisCompleteDate);
                    cmd.Parameters.AddWithValue("@CRFSampleId", obj.CRFSampleId);
                    cmd.Parameters.AddWithValue("@AdditionalColourCodesId", obj.AdditionalColourCodesId);

                    _sCon.Open();
                    cmd.ExecuteScalar();

                    //Start Reseed to avoid identity jump
                    int prevIdentity = GetReseedIdentity("ScriptSample", "ID");
                    ReseedIdentity("ScriptSample", prevIdentity);
                    //End Reseed to avoid identity jump

                    sQuery = "insert into ScriptSample (ScriptSample) values(@ScriptSample)";
