        public DataTable GetCRFListForTestResults_ToysAndBabyWear(int sampleID, int EmployeeID, int AdditionalColourCodeId)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT cd.CRFSampleID, SampleName, BatchNo, 
                                    CASE 
                                       WHEN tp.Protocol IS NOT NULL AND tp.Protocol != '' THEN tp.Protocol
                                       WHEN tsp.Protocol IS NOT NULL AND tsp.Protocol != '' THEN tsp.Protocol
                                       WHEN tssp.Protocol IS NOT NULL AND tssp.Protocol != '' THEN tssp.Protocol
                                       ELSE NULL
                                    END as TestMethod,
                                 cd.TestParameter, tsp.TestSubParameterID, tsp.TestSubParameter, 
                                 tssp.TestSubSubParameter, TestResult, cd.RequirementID, cd.UnitOfMeasurement, ISNULL(t.Specification, cd.Specification) AS Specification,
                                 StatusName, AnalysisStartingDate, AnalysisCompletionDate, t.DestroyDate, calculations, cd.SampleStatus, ce.EpID, 
                                 ce.Equipment, t.EquipmentName, ccs.ColourCodeId, ccs.AdditionalColourCodeId, ccs.ColourCodeId, 
                                 t.AdditionalColourCodesId, t.TestResultID, Conclusion,Conclusion_BH
                                FROM crfsampledetails cd 
                                INNER JOIN crfclonelist ci ON cd.clonecrfsampleid = ci.clonecrfsampleid
                                INNER JOIN InquiryStatus s ON s.inquirystatusid = cd.samplestatus
                                LEFT JOIN testresults t ON t.CRFSampleID = cd.CRFSampleId AND t.AdditionalColourCodesId = @AdditionalColourCodeId
                                INNER JOIN sampledetails sd ON ci.sampleid = sd.id 
                                INNER JOIN TestParameter tp ON tp.TestParameterID = cd.TestParameterID
                                LEFT JOIN TestSubParameter tsp ON tsp.TestSubParameterID = cd.TestSubParameterID
                                LEFT JOIN TestSubSubParameter tssp ON tssp.TestSubSubParameterID = cd.TestSubSubParameterID
                                LEFT JOIN Calibration_Equipment ce ON ce.EpID = tp.EpID
                                LEFT JOIN ColourCodeSave ccs ON ccs.InquiryId = cd.InquiryId AND ccs.AdditionalColourCodeId = @AdditionalColourCodeId
                                WHERE sd.sampleid = @SampleID AND cd.EmployeeID = @EmployeeID AND cd.OrganizationID = @OrganizationID
                                ORDER BY cd.CRFSampleId ASC";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@AdditionalColourCodeId", AdditionalColourCodeId);
                    cmd.Parameters.AddWithValue("@SampleID", sampleID);
                    cmd.Parameters.AddWithValue("@EmployeeID", EmployeeID);
                    cmd.Parameters.AddWithValue("@OrganizationID", HttpContext.Current.Session["OrganizationID"].ToString());

                    dt = GetDataUsingQuery1(cmd);
                }
            }
            return dt;

        }
        public int CheckAllColourCodesMatch(int sampleId)
        {
            int result = 0;

            string query = @"
            SELECT 
                CASE 
                    WHEN NOT EXISTS (
                        SELECT 1 
                        FROM ColourCodeSave ccs
                        WHERE ccs.sampleID = @SampleId
                        AND NOT EXISTS (
                            SELECT 1 
                            FROM TESTRESULTS tr
                            WHERE tr.sampleID = @SampleId
                            AND tr.AdditionalColourCodesId = ccs.AdditionalColourCodeId
                        )
                    ) AND EXISTS (SELECT 1 FROM ColourCodeSave WHERE sampleID = @SampleId)
                    THEN 1 
                    ELSE 0 
                END AS AllMatch";

            try
            {
                using (SqlConnection connection = new SqlConnection(cs))
                {
                    using (SqlCommand command = new SqlCommand(query, connection))
                    {
                        command.Parameters.AddWithValue("@SampleId", sampleId);
                        connection.Open();
                        object queryResult = command.ExecuteScalar();
                        connection.Close();
                        if (queryResult != null && queryResult != DBNull.Value)
                        {
                            result = Convert.ToInt32(queryResult);
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                // Handle SQL errors
                throw new Exception($"Database error occurred: {ex.Message}", ex);
            }
            catch (Exception ex)
            {
                // Handle other errors
                throw new Exception($"Error occurred: {ex.Message}", ex);
            }

            return result;
        }
        public int AddTestResults_ToysAndBabyWear(DAL.CM obj)
        {
            int modified = 0;



            //Start Reseed to avoid identity jump
            int prevIdentity = GetReseedIdentity("TestResults", "TestResultID");
            ReseedIdentity("TestResults", prevIdentity);
            //End Reseed to avoid identity jump

            string sQuery = "Insert into TestResults (CRFSampleID," +
                "sampleID," +
                "TestResult," +
                "UnitOfMeasurement," +
                "Specification," +
                "AnalysisStartingDate," +
                "AnalysisCompletionDate," +
                "OrganizationID, EquipmentName, AdditionalColourCodesId,Conclusion,Conclusion_BH)" +
                "output INSERTED.TestResultId values " +
                "(@CRFSampleID," +
                "@sampleID," +
                "@TestResult," +
                "@UnitOfMeasurement," +
                "@Specification," +
                "@AnalysisStartingDate," +
                "@AnalysisCompletionDate," +
                "@OrganizationID, @EquipmentName, @AdditionalColourCodesId,@Conclusion,@Conclusion_BH)";
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@EquipmentName", obj.equipmentSelect);
                    cmd.Parameters.AddWithValue("@CRFSampleID", obj.CRFSampleId);
                    cmd.Parameters.AddWithValue("@sampleID", obj.sampleId);
                    cmd.Parameters.AddWithValue("@TestResult", obj.testResult);
                    cmd.Parameters.AddWithValue("@UnitOfMeasurement", obj.unit);
                    cmd.Parameters.AddWithValue("@Specification", obj.specification);
                    cmd.Parameters.AddWithValue("@AnalysisStartingDate", obj.analysisStartingDate);
                    cmd.Parameters.AddWithValue("@AnalysisCompletionDate", obj._analysisCompletionDate);
                    cmd.Parameters.AddWithValue("@OrganizationID", obj.OrganizationID);
                    cmd.Parameters.AddWithValue("@AdditionalColourCodesId", obj.AdditionalColourCodesId);

                    if (obj.testResult == "N.D")
                    {
                        cmd.Parameters.AddWithValue("@Conclusion", "PASS");
                        cmd.Parameters.AddWithValue("@Conclusion_BH", "LULUS");
                    }
                    else
                    {
                        cmd.Parameters.AddWithValue("@Conclusion", obj.Conclusion);
                        if (obj.Conclusion == "Fail")
                        {
                            cmd.Parameters.AddWithValue("@Conclusion_BH", "TIDAK LULUS");
                        }
                        else
                        {
                            cmd.Parameters.AddWithValue("@Conclusion_BH", "LULUS");
                        }
                    }

                    _sCon.Open();
                    modified = (int)cmd.ExecuteScalar();
                }

            }
            return modified;
        }
        public DataTable GetNextItemCode()
        {
            string query = @"SELECT 
                            RIGHT('000000' + 
                                  CAST(ISNULL(MAX(CAST(LTRIM(RTRIM(ItemCode)) AS INT)),0) + 1 AS VARCHAR),6)
                            AS NextItemCode
                            FROM Items
                            WHERE LTRIM(RTRIM(ItemCode)) NOT LIKE '%[^0-9]%'";
            return GetDataUsingQuery(query);
        }
        public bool ItemExists(int purchaseGroupId, int subGroupId, string itemName)
        {
            string query = @"SELECT COUNT(1) 
                     FROM Items 
                     WHERE PurchaseGroupID = @PurchaseGroupID
                     AND PurchaseSubGroupID = @PurchaseSubGroupID
                     AND ItemName = @ItemName
                     AND isActive = 1";

            using (SqlConnection con = new SqlConnection(cs))
            using (SqlCommand cmd = new SqlCommand(query, con))
            {
                cmd.Parameters.Add("@PurchaseGroupID", SqlDbType.Int).Value = purchaseGroupId;
                cmd.Parameters.Add("@PurchaseSubGroupID", SqlDbType.Int).Value = subGroupId;
                cmd.Parameters.Add("@ItemName", SqlDbType.NVarChar).Value = itemName.Trim();

                con.Open();
                int count = Convert.ToInt32(cmd.ExecuteScalar());
                return count > 0;
            }
        }
