        public DataTable GetSalesStatusByDepartment(string year)
        {
            sQuery = @"SELECT d.DepartmentID,
                            d.DepartmentName,

                            -- No Quotation
                            SUM(CASE 
                                    WHEN q.QuotationMasterID IS NULL THEN 1 
                                    ELSE 0 
                                END) AS NoQuotation,

                            -- Quotation Reached but no Invoice
                            SUM(CASE 
                                    WHEN q.QuotationMasterID IS NOT NULL 
                                         AND i.InvoiceID IS NULL THEN 1 
                                    ELSE 0 
                                END) AS QuotationReached,

                            -- Invoice Generated
                            SUM(CASE 
                                    WHEN i.InvoiceID IS NOT NULL THEN 1 
                                    ELSE 0 
                                END) AS InvoiceGenerated

                        FROM CustomerInquiry iq
                        INNER JOIN Department d ON iq.DepartmentID = d.DepartmentID
                        LEFT JOIN QuotationMaster q ON iq.InquiryID = q.EnquiryId
                        LEFT JOIN Invoices i ON q.QuotationMasterID = i.QuotationID
                        where year(iq.Created)='" + year + "'" +
                      @" GROUP BY d.DepartmentID,d.DepartmentName
                        ORDER BY d.DepartmentName";
            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetTopSalesReps(string year)
        {
            string sQuery = @"
                           SELECT TOP 5
                        q.UserId,EmployeeName,
                        COUNT(q.QuotationMasterID) AS TotalConfirmedQuotations,
                        SUM(q.GrandTotal) AS TotalSalesAmount
                            FROM QuotationMaster q
                            inner join Users u on u.UserID = q.UserId
                            inner join Employees e on e.id= u.employeeID
                            WHERE q.PONumber IS NOT NULL  and year(QuotationDate)='" + year + "'" +
                            @" GROUP BY q.UserId,EmployeeName
                            ORDER BY SUM(q.GrandTotal) DESC;";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetPendingRequests(string year)
        {
            string sQuery = @"
                           SELECT TOP 5
                        r.RequestNo,DepartmentName,CompanyName,
                        r.Created,
                        r.CustomerId
                    FROM CustomerInquiry r
                    inner join Department d on d.DepartmentID = r.DepartmentID
                    inner join CompanyDetails c on c.CustomerMasterId = r.CustomerMasterId
                    WHERE NOT EXISTS (
                        SELECT 1 
                        FROM QuotationMaster q 
                        WHERE r.InquiryId = q.EnquiryId
                    ) and year(r.created) = '" + year + "' ORDER BY r.Created ASC;";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetPendingQuotations(string year)
        {
            string sQuery = @"
                         SELECT top 5
                                q.QuotationNumber,
                                q.QuotationDate,
                                c.CompanyName,
                                q.GrandTotal
                            FROM QuotationMaster q
                            INNER JOIN CompanyDetails c ON q.CustomerMasterID = c.CustomerMasterId
                            WHERE q.PONumber IS NULL and year(QuotationDate)='" + year + "'" +
                            @" ORDER BY q.GrandTotal DESC;";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetSalesPie(string year)
        {
            string sQuery = @"
                       SELECT 
                                d.DeptCode,
                                SUM(q.GrandTotal) AS TotalRevenue
                            FROM QuotationMaster q
                            inner join CustomerInquiry  ci on ci.InquiryId = q.EnquiryId
                            inner JOIN EmployeeDepartment d ON ci.DepartmentId = d.DepartmentID
                            WHERE q.PONumber IS NOT NULL and year(QuotationDate)='" + year + "'" +
                            @" GROUP BY d.DeptCode
                            ORDER BY SUM(q.GrandTotal) DESC;";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetResultOverallConclusion_ToysAndBabyWear(string sampleId)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT ROW_NUMBER() OVER (ORDER BY tp.TestParameter) AS [No.],tp.TestParameter AS [Test Parameters], MAX(c.TestMethod) AS [Test Method],MAX(c.Requirement) AS [Requirement],
                                 CASE 
                                   WHEN COUNT(DISTINCT t.Conclusion) = 1 THEN MAX(t.Conclusion) WHEN SUM(CASE WHEN t.Conclusion = 'FAIL' THEN 1 ELSE 0 END) > 0 THEN 'FAIL' ELSE MAX(t.Conclusion)
                                 END AS [Results]
                               FROM crfsampledetails c
                               LEFT JOIN TestResults t ON c.crfsampleid = t.crfsampleid
                               LEFT JOIN TestParameter tp ON tp.TestParameterID = c.TestParameterID
                               WHERE t.sampleID = @SampleId GROUP BY tp.TestParameter";

            using (SqlConnection conn = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, conn))
                {
                    conn.Open();
                    cmd.Parameters.AddWithValue("@SampleId", sampleId);
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }
            return dt;
        }
        public DataTable GetResultOverallConclusion_BH_ToysAndBabyWear(string sampleId)
        {
            DataTable dt = new DataTable();

            string sQuery = @"SELECT ROW_NUMBER() OVER (ORDER BY tp.TestParameter_BH) AS [No.], tp.TestParameter_BH AS [Parameter Uji],
                               MAX(c.TestMethod) AS [Metode Uji], MAX(c.Requirement) AS [Requirement],
                                CASE 
                                    WHEN COUNT(DISTINCT t.Conclusion_BH) = 1 THEN MAX(t.Conclusion_BH)
                                    WHEN SUM(CASE WHEN t.Conclusion_BH = 'TIDAK LULUS' THEN 1 ELSE 0 END) > 0 THEN 'TIDAK LULUS'
                                    ELSE MAX(t.Conclusion_BH)
                                END AS [Hasil Uji]
                              FROM crfsampledetails c
                              LEFT JOIN TestResults t ON c.crfsampleid = t.crfsampleid
                              LEFT JOIN TestParameter tp ON tp.TestParameterID = c.TestParameterID
                              WHERE t.sampleID = @SampleId GROUP BY tp.TestParameter_BH";

            using (SqlConnection conn = new SqlConnection(System.Web.Configuration.WebConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, conn))
                {
                    conn.Open();
                    cmd.Parameters.AddWithValue("@SampleId", sampleId);
                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }
            return dt;
        }
        public DataTable GetLabStatus1(string year)
        {
            DataTable dt = new DataTable();
            sQuery = @"SELECT 
                            d.EmployeeDepartmentName,

                            COUNT(DISTINCT ci.InquiryID) AS Enquiries,

                            COUNT(DISTINCT sd.SampleID) AS Samples,

                            COUNT(DISTINCT CASE WHEN sd.SampleStatus = 19
                                THEN sd.SampleID END) AS Allocated,

                            COUNT(DISTINCT CASE WHEN sd.samplestatus=27
                                THEN tr.TestResultID END) AS Tested,

                            COUNT(DISTINCT CASE WHEN sd.samplestatus=24 
                                THEN tr.TestResultID END) AS ReportReady

                        FROM EmployeeDepartment d

                        LEFT JOIN customerinquiry ci ON ci.DepartmentID = d.DepartmentID
                        left join CRFCloneList c on c.enquiryid=ci.inquiryid
                        LEFT JOIN SampleDetails sd ON sd.id = c.sampleID
                        LEFT JOIN testresultdetails tr  ON tr.SampleId = sd.SampleID
                        inner join Department d1 on d1.DepartmentID = d.DepartmentID 
                        where divisionID=3 and year(ci.Created)= '" + year + "'" +
                        @" GROUP BY d.EmployeeDepartmentName
                        ORDER BY d.EmployeeDepartmentName";
            return GetDataUsingQuery(sQuery);

        }
