        public int TestResultsAdd_Flateware_RP(int clauseID, string testDate, string testCompletationDate, string remark, int sampleId,
string sampleIdSeries, string inputType, string language, int reportID, string equipmentIds, string workOrderNo,
string productName, string productBrand, string productModel, string standardID, string standardName, string testMethod, string temperature,
    string humidity,
string[] ReportParamMap, string[] Result)
        {
            int modified = 0;
            try
            {

                string GetDateTime = DateTime.Today.ToString("dd-MMM-yyyy") + " " + DateTime.Now.ToString("h:mm:ss tt");

                // Start Reseed to avoid identity jump
                int prevIdentity = GetReseedIdentity("TestResultsLED", "ResultID");
                ReseedIdentity("TestResultsLED", prevIdentity);
                // End Reseed to avoid identity jump

                string sQuery = @"INSERT INTO TestResultsLED 
                              (ClauseID, TestDate,TestCompletationDate, Result, Remark, SampleID, SampleIDSeries, InputType, Language, 
                               ReportID, ReportParamMapID, EquipmentIds, CreatedDateTime, WorkOrderNo, ProductName, ProductBrand, 
                               ProductModel, StandardID, StandardName, TestMethod,Temperature, Humidity)
                              output INSERTED.ResultID values
                              (@ClauseID, @TestDate, @TestCompletationDate, @Result, @Remark, @SampleID, @SampleIDSeries, @InputType, @Language, 
                               @ReportID, @ReportParamMapID, @EquipmentIds, @CreatedDateTime, @WorkOrderNo, @ProductName, @ProductBrand, 
                               @ProductModel, @StandardID, @StandardName, @TestMethod,@Temperature, @Humidity)";
                using (SqlConnection _sCon = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                    {
                        for (int i = 0; i < ReportParamMap.Length; i++)
                        {
                            cmd.Parameters.AddWithValue("@ReportParamMapID", ReportParamMap[i]);
                            cmd.Parameters.AddWithValue("@Result", Result[i]);

                            cmd.Parameters.AddWithValue("@ClauseID", 0);
                            cmd.Parameters.AddWithValue("@TestDate", testDate);
                            cmd.Parameters.AddWithValue("@TestCompletationDate", testCompletationDate);
                            cmd.Parameters.AddWithValue("@Remark", remark ?? "");
                            cmd.Parameters.AddWithValue("@SampleID", sampleId);
                            cmd.Parameters.AddWithValue("@SampleIDSeries", sampleIdSeries);
                            cmd.Parameters.AddWithValue("@InputType", inputType);
                            cmd.Parameters.AddWithValue("@Language", language);
                            cmd.Parameters.AddWithValue("@ReportID", reportID);
                            cmd.Parameters.AddWithValue("@EquipmentIds", equipmentIds);
                            cmd.Parameters.AddWithValue("@CreatedDateTime", GetDateTime);
                            cmd.Parameters.AddWithValue("@WorkOrderNo", workOrderNo);
                            cmd.Parameters.AddWithValue("@ProductName", productName);
                            cmd.Parameters.AddWithValue("@ProductBrand", productBrand);
                            cmd.Parameters.AddWithValue("@ProductModel", productModel);
                            cmd.Parameters.AddWithValue("@StandardName", standardName);
                            cmd.Parameters.AddWithValue("@TestMethod", testMethod);
                            cmd.Parameters.AddWithValue("@Temperature", temperature);
                            cmd.Parameters.AddWithValue("@Humidity", humidity);
                            cmd.Parameters.AddWithValue("@StandardID", standardID);

                            try
                            {
                                _sCon.Open();
                                modified = (int)cmd.ExecuteScalar();
                            }
                            catch (Exception ex)
                            {
                                string s = ex.Message;
                            }

                            if (_sCon.State == ConnectionState.Open)
                                _sCon.Close();

                            modified++;
                        }
                    }
                }
            }
            catch (SqlException ex)
            {
                // Log the error or handle it appropriately
                Console.WriteLine($"SQL Error: {ex.Message}");
                // 
            }
            catch (Exception ex)
            {
                // Log the error or handle it appropriately
                Console.WriteLine($"Error: {ex.Message}");
                // You might want to throw the exception again or handle it based on your application's error handling strategy
            }

            return modified;
        }

