        public DataTable GetCustomerEnquiryWithSampleDetails_Flatware(int sampleID, int reportID, string standardID)
        {
            DataTable dt = new DataTable();

            // Split the standardID string into individual values and trim each one
            string[] standardIds = standardID.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
                                             .Select(id => id.Trim())
                                             .ToArray();

            // Handle both single and multiple standard IDs
            string standardIdCondition;
            if (standardIds.Length == 1)
            {
                standardIdCondition = "csd.TestStandardID = '" + standardIds[0] + "'";
            }
            else
            {
                string quotedStandardIds = string.Join(",", standardIds.Select(id => "'" + id + "'"));
                standardIdCondition = "csd.TestStandardID IN (" + quotedStandardIds + ")";
            }

            string sQuery = @"SELECT * FROM SampleDetails sd 
                      INNER JOIN crfclonelist c ON c.sampleid = sd.id  
                      INNER JOIN CustomerInquiry ci ON ci.InquiryId = c.EnquiryID
                      INNER JOIN AdditionalDetails ad ON ad.InquiryID = c.EnquiryID
                      INNER JOIN InquiryStatus st ON st.InquiryStatusId = c.CRFStatusID 
                      INNER JOIN CRFSampleDetails csd ON csd.InquiryId = c.EnquiryID
                      WHERE sd.id = " + sampleID +
                              " AND csd.ReportID = " + reportID +
                              " AND " + standardIdCondition;

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetExistingTestResults_Flatware_RP(string sampleId, string reportId)
        {
            Dictionary<string, string> parameterResults = new Dictionary<string, string>();

            try
            {
                using (SqlConnection conn = new SqlConnection(ConfigurationManager.ConnectionStrings["CM"].ConnectionString))
                {
                    conn.Open();
                    string query = @"SELECT * FROM TestResultsLED WHERE SampleID = @SampleID AND ReportID = @ReportID AND ClauseID = 0";

                    using (SqlCommand cmd = new SqlCommand(query, conn))
                    {
                        cmd.Parameters.AddWithValue("@SampleID", sampleId);
                        cmd.Parameters.AddWithValue("@ReportID", reportId);

                        using (SqlDataReader reader = cmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string paramId = reader["ReportParamMapID"].ToString();
                                string result = reader["Result"].ToString();
                                parameterResults[paramId] = result;
                            }
                        }
                    }
                }

                DataTable dt = new DataTable();
                dt.Columns.Add("ParameterID", typeof(string));
                dt.Columns.Add("Result", typeof(string));

                foreach (var param in parameterResults)
                {
                    dt.Rows.Add(param.Key, param.Value);
                }

                return dt;
            }
            catch (Exception ex)
            {
                //ScriptManager.RegisterStartupScript(this, GetType(), "DataFetchError",
                //  $"alert('Error fetching existing data: {ex.Message}');", true);
                return null;
            }
        }
