       string sampleIdSeries, string inputType, string language, int reportID, int reportParamMapID, string equipmentIds, string workOrderNo,
       string productName, string productBrand, string productModel, string standardID, string standardName, string testMethod,
       string TestCategory, string sampleCode, string TestEquipmentNo, string temperature, string humidity, string unit, string coatingmaterial, string Form, string typeofmaterial, string Typesofproducts,
       string SerialNo)
        {
            int modified = 0;


            //Start Reseed to avoid identity jump
            int prevIdentity = GetReseedIdentity("TestResultsLED", "ResultID");
            ReseedIdentity("TestResultsLED", prevIdentity);
            //End Reseed to avoid identity jump

            string GetDateTime = DateTime.Today.ToString("dd-MMM-yyyy") + " " + DateTime.Now.ToString("h:mm:ss tt");

            string sQuery = @"INSERT INTO TestResultsLED 
                              (ClauseID, TestDate,TestCompletationDate, Result, Remark, Remark_BH, SampleID, SampleIDSeries, InputType, Language, 
                               ReportID, ReportParamMapID, EquipmentIds, CreatedDateTime, WorkOrderNo, ProductName, ProductBrand, 
                               ProductModel, StandardID, StandardName, TestMethod,Specification, Specification_BH,
                               TestCategory,  SampleCode,  TestEquipmentNumber, Temperature, Humidity,UnitName,Typesofproducts,serialNO,coatingmaterial,Form,typeofmaterial)
                              output INSERTED.ResultID values
                              (@ClauseID, @TestDate, @TestCompletationDate, @Result, @Remark, @Remark_BH, @SampleID, @SampleIDSeries, @InputType, @Language, 
                               @ReportID, @ReportParamMapID, @EquipmentIds, @CreatedDateTime, @WorkOrderNo, @ProductName, @ProductBrand, 
                               @ProductModel, @StandardID, @StandardName, @TestMethod, @Specification, @Specification_BH,
                               @TestCategory,  @SampleCode,  @TestEquipmentNumber,@Temperature, @Humidity ,@UnitName,@Typesofproducts,@serialNO,@coatingmaterial,@Form,@typeofmaterial)";

            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sQuery, _sCon))
                {
                    cmd.Parameters.AddWithValue("@ClauseID", clauseID);
                    cmd.Parameters.AddWithValue("@TestDate", testDate);
                    cmd.Parameters.AddWithValue("@TestCompletationDate", testCompletationDate);
                    cmd.Parameters.AddWithValue("@Result", result);
                    cmd.Parameters.AddWithValue("@Remark", specification ?? "");
                    cmd.Parameters.AddWithValue("@Remark_BH", specification_BH ?? "");
                    cmd.Parameters.AddWithValue("@Specification", specification ?? "");
                    cmd.Parameters.AddWithValue("@Specification_BH", specification_BH ?? "");
