                    cmd.Parameters.AddWithValue("@TestMethod", testMethod);
                    cmd.Parameters.AddWithValue("@Temperature", temperature);
                    cmd.Parameters.AddWithValue("@Humidity", humidity);
                    cmd.Parameters.AddWithValue("@StandardID", standardID);
                    cmd.Parameters.AddWithValue("@UnitName", unit);
                    cmd.Parameters.AddWithValue("@coatingmaterial", coatingmaterial);

