        public DataTable GetFinalTAFData(int inquiryID, int cloneID)
        {
            DataTable dt = new DataTable();
            using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["CM"].ConnectionString))
            {
                string query = @"
                                   SELECT 
                                cs.InquiryId, 
                                cs.CRFSampleID, 
                                cs.CustomerRequestID, 
                                cs.SampleName, 
                                cs.SampleType,
                                cs.BatchNo, 
                                cs.WorkorderNumber, 
                                qm.QuotationNumber,td.TestReportNo,s.sampleIDSeries
                            ,
                                s.Remarks AS SampleCondition,s.receiver,td.DateOfMfg,td.DateOfExp,
                                FORMAT(s.ReceivedDate, 'dd-MM-yyyy') AS SubmissionOfSample

                            FROM CRFSampleDetails cs
                            INNER JOIN CustomerInquiry ci ON ci.InquiryId = cs.InquiryId
                            INNER JOIN additionaldetails ad ON ad.InquiryID = ci.InquiryId
                            INNER JOIN CRFCloneList cl ON cl.CloneCRFSampleID = cs.CloneCRFSampleID
                            INNER JOIN QuotationMaster qm ON qm.EnquiryId = ci.InquiryId
                            LEFT JOIN QuotationDetails qd ON qd.QuotationMasterID = qm.QuotationMasterID
                            INNER JOIN SampleDetails s ON s.ID = cl.sampleID
                            LEFT JOIN TestResults t ON t.CRFSampleID = cs.CRFSampleID
                            LEFT JOIN TestResultDetails td ON td.SampleID = s.ID
            WHERE cs.InquiryId = @InquiryID and cs.CloneCRFSampleID = @CloneCRFSampleID";

                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue("@InquiryID", inquiryID);
                    cmd.Parameters.AddWithValue("@CloneCRFSampleID", cloneID);
                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    da.Fill(dt);
                }
            }
            return dt;
        }
        public int AddCRFSampleDetails_Battery(DAL.CM obj)
        {
            int modified = 0;
            int prevIdentity = GetReseedIdentity("CRFSampleDetails", "CRFSampleId");
            ReseedIdentity("CRFSampleDetails", prevIdentity);

            string sQuery = @"INSERT INTO CRFSampleDetails 
                  (CloneCRFSampleID, InquiryId, CustomerRequestId, CustomerId, SampleName, SampleType, BatchNo, TestMethod, 
                   ReportID, ReportName, SizeOfSample, Remarks, Created, CRFID, OrganizationID,TestStandard,TestStandardID) 
                  VALUES 
                  (@CloneCRFSampleID, @InquiryId, @CustomerRequestId, @CustomerId, @SampleName, @SampleType, @BatchNo, @TestMethod, 
                   @ReportId, @ReportName, @SizeOfSample, @Remarks, @Created, @CRFID, @OrganizationID,@TestStandard,@TestStandardID)";

            using (SqlConnection con = new SqlConnection(cs))
            using (SqlCommand cmd = new SqlCommand(sQuery, con))
            {
                try
                {
                    cmd.Parameters.AddWithValue("@CloneCRFSampleID", obj.CloneCRFSampleID);
                    cmd.Parameters.AddWithValue("@InquiryId", obj.inquiryId);
                    cmd.Parameters.AddWithValue("@CustomerRequestId", obj.customerRequestId);
                    cmd.Parameters.AddWithValue("@CustomerId", obj.customerId);
                    cmd.Parameters.AddWithValue("@SampleName", obj.sampleName);
                    cmd.Parameters.AddWithValue("@SampleType", obj.SampleType);
                    cmd.Parameters.AddWithValue("@BatchNo", obj.batchNo);
                    cmd.Parameters.AddWithValue("@TestMethod", obj.testMethod);
                    cmd.Parameters.AddWithValue("@ReportID", obj.ReportID);
                    cmd.Parameters.AddWithValue("@ReportName", obj.ReportName);
                    cmd.Parameters.AddWithValue("@SizeOfSample", obj.sizeOfSample);
                    cmd.Parameters.AddWithValue("@Remarks", obj.remarks);
                    cmd.Parameters.AddWithValue("@CRFID", obj.CRFID);
                    cmd.Parameters.AddWithValue("@Created", DateTime.Now);
                    cmd.Parameters.AddWithValue("@OrganizationID", obj.OrganizationID);
                    cmd.Parameters.AddWithValue("@TestStandard", obj.TestStandardName);
                    cmd.Parameters.AddWithValue("@TestStandardID", obj.TestStandardID);

                    con.Open();
                    cmd.ExecuteScalar();
                    modified = 1;
                }
                catch (Exception ex)
                {
                    string s = ex.Message;
                }
            }

            return modified;
        }

