        public bool UpdateQRCodeNumbers(int sampleId, string qrCodeNumber, string qrCodeNumberBH, int revisionCount)
        {
            try
            {
                string query = @"UPDATE TestResultDetails SET QR_CodeNumber = @QRCodeNumber, QR_CodeNumber_BH = @QRCodeNumberBH, RevisionCount = @RevisionCount
                                 WHERE SampleId = @SampleId";

                using (SqlConnection conn = new SqlConnection(cs))
                using (SqlCommand cmd = new SqlCommand(query, conn))
                {
                    cmd.Parameters.AddWithValue("@SampleId", sampleId);
                    cmd.Parameters.AddWithValue("@RevisionCount", revisionCount);
                    cmd.Parameters.AddWithValue("@QRCodeNumber", string.IsNullOrEmpty(qrCodeNumber) ? (object)DBNull.Value : qrCodeNumber);
                    cmd.Parameters.AddWithValue("@QRCodeNumberBH", string.IsNullOrEmpty(qrCodeNumberBH) ? (object)DBNull.Value : qrCodeNumberBH);

                    conn.Open();
                    int rowsAffected = cmd.ExecuteNonQuery();
                    return rowsAffected > 0;
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"Error updating QR codes: {ex.Message}");
                return false;
            }
        }
        public DataTable getAllSamplesForEmailReport(int year, int month, string DepartmentID)
        {
            DataTable dt = new DataTable();
            string sQuery = @"SELECT distinct sd.ID, sd.sampleidseries, sd.SampleID, cr.CloneCRFSampleID, sd.sampleidSeries AS labid, sd.ReceivedDate, 
                                              ISNULL(trd.TestReportNo, '') AS TestReportNo, cd.CompanyName AS CustomerName, i.StatusName,sd.samplestatus,
                                              trd.IsEmailSent
                               FROM SampleDetails sd
                               INNER JOIN CRFCloneList cr ON cr.sampleID = sd.ID
                               INNER JOIN CustomerInquiry ci ON ci.InquiryId = cr.EnquiryID
                               INNER JOIN CompanyDetails cd ON cd.CustomerMasterId = ci.CustomerMasterId
                               INNER JOIN InquiryStatus i ON i.InquiryStatusID = sd.SampleStatus
                               LEFT JOIN TestResultDetails trd ON trd.SampleId = sd.ID
                               WHERE sd.samplestatus = 29 AND ci.departmentid= '" + DepartmentID + "'" +
                            @"   AND sd.OrganizationID = " + HttpContext.Current.Session["OrganizationID"].ToString() + @"
                                 AND YEAR(sd.Created) = " + year + @"
                                 AND MONTH(sd.Created) = " + month + @"
                               ORDER BY sd.ID DESC";

            dt = GetDataUsingQuery(sQuery);
            return dt;

        }
