        public int GetTemplateID(string transactionType, string payeeType)
        {
            string sql = @"SELECT TOP 1 TemplateID
                   FROM JournalTemplateMaster
                   WHERE TransactionType='Payment'
                     AND PayeeType=@PayeeType
                     AND HasWithholdingTax=@HasWHT
                     AND IsActive=1
                   ORDER BY Priority";

            SqlParameter[] param =
            {
                new SqlParameter("@TransactionType", transactionType),
                new SqlParameter("@PayeeType", payeeType)
            };

            object obj = DbHelper.ExecuteQuery(sql, param);

            if (obj == null)
                throw new Exception("Journal Template not found.");

            return Convert.ToInt32(obj);
        }
