        public string GetSignature(int userId, string documentType)
        {
            string signature = "~/Images/no-signature.png";

            string connString = ConfigurationManager.ConnectionStrings["CM"].ConnectionString;

            using (SqlConnection con = new SqlConnection(connString))
            using (SqlCommand cmd = new SqlCommand(
                @"SELECT SignaturePath
          FROM UserSignature
          WHERE UserID=@UserID
            AND DocumentType=@DocumentType
            AND IsActive=1", con))
            {
                cmd.Parameters.AddWithValue("@UserID", userId);
                cmd.Parameters.AddWithValue("@DocumentType", documentType);

                con.Open();

                object obj = cmd.ExecuteScalar();

                if (obj != null && obj != DBNull.Value)
                    signature = obj.ToString();
            }

            return signature;
        }
