            string sQuery = @"SELECT DISTINCT ci.InquiryId,TestReportNo,cd.CompanyName AS [Applicant],(Title + ' ' + FirstName + ' ' + LastName) AS Attention,ctd.Email,
                        CONCAT_WS(', ', NULLIF(Addressline1, ''), NULLIF(Addressline2, ''), NULLIF(AddressLine3, ''), NULLIF(city, ''), NULLIF(pincode, ''), NULLIF(country, '') ) AS Address,
                        samplename AS [SampleDescription],SampleCondition AS [SampleCondition],CreatedDate AS [Date],AnalysisStartingDate AS [TestSample],AnalysisCompletionDate AS [TestPeriod],
                        IssueDate,ColorName_Code AS [ColorName_Code],MaterialName_Code AS [MaterialName_Code],ad.BuyerCustomerName AS [Buyer'sName],ad.AgeGroup AS [AgeGroup],
                        ad.PONo AS [PONo],ad.Suppliername,BatchNo,ad.CountryOrigin AS [CountryofOrigin],ad.CountryDestination AS [CountryOfDestination],InquiryDetail AS [TestPackage],
                        BrandProduct,ProductGroupName,cf.Remarks AS [Remark],ad.ProductType AS [ProductType],FactoryName,FactoryAddress,ad.PersonID,CountryOrigin,DateOfExp,BrandProduct,
                        AgeGroup,ArticleNumber,Suppliername,FactoryName,FactoryAddress,LotNumber,MaterialType,ItemStyleNo,MaterialName_Code,ColorName_Code,pg.ProductGroupName,ad.LotNumber,
                        ad.BuyerCustomerName,ad.MaterialName_Code,ci.Remarks,sd.sampleIDSeries,a.TypeDescription,a.GroupOfProduct,a.DescriptionOfProduct,a.Remark as [GetRemarks],
                        t.FinalTestResult as FinalTestResult,ad.ProductName,ad.ProductSerialNo,ad.ProductSpecification,ad.Color,cf.WorkorderNumber as WorkorderNumber,
                        (SELECT STRING_AGG(cf2.TestMethod, ', ') FROM crfsampledetails cf2 WHERE cf2.clonecrfsampleid = c.clonecrfsampleid) AS TestMethod,
                        t.AuthorizedSignatoryID, e.EmployeeName AS [LabHeadName], ci.RequestNo
                        FROM testresultdetails t
                        INNER JOIN crfclonelist c ON c.sampleid = t.SampleId
                        INNER JOIN customerinquiry ci ON ci.inquiryid = c.enquiryid
                        LEFT JOIN ProductGroup pg ON pg.ProductGroupID = ci.productCategoryID
                        LEFT JOIN CompanyDetails cd ON cd.customermasterid = ci.customermasterid
                        INNER JOIN LocationDetails lo ON lo.customermasterid = ci.customermasterid 
                        INNER JOIN crfsampledetails cf ON cf.clonecrfsampleid = c.clonecrfsampleid
                        INNER JOIN AdditionalDetails ad ON ad.InquiryID = ci.InquiryId
                        INNER JOIN ContactPersonDetails cpd ON ad.PersonID = cpd.PersonId
                        LEFT JOIN ContactDetails ctd ON ctd.PersonId = cpd.PersonId
                        INNER JOIN SampleDetails sd ON sd.ID = t.SampleId
                        LEFT JOIN AdditionTypeDataForK3L a ON a.SampleIdForType = t.SampleId
                        INNER JOIN Employees e ON e.ID = t.AuthorizedSignatoryID
                     WHERE t.SampleId = '" + sampleId + "' ";

            dt = GetDataUsingQuery(sQuery);
            return dt;
        }
        public DataTable GetJournalLines(long paymentRequisitionDetailsID)
        {
            DataTable dt = new DataTable();

            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand("sp_GetJournalLines", conn))
                {
                    cmd.CommandType = CommandType.StoredProcedure;

                    cmd.Parameters.Add(
                        "@PaymentRequisitionDetailsID",
                        SqlDbType.BigInt).Value =
                        paymentRequisitionDetailsID;

                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }

            return dt;
