        public void DeleteJournalLine(long journalLineID)
        {
            string sql = @"
                            DELETE FROM JournalLines
                            WHERE LineID = @JournalLineID";

            SqlParameter[] parameters =
            {
                new SqlParameter(
                    "@JournalLineID",
                    journalLineID)
            };

            DbHelper.ExecuteNonQuery(sql, parameters);
        }
        public int GetNextJournalSequence(long journalID)
        {
            int nextSequence = 1;

            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(@"
            SELECT ISNULL(MAX(SequenceNo), 0) + 1
            FROM JournalLines
            WHERE JournalID = @JournalID",
                    conn))
                {
                    cmd.Parameters.Add(
                        "@JournalID",
                        SqlDbType.BigInt).Value = journalID;

                    conn.Open();

                    object result = cmd.ExecuteScalar();

                    if (result != null && result != DBNull.Value)
                    {
                        nextSequence = Convert.ToInt32(result);
                    }
                }
            }

            return nextSequence;
        }
        public long CreatePaymentJournalHeader(long detailsID, string createdBy)
        {
            long journalID = 0;

            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(@"
            INSERT INTO JournalHeader
            (
                JournalDate,
                ReferenceNo,
                Description,
                CreatedOn,
                CreatedBy,
                Posted,
                Txn,
                VoucherType,
                ReferenceType,
                ReferenceID,
                Narration,
                TotalDebit,
                TotalCredit,
                SourceID
            )
            VALUES
            (
                GETDATE(),
                @ReferenceNo,
                @Description,
                GETDATE(),
                @CreatedBy,
                0,
                'Payment',
                NULL,
                'PaymentRequisition',
                @ReferenceID,
                NULL,
                0,
                0,
                @SourceID
            );

            SELECT CAST(SCOPE_IDENTITY() AS BIGINT);
        ", conn))
                {
                    cmd.Parameters.Add(
                        "@ReferenceNo",
                        SqlDbType.NVarChar, 100).Value =
                        GetPaymentReferenceNo(detailsID);

                    cmd.Parameters.Add(
                        "@Description",
                        SqlDbType.NVarChar, 500).Value =
                        "Payment Requisition";

                    cmd.Parameters.Add(
                        "@CreatedBy",
                        SqlDbType.NVarChar, 100).Value =
                        createdBy ?? "System";

                    cmd.Parameters.Add(
                        "@ReferenceID",
                        SqlDbType.BigInt).Value =
                        detailsID;

                    cmd.Parameters.Add(
                        "@SourceID",
                        SqlDbType.BigInt).Value =
                        detailsID;

                    conn.Open();

                    object result = cmd.ExecuteScalar();

                    if (result != null && result != DBNull.Value)
                    {
                        journalID = Convert.ToInt64(result);
                    }
                }
            }

            return journalID;
        }
        public string GetPaymentReferenceNo(long detailsID)
        {
            string referenceNo = "";

            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(@"
                            SELECT TOP 1 PR.RequisitionNumber
                            FROM PaymentRequisitionDetails PRD
                            INNER JOIN PaymentRequisitionMaster PR
                                ON PR.PaymentRequisitionID = PRD.PaymentRequisitionID
                            WHERE PRD.PaymentRequisitionDetailsID = @DetailsID
                        ", conn))
                {
                    cmd.Parameters.Add(
                        "@DetailsID",
                        SqlDbType.BigInt).Value = detailsID;

                    conn.Open();

                    object result = cmd.ExecuteScalar();

                    if (result != null && result != DBNull.Value)
                    {
                        referenceNo = result.ToString();
                    }
                }
            }

            return referenceNo;
        }
        public long GetJournalIDForPayment(long detailsID)
        {
            long journalID = 0;

            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(@"
                                            SELECT TOP 1 JournalID
                                            FROM JournalHeader
                                            WHERE ReferenceType = 'PaymentRequisition'
                                              AND ReferenceID = @DetailsID
                                            ORDER BY JournalID DESC",
                    conn))
                {
                    cmd.Parameters.Add(
                        "@DetailsID",
                        SqlDbType.BigInt).Value = detailsID;

                    conn.Open();

                    object result = cmd.ExecuteScalar();

                    if (result != null && result != DBNull.Value)
                    {
                        journalID = Convert.ToInt64(result);
                    }
                }
            }

            return journalID;
        }
        public long AddJournalLine(
                                    long journalID,
                                    long sourceDetailID,
                                    int sequenceNo)
        {
            long journalLineID = 0;

            using (SqlConnection conn = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(@"
            INSERT INTO JournalLines
            (
                JournalID,
                SequenceNo,
                SourceDetailID
            )
            VALUES
            (
                @JournalID,
                @SequenceNo,
                @SourceDetailID
            );

            SELECT CAST(SCOPE_IDENTITY() AS BIGINT);",
                    conn))
                {
                    cmd.Parameters.Add(
                        "@JournalID",
                        SqlDbType.BigInt).Value = journalID;

                    cmd.Parameters.Add(
                        "@SequenceNo",
                        SqlDbType.Int).Value = sequenceNo;

                    cmd.Parameters.Add(
                        "@SourceDetailID",
                        SqlDbType.BigInt).Value = sourceDetailID;

                    conn.Open();

                    journalLineID =
                        Convert.ToInt64(cmd.ExecuteScalar());
                }
            }

            return journalLineID;
        }
        public void UpdateJournalLine(
                        long journalLineID,
                        long accountID,
                        string description,
                        decimal debit,
                        decimal credit)
        {
            using (SqlConnection conn =
                new SqlConnection(cs))
            {
                using (SqlCommand cmd =
                    new SqlCommand(@"
                UPDATE JournalLines
                SET
                    AccountID = @AccountID,
                    LineDescription = @Description,
                    Debit = @Debit,
                    Credit = @Credit
                WHERE LineID = @JournalLineID",
                        conn))
                {
                    cmd.Parameters.Add(
                        "@JournalLineID",
                        SqlDbType.BigInt).Value =
                        journalLineID;

                    cmd.Parameters.Add(
                        "@AccountID",
                        SqlDbType.BigInt).Value =
                        accountID;

                    cmd.Parameters.Add(
                        "@Description",
                        SqlDbType.NVarChar, 500).Value =
                        (object)description ?? DBNull.Value;

                    cmd.Parameters.Add(
                        "@Debit",
                        SqlDbType.Decimal).Value =
                        debit;

                    cmd.Parameters.Add(
                        "@Credit",
                        SqlDbType.Decimal).Value =
                        credit;

                    conn.Open();

                    cmd.ExecuteNonQuery();
                }
            }
        }
        public void UpdateJournalTotals(
                            long detailsID,
                            decimal totalDebit,
                            decimal totalCredit)
        {
            using (SqlConnection conn =
                new SqlConnection(cs))
            {
                using (SqlCommand cmd =
                    new SqlCommand(@"
                UPDATE JournalHeader
                SET
                    TotalDebit = @TotalDebit,
                    TotalCredit = @TotalCredit
                WHERE ReferenceID =
                      @PaymentRequisitionDetailsID",
                        conn))
                {
                    cmd.Parameters.Add(
                        "@PaymentRequisitionDetailsID",
                        SqlDbType.BigInt).Value =
                        detailsID;

                    cmd.Parameters.Add(
                        "@TotalDebit",
                        SqlDbType.Decimal).Value =
                        totalDebit;

                    cmd.Parameters.Add(
                        "@TotalCredit",
                        SqlDbType.Decimal).Value =
                        totalCredit;

                    conn.Open();

                    cmd.ExecuteNonQuery();
                }
            }
        }

