        public void UpdateHighestApproval(DAL.CM obj)
        {
            string sql = @"
                    UPDATE PurchaseRequisition
                    SET HighestApprovalOrgTreeID = @HighestApprovalOrgTreeID
                    WHERE PRID = @PRID";
            using (SqlConnection _sCon = new SqlConnection(cs))
            {
                using (SqlCommand cmd = new SqlCommand(sql, _sCon))
                {
                    cmd.Parameters.AddWithValue(
                        "@HighestApprovalOrgTreeID",
                        obj.highestApprovalOrgTreeID);

                    cmd.Parameters.AddWithValue(
                        "@PRID",
                        obj.PRID);

                    _sCon.Open();
                    cmd.ExecuteNonQuery();
                    _sCon.Close();
                }
            }
        }
    }
